## Test Cases

```zig
test "serialize simple text frame" {
    var buffer: [2]u8 = undefined;
    const len = try serializeFrameHeader(&buffer, .{
        .opcode = .text,
        .payload_length = 5,
        .mask = false,
    }, null);

    try testing.expectEqual(@as(usize, 2), len);
    try testing.expectEqual(@as(u8, 0x81), buffer[0]); // FIN=1, text
    try testing.expectEqual(@as(u8, 0x05), buffer[1]); // len=5, no mask
}

test "serialize masked frame" {
    var buffer: [6]u8 = undefined;
    const key = [4]u8{ 0x12, 0x34, 0x56, 0x78 };
    const len = try serializeFrameHeader(&buffer, .{
        .opcode = .text,
        .payload_length = 5,
        .mask = true,
    }, key);

    try testing.expectEqual(@as(usize, 6), len);
    try testing.expectEqual(@as(u8, 0x85), buffer[1]); // mask bit set
    try testing.expectEqualSlices(u8, &key, buffer[2..6]);
}

test "serialize 16-bit length" {
    var buffer: [4]u8 = undefined;
    const len = try serializeFrameHeader(&buffer, .{
        .opcode = .binary,
        .payload_length = 1000,
        .mask = false,
    }, null);

    try testing.expectEqual(@as(usize, 4), len);
    try testing.expectEqual(@as(u8, 126), buffer[1] & 0x7F);
    try testing.expectEqual(@as(u16, 1000), std.mem.readInt(u16, buffer[2..4], .big));
}

test "round-trip serialization" {
    var buffer: [14]u8 = undefined;
    const original = FrameOptions{
        .opcode = .binary,
        .payload_length = 100000,
        .mask = false,
        .fin = true,
    };

    const written = try serializeFrameHeader(&buffer, original, null);
    const parsed = try parseFrameHeader(buffer[0..written], true);

    try testing.expectEqual(original.fin, parsed.header.fin);
    try testing.expectEqual(original.opcode, parsed.header.opcode);
    try testing.expectEqual(original.payload_length, parsed.header.payload_length);
}
```

