## Summary
Implement in-memory CORS preflight cache to avoid redundant OPTIONS requests.

## Spec Reference
- https://fetch.spec.whatwg.org/#cors-preflight-cache
- specs/whatwg/fetch.md (CORS-preflight cache section)

## Location
`src/fetch/cors/preflight_cache.zig`

## Requirements

### Preflight Cache Entry
```zig
/// CORS preflight cache entry.
pub const PreflightCacheEntry = struct {
    /// Cache key components
    key: CacheKey,

    /// Allowed methods
    methods: std.StringHashMap(void),

    /// Allowed headers (byte-lowercased)
    headers: std.StringHashMap(void),

    /// Expiry time (absolute timestamp)
    expiry_time: i64,

    /// Whether credentials are allowed
    credentials: bool,

    pub const CacheKey = struct {
        /// Origin of the request
        origin: []const u8,
        /// URL being requested
        url: []const u8,
        /// Byte-serialized request origin
        request_origin: []const u8,
    };
};
```

### Preflight Cache
```zig
/// In-memory CORS preflight cache.
///
/// Per spec, preflight results can be cached to avoid redundant OPTIONS.
/// Cache entries expire based on Access-Control-Max-Age.
pub const PreflightCache = struct {
    allocator: std.mem.Allocator,
    entries: std.ArrayList(PreflightCacheEntry),

    /// Maximum age for cache entries (default 5 seconds if not specified)
    default_max_age: u64 = 5,

    /// Upper bound on max age (implementation may cap this)
    max_max_age: u64 = 86400, // 24 hours

    pub fn init(allocator: std.mem.Allocator) PreflightCache {
        return .{
            .allocator = allocator,
            .entries = std.ArrayList(PreflightCacheEntry).init(allocator),
        };
    }

    pub fn deinit(self: *PreflightCache) void {
        for (self.entries.items) |*entry| {
            entry.methods.deinit();
            entry.headers.deinit();
        }
        self.entries.deinit();
    }

    /// Match cache entry for request.
    /// Returns entry if found and not expired.
    pub fn match(
        self: *PreflightCache,
        origin: []const u8,
        url: []const u8,
        request_origin: []const u8,
    ) ?*PreflightCacheEntry {
        const now = std.time.timestamp();

        for (self.entries.items) |*entry| {
            // Check expiry first
            if (entry.expiry_time < now) continue;

            // Check key match
            if (std.mem.eql(u8, entry.key.origin, origin) and
                std.mem.eql(u8, entry.key.url, url) and
                std.mem.eql(u8, entry.key.request_origin, request_origin))
            {
                return entry;
            }
        }
        return null;
    }

    /// Create cache entry from preflight response.
    pub fn createEntry(
        self: *PreflightCache,
        origin: []const u8,
        url: []const u8,
        request_origin: []const u8,
        max_age: u64,
        methods: []const []const u8,
        headers: []const []const u8,
        credentials: bool,
    ) !void {
        const now = std.time.timestamp();
        const capped_max_age = @min(max_age, self.max_max_age);

        var entry = PreflightCacheEntry{
            .key = .{
                .origin = try self.allocator.dupe(u8, origin),
                .url = try self.allocator.dupe(u8, url),
                .request_origin = try self.allocator.dupe(u8, request_origin),
            },
            .methods = std.StringHashMap(void).init(self.allocator),
            .headers = std.StringHashMap(void).init(self.allocator),
            .expiry_time = now + @intCast(i64, capped_max_age),
            .credentials = credentials,
        };

        for (methods) |method| {
            try entry.methods.put(try self.allocator.dupe(u8, method), {});
        }

        for (headers) |header| {
            // Store headers byte-lowercased
            const lower = try byteLowercase(self.allocator, header);
            try entry.headers.put(lower, {});
        }

        try self.entries.append(entry);
    }

    /// Check if method is allowed for cached entry.
    pub fn isMethodAllowed(entry: *PreflightCacheEntry, method: []const u8) bool {
        // Wildcard check
        if (entry.methods.contains("*") and !entry.credentials) {
            return true;
        }
        return entry.methods.contains(method);
    }

    /// Check if header is allowed for cached entry.
    pub fn isHeaderAllowed(entry: *PreflightCacheEntry, header: []const u8) bool {
        // Wildcard check
        if (entry.headers.contains("*") and !entry.credentials) {
            return true;
        }
        // Must byte-lowercase for comparison
        var buf: [256]u8 = undefined;
        const lower = std.ascii.lowerString(&buf, header);
        return entry.headers.contains(lower);
    }

    /// Clear cache entry for origin/URL.
    pub fn clear(
        self: *PreflightCache,
        origin: []const u8,
        url: []const u8,
    ) void {
        var i: usize = 0;
        while (i < self.entries.items.len) {
            const entry = &self.entries.items[i];
            if (std.mem.eql(u8, entry.key.origin, origin) and
                std.mem.eql(u8, entry.key.url, url))
            {
                // Free and remove
                entry.methods.deinit();
                entry.headers.deinit();
                _ = self.entries.orderedRemove(i);
            } else {
                i += 1;
            }
        }
    }

    /// Remove all expired entries.
    pub fn removeExpired(self: *PreflightCache) void {
        const now = std.time.timestamp();
        var i: usize = 0;
        while (i < self.entries.items.len) {
            if (self.entries.items[i].expiry_time < now) {
                var entry = self.entries.orderedRemove(i);
                entry.methods.deinit();
                entry.headers.deinit();
            } else {
                i += 1;
            }
        }
    }

    /// Clear entire cache.
    pub fn clearAll(self: *PreflightCache) void {
        for (self.entries.items) |*entry| {
            entry.methods.deinit();
            entry.headers.deinit();
        }
        self.entries.clearRetainingCapacity();
    }
};
```

