### Implementation Details

#### Update: `src/webidl/impls/TestUtils.zig`

```zig
//! Implementation for WebIDL namespace: TestUtils
//!
//! WHATWG TestUtils Standard: https://testutils.spec.whatwg.org/
//!
//! This namespace provides testing APIs that are only available when
//! built with `-Denable-test-utils=true`.
//!
//! ## WebIDL Definition
//! ```webidl
//! [Exposed=(Window,Worker)]
//! namespace TestUtils {
//!   [NewObject] Promise<undefined> gc();
//! };
//! ```

const std = @import("std");
const runtime = @import("runtime");
const build_options = @import("build_options");

// Conditionally import testutils module
const testutils = if (build_options.enable_test_utils)
    @import("testutils")
else
    struct {
        // Stub when TestUtils is disabled
        pub fn performGC(_: runtime.Context) !*anyopaque {
            return error.NotImplemented;
        }
    };

/// TestUtils.gc() - Trigger garbage collection
///
/// Per WHATWG TestUtils spec:
/// 1. Let p be a new promise.
/// 2. Run the following in parallel:
///    2.1. Run implementation-defined steps to perform a garbage collection
///         covering at least the entry Realm.
///    2.2. Resolve p.
///
/// ## Returns
/// Promise<undefined> - resolves after GC completes
///
/// ## Errors
/// - error.NotImplemented: TestUtils not enabled in build
/// - error.NotExposedInContext: Called from wrong context (not Window/Worker)
/// - error.NoEngine: No JS engine configured
/// - error.PromiseError: Failed to create Promise
pub fn call_gc(ctx: runtime.Context) anyerror!*const anyopaque {
    return testutils.performGC(ctx);
}
```

#### Update: `src/webidl/namespaces/TestUtils.zig`

Add conditional compilation wrapper:

```zig
//! WebIDL namespace: TestUtils
//!
//! This file is AUTO-GENERATED. Do not edit manually.
//!
//! Conditionally compiled based on enable_test_utils build option.

const build_options = @import("build_options");

pub usingnamespace if (build_options.enable_test_utils)
    @import("TestUtils_enabled.zig")
else
    // Empty namespace when disabled
    struct {
        pub const TestUtils = struct {
            pub const Meta = struct {
                pub const name = "TestUtils";
                pub const is_namespace = true;
                pub const is_disabled = true; // Marker for disabled
            };
        };
    };
```

Alternatively, keep the existing file but gate the impl:

```zig
//! WebIDL namespace: TestUtils
//!
//! This file is AUTO-GENERATED. Do not edit manually.

const runtime = @import("runtime");
const build_options = @import("build_options");

const TestUtils_impl = if (build_options.enable_test_utils)
    @import("impls").TestUtils
else
    struct {
        pub fn call_gc(_: runtime.Context) anyerror!*const anyopaque {
            return error.NotImplemented;
        }
    };

pub const TestUtils = struct {
    pub const Meta = struct {
        pub const name = "TestUtils";
        pub const is_namespace = true;
        pub const BaseType = ?*anyopaque;
        pub const MixinTypes = &.{};

        pub const methods = .{
            .{ "gc", "call_gc" },
        };

        pub const has_constructor = false;
        pub const properties = .{};

        /// Whether TestUtils is enabled in this build
        pub const is_enabled = build_options.enable_test_utils;
    };

    pub const State = struct {};

    pub fn call_gc(ctx: runtime.Context) anyerror!*const anyopaque {
        return try TestUtils_impl.call_gc(ctx);
    }
};
```

