### 4. Shared Cookie Tests
```zig
test "shared handle shares cookies between easy handles" {
    // Create share handle
    const share = c.curl_share_init().?;
    defer _ = c.curl_share_cleanup(share);
    _ = c.curl_share_setopt(share, c.CURLSHOPT_SHARE, c.CURL_LOCK_DATA_COOKIE);

    // Create two easy handles sharing cookies
    const curl1 = c.curl_easy_init().?;
    defer c.curl_easy_cleanup(curl1);
    const curl2 = c.curl_easy_init().?;
    defer c.curl_easy_cleanup(curl2);

    // Attach share handle
    _ = c.curl_easy_setopt(curl1, c.CURLOPT_SHARE, share);
    _ = c.curl_easy_setopt(curl2, c.CURLOPT_SHARE, share);

    // Enable cookie engine on both
    _ = c.curl_easy_setopt(curl1, c.CURLOPT_COOKIEFILE, "");
    _ = c.curl_easy_setopt(curl2, c.CURLOPT_COOKIEFILE, "");

    // Add cookie via curl1
    _ = c.curl_easy_setopt(curl1, c.CURLOPT_COOKIELIST, 
        "Set-Cookie: shared=yes; domain=.example.com");

    // Verify curl2 sees the cookie
    var cookies: ?*c.curl_slist = null;
    _ = c.curl_easy_getinfo(curl2, c.CURLINFO_COOKIELIST, &cookies);
    defer c.curl_slist_free_all(cookies);

    try testing.expect(cookies != null);
    const cookie_str = std.mem.span(cookies.?.data);
    try testing.expect(std.mem.indexOf(u8, cookie_str, "shared") != null);
}
