## File to Create
src/dom/events/CookieChangeEvent.zig

## Implementation

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const Event = @import("../event.zig").Event;
const CookieListItem = @import("../../webidl/impls/CookieStore.zig").CookieStore.CookieListItem;

/// CookieChangeEvent - fired when cookies change
/// https://wicg.github.io/cookie-store/#CookieChangeEvent
pub const CookieChangeEvent = struct {
    /// Inherit from Event
    event: Event,

    /// Cookies that were added or modified
    changed: []const CookieListItem,

    /// Cookies that were deleted
    deleted: []const CookieListItem,

    /// Allocator for cleanup
    allocator: Allocator,

    /// Create a new CookieChangeEvent
    pub fn init(
        allocator: Allocator,
        event_type: []const u8,
        init_dict: CookieChangeEventInit,
    ) !*CookieChangeEvent {
        const self = try allocator.create(CookieChangeEvent);
        errdefer allocator.destroy(self);

        // Initialize base Event
        self.event = try Event.init(allocator, event_type, .{
            .bubbles = init_dict.bubbles,
            .cancelable = init_dict.cancelable,
            .composed = init_dict.composed,
        });

        // Copy changed cookies
        if (init_dict.changed.len > 0) {
            const changed = try allocator.alloc(CookieListItem, init_dict.changed.len);
            errdefer allocator.free(changed);

            for (init_dict.changed, 0..) |cookie, i| {
                changed[i] = try cookie.clone(allocator);
            }
            self.changed = changed;
        } else {
            self.changed = &[_]CookieListItem{};
        }

        // Copy deleted cookies
        if (init_dict.deleted.len > 0) {
            const deleted = try allocator.alloc(CookieListItem, init_dict.deleted.len);
            errdefer allocator.free(deleted);

            for (init_dict.deleted, 0..) |cookie, i| {
                deleted[i] = try cookie.clone(allocator);
            }
            self.deleted = deleted;
        } else {
            self.deleted = &[_]CookieListItem{};
        }

        self.allocator = allocator;

        return self;
    }

    /// Clean up
    pub fn deinit(self: *CookieChangeEvent) void {
        // Free changed cookies
        for (self.changed) |*cookie| {
            cookie.deinit(self.allocator);
        }
        if (self.changed.len > 0) {
            self.allocator.free(self.changed);
        }

        // Free deleted cookies
        for (self.deleted) |*cookie| {
            cookie.deinit(self.allocator);
        }
        if (self.deleted.len > 0) {
            self.allocator.free(self.deleted);
        }

        // Free base event
        self.event.deinit();

        self.allocator.destroy(self);
    }

    // ============================================================
    // WebIDL Attributes
    // ============================================================

    /// Get the list of changed cookies (readonly)
    pub fn getChanged(self: *const CookieChangeEvent) []const CookieListItem {
        return self.changed;
    }

    /// Get the list of deleted cookies (readonly)
    pub fn getDeleted(self: *const CookieChangeEvent) []const CookieListItem {
        return self.deleted;
    }

    // ============================================================
    // Event Interface Methods (delegated to base)
    // ============================================================

    pub fn getType(self: *const CookieChangeEvent) []const u8 {
        return self.event.event_type;
    }

    pub fn getTarget(self: *const CookieChangeEvent) ?*anyopaque {
        return self.event.target;
    }

    pub fn getBubbles(self: *const CookieChangeEvent) bool {
        return self.event.bubbles;
    }

    pub fn getCancelable(self: *const CookieChangeEvent) bool {
        return self.event.cancelable;
    }

    pub fn preventDefault(self: *CookieChangeEvent) void {
        self.event.preventDefault();
    }

    pub fn stopPropagation(self: *CookieChangeEvent) void {
        self.event.stopPropagation();
    }

    pub fn stopImmediatePropagation(self: *CookieChangeEvent) void {
        self.event.stopImmediatePropagation();
    }
};

/// Initialization dictionary for CookieChangeEvent
pub const CookieChangeEventInit = struct {
    // EventInit fields
    bubbles: bool = false,
    cancelable: bool = false,
    composed: bool = false,

    // CookieChangeEventInit fields
    changed: []const CookieListItem = &[_]CookieListItem{},
    deleted: []const CookieListItem = &[_]CookieListItem{},
};

// ============================================================
// Factory Functions
// ============================================================

/// Create a CookieChangeEvent for cookie changes
pub fn createChangeEvent(
    allocator: Allocator,
    changed: []const CookieListItem,
    deleted: []const CookieListItem,
) !*CookieChangeEvent {
    return CookieChangeEvent.init(allocator, "change", .{
        .changed = changed,
        .deleted = deleted,
    });
}
```

