Cache wrappers created via constructors (new Element()) in addition to wrapInstanceAsV8Object.

## Objective
Ensure constructors also populate the wrapper cache so that `new Element()` creates cached wrappers just like querySelector does.

## Technical Details

### Changes to constructorCallback
File: src/runtime/engines/v8/interface.zig

```zig
fn constructorCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
    const isolate = info.getIsolate();
    const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
        conv.throwError(isolate, "No current V8 context");
        return;
    };

    // ... existing allocator and context setup ...

    // Call the interface's constructor
    const instance = callConstructorWithArgs(info, allocator, ctx, v8_context, isolate) catch |err| {
        // ... error handling ...
        return;
    };

    // Get 'this' object (the newly created instance)
    const this_obj = info.getThis();

    // Store the Zig instance in V8 object's internal fields (EXISTING)
    const dom_type_info_mod = @import("dom_type_info.zig");
    if (dom_type_info_mod.getTypeInfoByName(interface_name)) |type_info| {
        setInstanceWithTypeInfo(runtime.Instance, this_obj, instance, type_info);
    } else {
        setInstance(runtime.Instance, this_obj, instance);
    }

    // ========================================
    // NEW: Cache the wrapper
    // ========================================
    const ctx_mgr = @import("context_manager.zig");
    if (ctx_mgr.getContext(v8_context)) |runtime_ctx| {
        if (runtime_ctx.wrapper_cache) |*cache| {
            cache.set(instance, this_obj, isolate) catch |err| {
                // Log but don't fail - wrapper is still usable
                std.log.warn("Failed to cache constructor wrapper: {s}", .{@errorName(err)});
            };
        }
    }

    // Return 'this' (V8 does this automatically for constructors)
}
```

