// ============================================================================
// Main Thread Scheduling (cross-thread coordination)
// ============================================================================

/// Callback type for main thread execution
///
/// This function will be called on the main JavaScript thread
/// via the V8 platform's foreground task runner.
pub const MainThreadCallbackFn = *const fn (user_data: ?*anyopaque) callconv(.c) void;

/// Schedule a callback to run on the main/foreground thread
///
/// Uses V8's platform task runner to post work to the main thread.
/// The callback will be invoked during the next event loop tick.
///
/// Maps to: platform->GetForegroundTaskRunner(isolate)->PostTask(...)
///
/// Arguments:
///   - isolate: V8 Isolate to schedule on
///   - callback: Function to call on main thread
///   - user_data: Opaque data passed to callback (may be null)
///
/// Returns:
///   - true if task was successfully posted
///   - false if scheduling failed (no platform, no task runner, etc.)
///
/// Thread Safety:
///   This function is safe to call from any thread. That's the entire
///   purpose - it allows background threads to post work to the main thread.
///
/// Memory:
///   The caller must ensure user_data remains valid until callback is invoked.
///   V8 will NOT free user_data; the callback should handle cleanup.
pub extern fn v8_Isolate_ScheduleOnMainThread(
    isolate: *Isolate,
    callback: MainThreadCallbackFn,
    user_data: ?*anyopaque,
) bool;
```

### C++ Implementation Required

These FFI declarations require corresponding C++ wrapper functions. Create or update the C++ wrapper source:

**File: v8_wrapper.cpp (or similar)**

```cpp
#include <v8.h>
#include <libplatform/libplatform.h>
#include <memory>

extern "C" {

// GC for testing
void v8_Isolate_RequestGarbageCollectionForTesting(v8::Isolate* isolate) {
    // V8's testing GC API - performs full GC
    // Note: This may be a no-op in production V8 builds
    isolate->RequestGarbageCollectionForTesting(
        v8::Isolate::kFullGarbageCollection
    );
}

// Helper class for main thread task
class MainThreadTask : public v8::Task {
public:
    MainThreadTask(void (*callback)(void*), void* user_data)
        : callback_(callback), user_data_(user_data) {}

    void Run() override {
        if (callback_) {
            callback_(user_data_);
        }
    }

private:
    void (*callback_)(void*);
    void* user_data_;
};

// Schedule callback on main thread
bool v8_Isolate_ScheduleOnMainThread(
    v8::Isolate* isolate,
    void (*callback)(void*),
    void* user_data
) {
    // Get the V8 platform (must be set during initialization)
    v8::Platform* platform = v8::V8::GetCurrentPlatform();
    if (!platform) {
        return false;
    }

    // Get the foreground (main thread) task runner
    std::shared_ptr<v8::TaskRunner> task_runner = 
        platform->GetForegroundTaskRunner(isolate);
    if (!task_runner) {
        return false;
    }

    // Post the task
    task_runner->PostTask(
        std::make_unique<MainThreadTask>(callback, user_data)
    );

    return true;
}

} // extern "C"
```

