        deinit: *const fn(ptr: *anyopaque) void,
    };

    pub fn performRequest(self: NetworkBackend, request: NetworkRequest) NetworkError!NetworkResponse {
        return self.vtable.performRequest(self.ptr, request);
    }

    pub fn cancelRequest(self: NetworkBackend, request_id: u64) void {
        self.vtable.cancelRequest(self.ptr, request_id);
    }

    pub fn deinit(self: NetworkBackend) void {
        self.vtable.deinit(self.ptr);
    }
};

pub const NetworkRequest = struct {
    /// Request ID for cancellation
    id: u64,

    /// HTTP method
    method: []const u8,

    /// Full URL
    url: []const u8,

    /// Headers to send
    headers: []const Header,

    /// Request body (null for GET/HEAD)
    body: ?[]const u8,

    /// Timeout in milliseconds (0 = no timeout)
    timeout_ms: u64,

    /// Whether to follow redirects (we handle manually, so usually false)
    follow_redirects: bool,

    /// Whether to include credentials (for TLS client certs)
    include_credentials: bool,

    pub const Header = struct {
        name: []const u8,
        value: []const u8,
    };
};

pub const NetworkResponse = struct {
    /// HTTP status code
    status: u16,

    /// Status message (may be empty for HTTP/2)
    status_message: []const u8,

    /// Response headers
    headers: []const NetworkRequest.Header,

    /// Response body
    body: []const u8,

    /// Connection timing info
    timing: ConnectionTiming,

    pub const ConnectionTiming = struct {
        dns_start: f64,
        dns_end: f64,
        connect_start: f64,
        connect_end: f64,
        secure_start: f64,
        secure_end: f64,
        request_start: f64,
        response_start: f64,
        response_end: f64,
    };
};

pub const NetworkError = error{
    ConnectionFailed,
    DnsResolutionFailed,
    Timeout,
    TlsError,
    InvalidUrl,
    RequestCanceled,
    OutOfMemory,
    Unknown,
};
