### libcurl Backend
```zig
/// libcurl-based network backend.
pub const LibcurlBackend = struct {
    allocator: std.mem.Allocator,

    // curl multi handle for async operations
    multi_handle: *c.CURLM,

    // Active request tracking
    active_requests: std.AutoHashMap(u64, *RequestContext),
    next_request_id: u64,

    pub fn init(allocator: std.mem.Allocator) !*LibcurlBackend {
        // Initialize libcurl
        if (c.curl_global_init(c.CURL_GLOBAL_DEFAULT) != c.CURLE_OK) {
            return error.CurlInitFailed;
        }

        const self = try allocator.create(LibcurlBackend);
        self.* = .{
            .allocator = allocator,
            .multi_handle = c.curl_multi_init() orelse return error.CurlInitFailed,
            .active_requests = std.AutoHashMap(u64, *RequestContext).init(allocator),
            .next_request_id = 1,
        };
        return self;
    }

    pub fn deinit(self: *LibcurlBackend) void {
        // Clean up active requests
        var iter = self.active_requests.iterator();
        while (iter.next()) |entry| {
            entry.value_ptr.*.deinit();
        }
        self.active_requests.deinit();

        c.curl_multi_cleanup(self.multi_handle);
        c.curl_global_cleanup();
        self.allocator.destroy(self);
    }

    pub fn performRequest(
        self: *LibcurlBackend,
        request: NetworkRequest,
    ) NetworkError!NetworkResponse {
        const ctx = try RequestContext.init(self.allocator, request);
        errdefer ctx.deinit();

        // Set up curl easy handle
        const curl = c.curl_easy_init() orelse return error.Unknown;
        defer c.curl_easy_cleanup(curl);

        // Configure request
        try self.configureCurl(curl, ctx, request);

        // Perform synchronous request
        const res = c.curl_easy_perform(curl);
        if (res != c.CURLE_OK) {
            return translateCurlError(res);
        }

        // Build response
        return ctx.buildResponse();
    }

    fn configureCurl(
        self: *LibcurlBackend,
        curl: *c.CURL,
        ctx: *RequestContext,
        request: NetworkRequest,
    ) !void {
        _ = self;

        // URL
        _ = c.curl_easy_setopt(curl, c.CURLOPT_URL, request.url.ptr);

        // Method
        if (std.mem.eql(u8, request.method, "POST")) {
            _ = c.curl_easy_setopt(curl, c.CURLOPT_POST, @as(c_long, 1));
        } else if (std.mem.eql(u8, request.method, "PUT")) {
            _ = c.curl_easy_setopt(curl, c.CURLOPT_UPLOAD, @as(c_long, 1));
        } else if (!std.mem.eql(u8, request.method, "GET")) {
            _ = c.curl_easy_setopt(curl, c.CURLOPT_CUSTOMREQUEST, request.method.ptr);
        }

        // Headers
        var header_list: ?*c.curl_slist = null;
        for (request.headers) |header| {
            const header_str = try std.fmt.allocPrintZ(
                ctx.allocator,
                "{s}: {s}",
                .{ header.name, header.value },
            );
            header_list = c.curl_slist_append(header_list, header_str.ptr);
        }
        if (header_list) |list| {
            _ = c.curl_easy_setopt(curl, c.CURLOPT_HTTPHEADER, list);
            ctx.header_list = list;
        }

        // Body
        if (request.body) |body| {
            _ = c.curl_easy_setopt(curl, c.CURLOPT_POSTFIELDS, body.ptr);
            _ = c.curl_easy_setopt(curl, c.CURLOPT_POSTFIELDSIZE, @intCast(c_long, body.len));
        }

        // Callbacks for response
        _ = c.curl_easy_setopt(curl, c.CURLOPT_WRITEFUNCTION, writeCallback);
        _ = c.curl_easy_setopt(curl, c.CURLOPT_WRITEDATA, ctx);
        _ = c.curl_easy_setopt(curl, c.CURLOPT_HEADERFUNCTION, headerCallback);
        _ = c.curl_easy_setopt(curl, c.CURLOPT_HEADERDATA, ctx);

        // Redirects - we handle manually
        _ = c.curl_easy_setopt(curl, c.CURLOPT_FOLLOWLOCATION, @as(c_long, 0));

        // Timeout
        if (request.timeout_ms > 0) {
            _ = c.curl_easy_setopt(curl, c.CURLOPT_TIMEOUT_MS, @intCast(c_long, request.timeout_ms));
        }

        // TLS
        if (!request.include_credentials) {
            // Don't send client certificates
            _ = c.curl_easy_setopt(curl, c.CURLOPT_SSLCERT, null);
        }
    }

    /// Get backend as trait object.
    pub fn asBackend(self: *LibcurlBackend) NetworkBackend {
        return .{
            .ptr = self,
            .vtable = &vtable,
        };
    }

    const vtable = NetworkBackend.VTable{
        .performRequest = performRequestImpl,
        .cancelRequest = cancelRequestImpl,
        .deinit = deinitImpl,
    };
};

const RequestContext = struct {
    allocator: std.mem.Allocator,
    response_body: std.ArrayList(u8),
    response_headers: std.ArrayList(NetworkRequest.Header),
    header_list: ?*c.curl_slist,

    pub fn init(allocator: std.mem.Allocator, request: NetworkRequest) !*RequestContext {
        _ = request;
        const ctx = try allocator.create(RequestContext);
        ctx.* = .{
            .allocator = allocator,
            .response_body = std.ArrayList(u8).init(allocator),
            .response_headers = std.ArrayList(NetworkRequest.Header).init(allocator),
            .header_list = null,
        };
        return ctx;
    }

    pub fn deinit(self: *RequestContext) void {
        self.response_body.deinit();
        for (self.response_headers.items) |h| {
            self.allocator.free(h.name);
            self.allocator.free(h.value);
        }
        self.response_headers.deinit();
        if (self.header_list) |list| {
            c.curl_slist_free_all(list);
        }
        self.allocator.destroy(self);
    }
};

fn writeCallback(ptr: [*]u8, size: usize, nmemb: usize, userdata: *RequestContext) usize {
    const total = size * nmemb;
    userdata.response_body.appendSlice(ptr[0..total]) catch return 0;
    return total;
}

fn headerCallback(ptr: [*]u8, size: usize, nmemb: usize, userdata: *RequestContext) usize {
    const total = size * nmemb;
    // Parse header line
    const line = ptr[0..total];
    // ... parse name: value
    _ = userdata;
    return total;
}

fn translateCurlError(code: c.CURLcode) NetworkError {
    return switch (code) {
        c.CURLE_COULDNT_RESOLVE_HOST => error.DnsResolutionFailed,
        c.CURLE_COULDNT_CONNECT => error.ConnectionFailed,
        c.CURLE_OPERATION_TIMEDOUT => error.Timeout,
        c.CURLE_SSL_CONNECT_ERROR => error.TlsError,
        else => error.Unknown,
    };
}
