```zig
const std = @import("std");
const Transport = @import("transport.zig").Transport;
const ConnectOptions = @import("transport.zig").ConnectOptions;

/// TLS transport implementation using std.crypto.tls
pub const TlsTransport = struct {
    tls_client: std.crypto.tls.Client,
    underlying_stream: std.net.Stream,
    allocator: std.mem.Allocator,

    const Self = @This();

    pub fn connect(allocator: std.mem.Allocator, options: ConnectOptions) !Transport {
        // First establish TCP connection
        const address = try std.net.Address.resolveIp(options.host, options.port);
        const stream = try std.net.tcpConnectToAddress(address);
        errdefer stream.close();

        // Set up TLS
        var bundle = std.crypto.tls.x509.Bundle{};
        if (!options.tls_skip_verify) {
            bundle.rescan(allocator) catch {};
        }

        const sni = options.tls_sni orelse options.host;
        var tls = try std.crypto.tls.Client.init(.{
            .stream = stream,
            .host = sni,
            .ca_bundle = bundle,
        });

        const self = try allocator.create(Self);
        self.* = .{
            .tls_client = tls,
            .underlying_stream = stream,
            .allocator = allocator,
        };

        return .{
            .ptr = self,
            .vtable = &vtable,
        };
    }

    fn readImpl(ptr: *anyopaque, buffer: []u8) Transport.ReadError!usize {
        const self: *Self = @ptrCast(@alignCast(ptr));
        return self.tls_client.read(buffer) catch |err| switch (err) {
            error.TlsAlert => error.TlsError,
            else => error.Unexpected,
        };
    }

    fn writeImpl(ptr: *anyopaque, data: []const u8) Transport.WriteError!usize {
        const self: *Self = @ptrCast(@alignCast(ptr));
        return self.tls_client.write(data) catch |err| switch (err) {
            error.TlsAlert => error.TlsError,
            else => error.Unexpected,
        };
    }

    fn closeImpl(ptr: *anyopaque) void {
        const self: *Self = @ptrCast(@alignCast(ptr));
        self.tls_client.close();
        self.underlying_stream.close();
        self.allocator.destroy(self);
    }

    // ... poll and getRemoteAddress implementations

    const vtable = Transport.VTable{
        .read = readImpl,
        .write = writeImpl,
        .close = closeImpl,
        .poll = pollImpl,
        .getRemoteAddress = getRemoteAddressImpl,
    };
};
