```zig
//! ProgressEvent Implementation
//! Spec: https://xhr.spec.whatwg.org/#interface-progressevent

const std = @import("std");
const Event = @import("Event.zig");

pub const ProgressEvent = struct {
    // Base Event
    event: Event,

    // ProgressEvent-specific fields
    length_computable: bool,
    loaded: f64,
    total: f64,

    /// Create a ProgressEvent
    pub fn init(
        allocator: std.mem.Allocator,
        event_type: []const u8,
        length_computable: bool,
        loaded: f64,
        total: f64,
    ) !*ProgressEvent {
        const self = try allocator.create(ProgressEvent);
        self.event = try Event.init(allocator, event_type);
        self.length_computable = length_computable;
        self.loaded = loaded;
        self.total = total;
        return self;
    }

    pub fn deinit(self: *ProgressEvent, allocator: std.mem.Allocator) void {
        self.event.deinit(allocator);
        allocator.destroy(self);
    }

    // Getters
    pub fn getLengthComputable(self: *ProgressEvent) bool {
        return self.length_computable;
    }

    pub fn getLoaded(self: *ProgressEvent) f64 {
        return self.loaded;
    }

    pub fn getTotal(self: *ProgressEvent) f64 {
        return self.total;
    }
};
```

