//! Implementation for MessageEvent interface

const std = @import("std");
const runtime = @import("runtime");
const interfaces = @import("interfaces");
const dictionaries = @import("dictionaries");
const webidl = @import("webidl");
const MessageEvent = interfaces.MessageEvent;

pub const State = MessageEvent.State;

/// Message data type (for WebSocket binary type handling)
pub const DataType = enum {
    text,
    blob,
    array_buffer,
};

pub const InternalState = struct {
    /// The message data
    data: MessageData,
    /// Origin URL
    origin: runtime.USVString,
    /// Last event ID (always empty for WebSocket)
    last_event_id: runtime.DOMString,
    /// Source (always null for WebSocket)
    source: ?*anyopaque,
    /// Message ports (empty for WebSocket)
    ports_data: ?[]const *runtime.Instance,
};

pub const MessageData = union(DataType) {
    text: []const u8,
    blob: *runtime.Instance, // Blob instance
    array_buffer: []const u8, // Raw bytes for ArrayBuffer
};

pub fn init(
    allocator: std.mem.Allocator,
    comptime StateType: type,
    vtable: *const runtime.VTable,
    ctx: runtime.Context,
) !*runtime.Instance {
    const instance = try runtime.Instance.init(allocator, StateType, vtable, ctx);

    const internal = try allocator.create(InternalState);
    internal.* = .{
        .data = .{ .text = "" },
        .origin = "",
        .last_event_id = "",
        .source = null,
        .ports_data = null,
    };

    const state = instance.getState(StateType);
    state._internal = internal;

    return instance;
}

pub fn deinit(instance: *runtime.Instance) void {
    const state = instance.getState(State);
    if (state._internal) |internal| {
        instance.allocator.destroy(internal);
    }
    runtime.Instance.deinit(instance);
}

/// Constructor: new MessageEvent(type, eventInitDict)
pub fn call_constructor(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    event_type: runtime.DOMString,
    init_dict: webidl.Opt(dictionaries.MessageEventInit),
) !*runtime.Instance {
    const instance = try init(allocator, State, &MessageEvent.vtable, ctx);
    errdefer deinit(instance);

    const state = instance.getState(State);
    state.type = event_type;
    state.bubbles = false;
    state.cancelable = false;

    const internal = state._internal.?;
    if (init_dict.wasPassed()) {
        const dict = init_dict.value;
        if (dict.data) |d| internal.data = .{ .text = d }; // Simplified
        if (dict.origin) |o| internal.origin = o;
        if (dict.lastEventId) |id| internal.last_event_id = id;
        // source and ports require more complex handling
    }

    return instance;
}

/// Getter for data
pub fn get_data(instance: *runtime.Instance) anyerror!*const anyopaque {
    const state = instance.getState(State);
    const internal = state._internal orelse return error.NotInitialized;

    // Return type depends on data variant
    return switch (internal.data) {
        .text => |t| @ptrCast(t.ptr),
        .blob => |b| @ptrCast(b),
        .array_buffer => |a| @ptrCast(a.ptr),
    };
}

/// Getter for origin
pub fn get_origin(instance: *runtime.Instance) anyerror!runtime.USVString {
    const state = instance.getState(State);
    const internal = state._internal orelse return "";
    return internal.origin;
}

/// Getter for lastEventId
pub fn get_lastEventId(instance: *runtime.Instance) anyerror!runtime.DOMString {
    const state = instance.getState(State);
    const internal = state._internal orelse return "";
    return internal.last_event_id;
}

/// Getter for source
pub fn get_source(instance: *runtime.Instance) anyerror!?*anyopaque {
    const state = instance.getState(State);
    const internal = state._internal orelse return null;
    return internal.source;
}

/// Getter for ports
pub fn get_ports(instance: *runtime.Instance) anyerror!*const anyopaque {
    _ = instance;
    // Return empty frozen array
    // TODO: Proper FrozenArray implementation
    return @ptrFromInt(0);
}

/// Create a MessageEvent for WebSocket text message
pub fn createTextMessageEvent(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    data: []const u8,
    origin: []const u8,
) !*runtime.Instance {
    const instance = try init(allocator, State, &MessageEvent.vtable, ctx);

    const state = instance.getState(State);
    state.type = "message";

    const internal = state._internal.?;
    internal.data = .{ .text = try allocator.dupe(u8, data) };
    internal.origin = try allocator.dupe(u8, origin);

    return instance;
}

/// Create a MessageEvent for WebSocket binary message (ArrayBuffer)
pub fn createBinaryMessageEvent(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    data: []const u8,
    origin: []const u8,
) !*runtime.Instance {
    const instance = try init(allocator, State, &MessageEvent.vtable, ctx);

    const state = instance.getState(State);
    state.type = "message";

    const internal = state._internal.?;
    internal.data = .{ .array_buffer = try allocator.dupe(u8, data) };
    internal.origin = try allocator.dupe(u8, origin);

    return instance;
}

/// Create a MessageEvent for WebSocket binary message (Blob)
pub fn createBlobMessageEvent(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    blob: *runtime.Instance,
    origin: []const u8,
) !*runtime.Instance {
    const instance = try init(allocator, State, &MessageEvent.vtable, ctx);

    const state = instance.getState(State);
    state.type = "message";

    const internal = state._internal.?;
    internal.data = .{ .blob = blob };
    internal.origin = try allocator.dupe(u8, origin);

    return instance;
}
```

