```zig
// src/websocket/events.zig

const std = @import("std");
const runtime = @import("runtime");
const event_loop = @import("../runtime/event_loop/root.zig");

/// Task data for WebSocket events
pub const WebSocketEventTask = struct {
    /// The WebSocket instance
    websocket: *runtime.Instance,
    /// The event to dispatch
    event: WebSocketEventType,

    pub const WebSocketEventType = union(enum) {
        open: OpenEventData,
        message: MessageEventData,
        @"error": void,
        close: CloseEventData,
    };

    pub const OpenEventData = struct {
        extensions: ?[]const u8,
        protocol: ?[]const u8,
    };

    pub const MessageEventData = struct {
        data: []const u8,
        is_text: bool,
        origin: []const u8,
    };

    pub const CloseEventData = struct {
        was_clean: bool,
        code: u16,
        reason: []const u8,
    };
};

/// Queue a WebSocket event for dispatch
pub fn queueWebSocketEvent(
    loop: *event_loop.EventLoop,
    task: WebSocketEventTask,
) !void {
    const task_fn = struct {
        fn execute(data: *anyopaque) void {
            const t: *WebSocketEventTask = @ptrCast(@alignCast(data));
            dispatchWebSocketEvent(t.*);
        }
    }.execute;

    try loop.queueTask(.{
        .source = .websocket,
        .callback = task_fn,
        .data = @ptrCast(&task),
    });
}

/// Actually dispatch the event (runs on the main thread)
fn dispatchWebSocketEvent(task: WebSocketEventTask) void {
    const ws_state = task.websocket.getState(WebSocket.State);
    const internal = ws_state._internal orelse return;

    switch (task.event) {
        .open => |data| {
            ws_state.readyState = 1; // OPEN
            ws_state.extensions = data.extensions orelse "";
            ws_state.protocol = data.protocol orelse "";

            // Fire 'open' event on EventTarget
            fireSimpleEvent(task.websocket, "open");
        },
        .message => |data| {
            if (ws_state.readyState != 1) return; // Not OPEN

            // Create MessageEvent
            const event = createMessageEvent(
                task.websocket.allocator,
                data.data,
                data.is_text,
                data.origin,
                internal.binary_type,
            );

            // Fire message event
            fireEvent(task.websocket, "message", event);
        },
        .@"error" => {
            fireSimpleEvent(task.websocket, "error");
        },
        .close => |data| {
            ws_state.readyState = 3; // CLOSED

            // Create CloseEvent  
            const event = createCloseEvent(
                task.websocket.allocator,
                data.was_clean,
                data.code,
                data.reason,
            );

            // Fire close event
            fireEvent(task.websocket, "close", event);
        },
    }
}

fn fireSimpleEvent(target: *runtime.Instance, event_type: []const u8) void {
    // Create Event
    const event = interfaces.Event.call_constructor(
        target.allocator,
        target.context,
        event_type,
        .notPassed(),
    ) catch return;
    defer interfaces.Event.deinit(event);

    // Dispatch via EventTarget
    _ = interfaces.EventTarget.call_dispatchEvent(target, event) catch {};
}

fn fireEvent(target: *runtime.Instance, event_type: []const u8, event: *runtime.Instance) void {
    _ = event_type;
    // Set event target
    const event_state = event.getState(interfaces.Event.State);
    event_state.target = target;

    // Dispatch via EventTarget
    _ = interfaces.EventTarget.call_dispatchEvent(target, event) catch {};
}

fn createMessageEvent(
    allocator: std.mem.Allocator,
    data: []const u8,
    is_text: bool,
    origin: []const u8,
    binary_type: enums.BinaryType,
) *runtime.Instance {
    if (is_text) {
        return MessageEventImpl.createTextMessageEvent(allocator, .{}, data, origin) catch unreachable;
    } else {
        return switch (binary_type) {
            .arraybuffer => MessageEventImpl.createBinaryMessageEvent(allocator, .{}, data, origin) catch unreachable,
            .blob => MessageEventImpl.createBlobMessageEvent(allocator, .{}, createBlob(allocator, data), origin) catch unreachable,
        };
    }
}

fn createCloseEvent(
    allocator: std.mem.Allocator,
    was_clean: bool,
    code: u16,
    reason: []const u8,
) *runtime.Instance {
    return CloseEventImpl.createCloseEvent(allocator, .{}, was_clean, code, reason) catch unreachable;
}
