pub const WebSocketConnection = struct {
    // Add event loop reference
    event_loop: ?*event_loop.EventLoop,
    websocket_instance: ?*runtime.Instance,

    // Modify handleStateEvent to queue instead of direct dispatch
    fn handleStateEvent(self: *Self, event: StateMachine.StateEvent) void {
        if (self.event_loop) |loop| {
            const task = switch (event) {
                .opened => WebSocketEventTask{
                    .websocket = self.websocket_instance.?,
                    .event = .{ .open = .{
                        .extensions = self.extensions,
                        .protocol = self.protocol,
                    }},
                },
                .message => |msg| WebSocketEventTask{
                    .websocket = self.websocket_instance.?,
                    .event = .{ .message = .{
                        .data = msg.data,
                        .is_text = msg.is_text,
                        .origin = self.url,
                    }},
                },
                .closed => |info| WebSocketEventTask{
                    .websocket = self.websocket_instance.?,
                    .event = .{ .close = .{
                        .was_clean = info.was_clean,
                        .code = @intFromEnum(info.code),
                        .reason = info.reason,
                    }},
                },
                // ... etc
            };

            queueWebSocketEvent(loop, task) catch {};
        }
    }
};
