## Implementation
```zig
// src/webidl/impls/ProgressEvent.zig

pub const InternalState = struct {
    length_computable: bool,
    loaded: u64,
    total: u64,
};

pub fn call_constructor(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    event_type: runtime.DOMString,
    init: dictionaries.ProgressEventInit,
) !*runtime.Instance {
    // Create Event base
    const event_init = dictionaries.EventInit{
        .bubbles = init.base.bubbles,
        .cancelable = init.base.cancelable,
        .composed = init.base.composed,
    };

    const instance = try ProgressEvent.init(allocator, ProgressEvent.State, &ProgressEvent.vtable, ctx);

    // Initialize Event properties via base
    try Event.initializeEvent(instance, event_type, event_init);

    // Set ProgressEvent-specific properties
    const internal = try allocator.create(InternalState);
    internal.* = .{
        .length_computable = init.lengthComputable orelse false,
        .loaded = init.loaded orelse 0,
        .total = init.total orelse 0,
    };
    try setInternal(instance, internal);

    return instance;
}

pub fn get_lengthComputable(instance: *runtime.Instance) !bool {
    const internal = getInternal(instance) orelse return false;
    return internal.length_computable;
}

pub fn get_loaded(instance: *runtime.Instance) !u64 {
    const internal = getInternal(instance) orelse return 0;
    return internal.loaded;
}

pub fn get_total(instance: *runtime.Instance) !u64 {
    const internal = getInternal(instance) orelse return 0;
    return internal.total;
}
```

## Usage in FileReader
