//! 2. GC execution on dedicated thread
//! 3. Main thread scheduling
//! 4. Promise resolution
//!
//! Run with: zig build test -Denable-test-utils=true

const std = @import("std");
const testing = std.testing;
const runtime = @import("runtime");
const v8 = @import("v8");
