test "TestUtils.gc - returns Promise" {
    if (!v8Available()) return error.SkipZigTest;

    // Initialize V8
    var isolate = try v8.Isolate.create(testing.allocator);
    defer isolate.dispose();

    var context = try v8.Context.create(isolate);
    defer context.dispose();

    // Create runtime context with V8 engine
    var ctx_data = try runtime.ContextData.init(testing.allocator, .{
        .engine = &v8.engine.v8_engine_interface,
        .engine_ctx = @ptrCast(isolate),
        .realm_info = runtime.RealmInfo.forWindow(),
    });
    defer ctx_data.deinit();

    // Call gc()
    const result = try testutils.performGC(&ctx_data);

    // Result should be a V8 Promise
    try testing.expect(result != null);

    // Verify it's actually a Promise
    const v8_value: *v8.ffi.Value = @ptrCast(@alignCast(result));
    try testing.expect(v8.ffi.v8_Value_IsPromise(v8_value));
}

test "TestUtils.gc - Promise resolves after GC" {
    if (!v8Available()) return error.SkipZigTest;

    // Initialize V8
    var isolate = try v8.Isolate.create(testing.allocator);
    defer isolate.dispose();

    var context = try v8.Context.create(isolate);
    defer context.dispose();

    // Create runtime context
    var ctx_data = try runtime.ContextData.init(testing.allocator, .{
        .engine = &v8.engine.v8_engine_interface,
        .engine_ctx = @ptrCast(isolate),
        .realm_info = runtime.RealmInfo.forWindow(),
    });
    defer ctx_data.deinit();

    // Call gc()
    const promise_ptr = try testutils.performGC(&ctx_data);
    const promise: *v8.ffi.Promise = @ptrCast(@alignCast(promise_ptr));

    // Run event loop to allow GC thread to complete and promise to resolve
    try v8.runEventLoopUntilIdle(isolate);

    // Promise should be resolved
    const state = v8.ffi.v8_Promise_State(promise);
    try testing.expectEqual(v8.ffi.PromiseState.Fulfilled, state);

    // Value should be undefined
    const result = v8.ffi.v8_Promise_Result(promise);
    try testing.expect(v8.ffi.v8_Value_IsUndefined(result));
}

