```zig
//! Implementation for CloseEvent interface

const std = @import("std");
const runtime = @import("runtime");
const interfaces = @import("interfaces");
const dictionaries = @import("dictionaries");
const webidl = @import("webidl");
const CloseEvent = interfaces.CloseEvent;

pub const State = CloseEvent.State;

pub const InternalState = struct {
    /// Whether the connection closed cleanly
    was_clean: bool,
    /// The close code (1000-4999)
    code: u16,
    /// The close reason (UTF-8, max 123 bytes)
    reason: runtime.USVString,
};

pub fn init(
    allocator: std.mem.Allocator,
    comptime StateType: type,
    vtable: *const runtime.VTable,
    ctx: runtime.Context,
) !*runtime.Instance {
    const instance = try runtime.Instance.init(allocator, StateType, vtable, ctx);

    // Initialize internal state
    const internal = try allocator.create(InternalState);
    internal.* = .{
        .was_clean = false,
        .code = 0,
        .reason = "",
    };

    const state = instance.getState(StateType);
    state._internal = internal;

    return instance;
}

pub fn deinit(instance: *runtime.Instance) void {
    const state = instance.getState(State);
    if (state._internal) |internal| {
        instance.allocator.destroy(internal);
    }
    runtime.Instance.deinit(instance);
}

/// Constructor: new CloseEvent(type, eventInitDict)
pub fn call_constructor(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    event_type: runtime.DOMString,
    init_dict: webidl.Opt(dictionaries.CloseEventInit),
) !*runtime.Instance {
    const instance = try init(allocator, State, &CloseEvent.vtable, ctx);
    errdefer deinit(instance);

    // Initialize Event base class
    const state = instance.getState(State);
    state.type = event_type;
    state.bubbles = false;
    state.cancelable = false;

    // Initialize CloseEvent-specific fields
    const internal = state._internal.?;
    if (init_dict.wasPassed()) {
        const dict = init_dict.value;
        internal.was_clean = dict.wasClean orelse false;
        internal.code = dict.code orelse 0;
        internal.reason = dict.reason orelse "";

        // Also copy EventInit fields
        if (dict.bubbles) |b| state.bubbles = b;
        if (dict.cancelable) |c| state.cancelable = c;
    }

    return instance;
}

/// Getter for wasClean
pub fn get_wasClean(instance: *runtime.Instance) anyerror!bool {
    const state = instance.getState(State);
    const internal = state._internal orelse return false;
    return internal.was_clean;
}

/// Getter for code
pub fn get_code(instance: *runtime.Instance) anyerror!u16 {
    const state = instance.getState(State);
    const internal = state._internal orelse return 0;
    return internal.code;
}

/// Getter for reason  
pub fn get_reason(instance: *runtime.Instance) anyerror!runtime.USVString {
    const state = instance.getState(State);
    const internal = state._internal orelse return "";
    return internal.reason;
}

/// Create a CloseEvent with the given parameters
/// Convenience function for internal use
pub fn createCloseEvent(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    was_clean: bool,
    code: u16,
    reason: []const u8,
) !*runtime.Instance {
    return call_constructor(allocator, ctx, "close", .passed(.{
        .wasClean = was_clean,
        .code = code,
        .reason = reason,
    }));
}
```

