## Global Singleton Pattern

```zig
// In src/fetch/network/curl_cookies.zig

/// Global cookie manager singleton
var global_cookie_manager: ?*CurlCookieManager = null;
var global_init_mutex: std.Thread.Mutex = .{};

/// Initialize the global cookie manager
/// Call this once at application startup
/// @param allocator: Allocator for the cookie manager
/// @param persist_path: Optional path to persist cookies to disk
pub fn initGlobal(allocator: Allocator, persist_path: ?[]const u8) !void {
    global_init_mutex.lock();
    defer global_init_mutex.unlock();

    if (global_cookie_manager != null) {
        return error.AlreadyInitialized;
    }

    global_cookie_manager = try CurlCookieManager.init(allocator, persist_path);
}

/// Deinitialize the global cookie manager
/// Call this at application shutdown
pub fn deinitGlobal() void {
    global_init_mutex.lock();
    defer global_init_mutex.unlock();

    if (global_cookie_manager) |manager| {
        manager.deinit();
        global_cookie_manager = null;
    }
}

/// Get the global cookie manager
/// Returns null if not initialized
pub fn getGlobal() ?*CurlCookieManager {
    return global_cookie_manager;
}

/// Get the global cookie manager, initializing with defaults if needed
/// This is a convenience method for simple use cases
pub fn getOrInitGlobal(allocator: Allocator) !*CurlCookieManager {
    global_init_mutex.lock();
    defer global_init_mutex.unlock();

    if (global_cookie_manager) |manager| {
        return manager;
    }

    global_cookie_manager = try CurlCookieManager.init(allocator, null);
    return global_cookie_manager.?;
}
```

## Global CookieStore Accessor

```zig
// In src/webidl/impls/CookieStore.zig

/// Global CookieStore instance (replaces Window.cookieStore until Window is implemented)
var global_cookie_store: ?*CookieStore = null;
var global_store_mutex: std.Thread.Mutex = .{};

/// Get the global CookieStore instance
/// Creates one if it doesn't exist, using the global CurlCookieManager
pub fn getGlobalCookieStore(allocator: Allocator) !*CookieStore {
    global_store_mutex.lock();
    defer global_store_mutex.unlock();

    if (global_cookie_store) |store| {
        return store;
    }

    // Get or create global cookie manager
    const curl_cookies = @import("../../fetch/network/curl_cookies.zig");
    const manager = try curl_cookies.getOrInitGlobal(allocator);

    global_cookie_store = try CookieStore.init(allocator, manager, null);
    return global_cookie_store.?;
}

/// Get the global CookieStore for a specific URL context
/// This is useful for creating context-specific cookie stores
pub fn getCookieStoreForUrl(allocator: Allocator, url: []const u8) !*CookieStore {
    const curl_cookies = @import("../../fetch/network/curl_cookies.zig");
    const manager = try curl_cookies.getOrInitGlobal(allocator);

    return CookieStore.init(allocator, manager, url);
}

/// Clean up global CookieStore
/// Call at application shutdown
pub fn deinitGlobalCookieStore() void {
    global_store_mutex.lock();
    defer global_store_mutex.unlock();

    if (global_cookie_store) |store| {
        store.deinit();
        global_cookie_store = null;
    }
}
```

