### Parse Serialized CSP

```zig
const std = @import("std");
const types = @import("types.zig");

/// Parse a serialized CSP string into a Policy object.
/// Spec: CSP Level 3 § 2.2.1
///
/// Algorithm:
/// 1. If serialized is a byte sequence, isomorphic decode it
/// 2. Let policy be a new policy with empty directive set
/// 3. For each token from strictly splitting on ';':
///    a. Strip leading/trailing whitespace
///    b. If empty or non-ASCII, continue
///    c. Let directive name be first token before whitespace
///    d. Lowercase directive name
///    e. If directive name already in policy, continue (first wins)
///    f. Let directive value be remaining tokens split on whitespace
///    g. Append new directive to policy's directive set
/// 4. Return policy
pub fn parseSerializedCSP(
    allocator: std.mem.Allocator,
    serialized: []const u8,
    source: types.PolicySource,
    disposition: types.PolicyDisposition,
) !types.Policy {
    var policy = types.Policy{
        .directive_set = types.DirectiveSet.init(allocator),
        .disposition = disposition,
        .source = source,
        .self_origin = null,
        .allocator = allocator,
    };

    // Split on semicolon
    var directive_tokens = std.mem.splitScalar(u8, serialized, ';');

    while (directive_tokens.next()) |token| {
        // Strip leading and trailing whitespace
        const trimmed = std.mem.trim(u8, token, &std.ascii.whitespace);

        if (trimmed.len == 0) continue;

        // Check if ASCII
        if (!isAscii(trimmed)) continue;

        // Extract directive name (first non-whitespace sequence)
        var name_end: usize = 0;
        while (name_end < trimmed.len and !std.ascii.isWhitespace(trimmed[name_end])) {
            name_end += 1;
        }

        // Lowercase directive name
        const directive_name = try allocator.alloc(u8, name_end);
        _ = std.ascii.lowerString(directive_name, trimmed[0..name_end]);

        // Skip if duplicate (first directive wins)
        if (policy.directive_set.items.contains(directive_name)) {
            allocator.free(directive_name);
            // TODO: Notify developer about duplicate directive
            continue;
        }

        // Parse directive value (split remaining on whitespace)
        var source_list = types.SourceList.init(allocator);

        if (name_end < trimmed.len) {
            const value_part = std.mem.trim(u8, trimmed[name_end..], &std.ascii.whitespace);

            var value_tokens = std.mem.tokenizeAny(u8, value_part, &std.ascii.whitespace);
            while (value_tokens.next()) |value_token| {
                const expr = try parseSourceExpression(allocator, value_token);
                try source_list.expressions.append(expr);
            }
        }

        // Create and append directive
        const directive = types.Directive{
            .name = directive_name,
            .value = source_list,
            .allocator = allocator,
        };

        try policy.directive_set.append(directive);
    }

    return policy;
}

/// Parse a source expression token
fn parseSourceExpression(
    allocator: std.mem.Allocator,
    token: []const u8,
) !types.SourceExpression {
    var expr = types.SourceExpression{
        .type = .host, // default
        .raw_value = try allocator.dupe(u8, token),
        .allocator = allocator,
    };

    // Check for keywords (case-insensitive, enclosed in single quotes)
    if (token.len >= 2 and token[0] == '\'' and token[token.len - 1] == '\'') {
        const keyword = std.ascii.lowerString(allocator, token[1..token.len-1]) catch token[1..token.len-1];
        defer allocator.free(keyword);

        if (std.mem.eql(u8, keyword, "none")) {
            expr.type = .keyword_none;
        } else if (std.mem.eql(u8, keyword, "self")) {
            expr.type = .keyword_self;
        } else if (std.mem.eql(u8, keyword, "unsafe-inline")) {
            expr.type = .keyword_unsafe_inline;
        } else if (std.mem.eql(u8, keyword, "unsafe-eval")) {
            expr.type = .keyword_unsafe_eval;
        } else if (std.mem.eql(u8, keyword, "unsafe-hashes")) {
            expr.type = .keyword_unsafe_hashes;
        } else if (std.mem.eql(u8, keyword, "strict-dynamic")) {
            expr.type = .keyword_strict_dynamic;
        } else if (std.mem.eql(u8, keyword, "wasm-unsafe-eval")) {
            expr.type = .keyword_wasm_unsafe_eval;
        } else if (std.mem.eql(u8, keyword, "report-sample")) {
            expr.type = .keyword_report_sample;
        } else if (std.mem.eql(u8, keyword, "trusted-types-eval")) {
            expr.type = .keyword_trusted_types_eval;
        } else if (std.mem.startsWith(u8, keyword, "nonce-")) {
            expr.type = .nonce;
            expr.nonce_value = try allocator.dupe(u8, keyword[6..]);
        } else if (std.mem.startsWith(u8, keyword, "sha256-") or
                   std.mem.startsWith(u8, keyword, "sha384-") or
                   std.mem.startsWith(u8, keyword, "sha512-")) {
            expr.type = .hash;
            expr.hash_algorithm = try allocator.dupe(u8, keyword[0..6]);
            expr.hash_value = try allocator.dupe(u8, keyword[7..]);
        }
    } else if (std.mem.indexOf(u8, token, ":") != null and
               std.mem.indexOf(u8, token, "/") == null) {
        // Scheme source (ends with : but no /)
        expr.type = .scheme;
        expr.scheme_part = try allocator.dupe(u8, token);
    } else {
        // Host source
        expr.type = .host;
        // TODO: Parse host, port, path components
    }

    return expr;
}

fn isAscii(str: []const u8) bool {
    for (str) |c| {
        if (c > 127) return false;
    }
    return true;
}
