// src/webidl/impls/Blob.zig

const std = @import("std");
const runtime = @import("runtime");
const file = @import("file");
const interfaces = @import("interfaces");
const dictionaries = @import("dictionaries");
const typedefs = @import("typedefs");

const Blob = interfaces.Blob;
const BlobData = file.BlobData;

pub const InternalState = struct {
    allocator: std.mem.Allocator,
    blob_data: *BlobData,

    pub fn init(allocator: std.mem.Allocator, blob_data: *BlobData) InternalState {
        return .{
            .allocator = allocator,
            .blob_data = blob_data,
        };
    }

    pub fn deinit(self: *InternalState) void {
        self.blob_data.deinit();
    }
};

// Global registry for internal state (following EventTarget pattern)
var internal_state_registry: std.AutoHashMap(usize, *InternalState) = undefined;
var registry_initialized: bool = false;

fn ensureRegistry() void {
    if (!registry_initialized) {
        internal_state_registry = std.AutoHashMap(usize, *InternalState).init(std.heap.page_allocator);
        registry_initialized = true;
    }
}

fn getInternal(instance: *runtime.Instance) ?*InternalState {
    ensureRegistry();
    return internal_state_registry.get(@intFromPtr(instance));
}

fn setInternal(instance: *runtime.Instance, internal: *InternalState) !void {
    ensureRegistry();
    try internal_state_registry.put(@intFromPtr(instance), internal);
}

// ============= Constructor =============

/// Blob() constructor
/// Spec: https://www.w3.org/TR/FileAPI/#constructorBlob
pub fn call_constructor(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    blobParts: ?[]const typedefs.BlobPart,
    options: dictionaries.BlobPropertyBag,
) !*runtime.Instance {
    // Step 1: If invoked with zero parameters, return empty Blob
    const bytes = if (blobParts) |parts|
        try file.algorithms.processBlobParts(allocator, parts, .{
            .endings = if (options.endings) |e|
                if (std.mem.eql(u8, e, "native")) .native else .transparent
            else
                .transparent,
        })
    else
        &[_]u8{};
    errdefer if (blobParts != null) allocator.free(bytes);

    // Step 3: Normalize type
    const mime_type = options.type orelse "";

    // Create BlobData
    const blob_data = try BlobData.init(allocator, bytes, mime_type);
    errdefer blob_data.deinit();

    // Free the intermediate bytes (BlobData made a copy)
    if (blobParts != null) allocator.free(bytes);

    // Create the Blob instance
    const instance = try Blob.init(allocator, Blob.State, &Blob.vtable, ctx);
    errdefer Blob.deinit(instance);

    // Store internal state
    const internal = try allocator.create(InternalState);
    internal.* = InternalState.init(allocator, blob_data);
    try setInternal(instance, internal);

    return instance;
}

// ============= Attributes =============

/// size attribute getter
/// Returns the size of the byte sequence in number of bytes
pub fn get_size(instance: *runtime.Instance) !u64 {
    const internal = getInternal(instance) orelse return 0;
    return internal.blob_data.size();
}

/// type attribute getter
/// Returns ASCII-encoded string in lower case representing the media type
pub fn get_type(instance: *runtime.Instance) !runtime.DOMString {
    const internal = getInternal(instance) orelse return runtime.DOMString.empty();
    return runtime.DOMString.fromSlice(internal.blob_data.getType());
}

// ============= Methods =============

/// slice() method
/// Returns a new Blob with bytes from start to end
pub fn call_slice(
    instance: *runtime.Instance,
    start: ?i64,
    end: ?i64,
    contentType: ?runtime.DOMString,
) !*runtime.Instance {
    const internal = getInternal(instance) orelse return error.InvalidState;
    const allocator = internal.allocator;
    const ctx = instance.ctx;

    // Get contentType as slice
    const ct = if (contentType) |ct_str| ct_str.asSlice() else null;

    // Run slice blob algorithm
    const sliced_data = try file.algorithms.sliceBlob(
        allocator,
        internal.blob_data,
        start,
        end,
        ct,
    );
    errdefer sliced_data.deinit();

    // Create new Blob instance for the slice
    const sliced_instance = try Blob.init(allocator, Blob.State, &Blob.vtable, ctx);
    errdefer Blob.deinit(sliced_instance);

    // Store internal state
    const sliced_internal = try allocator.create(InternalState);
    sliced_internal.* = InternalState.init(allocator, sliced_data);
    try setInternal(sliced_instance, sliced_internal);

    return sliced_instance;
}

// ============= Lifecycle =============

pub fn deinit(instance: *runtime.Instance) void {
    ensureRegistry();
    if (internal_state_registry.fetchRemove(@intFromPtr(instance))) |kv| {
        kv.value.deinit();
        kv.value.allocator.destroy(kv.value);
    }
}
```

