## Phase 5.3: Context Validation Module

### Overview
Implement context validation helpers for TestUtils. This ensures TestUtils.gc() is only called from appropriate contexts (Window or Worker) per the WebIDL [Exposed=(Window,Worker)] attribute.

### Specification Reference
```webidl
[Exposed=(Window,Worker)]
namespace TestUtils {
  [NewObject] Promise<undefined> gc();
};
```

The [Exposed] attribute means TestUtils.gc() should only be available in Window and Worker contexts, not in Worklets or other restricted environments.

### Implementation Details

#### File: `src/testutils/context.zig`

```zig
//! Context Validation for TestUtils
//!
//! Validates that TestUtils operations are called from appropriate
//! contexts per WebIDL [Exposed] attributes.
//!
//! ## WebIDL Exposure
//!
//! TestUtils is [Exposed=(Window,Worker)], meaning it's available in:
//! - Window (browser main document)
//! - DedicatedWorkerGlobalScope
//! - SharedWorkerGlobalScope
//! - ServiceWorkerGlobalScope
//!
//! It is NOT available in:
//! - Worklets (AudioWorklet, PaintWorklet, etc.)
//! - Other restricted contexts

const std = @import("std");
const runtime = @import("runtime");
const Exposure = runtime.Exposure;
const RealmInfo = runtime.RealmInfo;

/// Errors that can occur during context validation
pub const ExposureError = error{
    /// The API is not exposed in the current context type
    /// E.g., calling TestUtils.gc() from a Worklet
    NotExposedInContext,

    /// The context doesn't have realm info (shouldn't happen in practice)
    NoRealmInfo,
};

/// Validate that the current context is exposed to the given exposure
///
/// This checks the context's RealmInfo to determine if an API with
/// the given [Exposed] attribute is available.
///
/// ## Arguments
/// - ctx: Runtime context to validate
/// - exposure: Required exposure (from WebIDL [Exposed] attribute)
///
/// ## Returns
/// - void on success (context is valid)
/// - ExposureError.NotExposedInContext if context type doesn't match
///
/// ## Example
/// ```zig
/// // TestUtils is [Exposed=(Window,Worker)]
/// try validateExposure(ctx, .window_and_worker);
/// ```
pub fn validateExposure(
    ctx: runtime.Context,
    exposure: Exposure,
) ExposureError!void {
    const realm_info = ctx.getRealmInfo();

    if (!realm_info.isExposedTo(exposure)) {
        return ExposureError.NotExposedInContext;
    }
}

/// Check if TestUtils is exposed in the given context
///
/// Convenience function specifically for TestUtils validation.
/// Returns true if the context is Window or Worker.
pub fn isTestUtilsExposed(ctx: runtime.Context) bool {
    return ctx.getRealmInfo().isExposedTo(.window_and_worker);
}

/// Get a human-readable error message for exposure errors
///
/// Useful for error reporting and debugging.
pub fn exposureErrorMessage(
    ctx: runtime.Context,
    api_name: []const u8,
    required_exposure: Exposure,
) []const u8 {
    _ = required_exposure;
    const context_name = ctx.getRealmInfo().contextName();

    // Return static message (dynamic formatting would need allocator)
    _ = api_name;
    _ = context_name;
    return "API not exposed in current context";
}

// ============================================================================
// Tests
// ============================================================================

const testing = std.testing;

test "validateExposure - window context passes" {
    var ctx_data = try runtime.ContextData.init(testing.allocator, .{
        .realm_info = runtime.RealmInfo.forWindow(),
    });
    defer ctx_data.deinit();

    // Window should pass for window_and_worker exposure
    try validateExposure(&ctx_data, .window_and_worker);
    try validateExposure(&ctx_data, .window);
    try validateExposure(&ctx_data, .all);
}

test "validateExposure - worker context passes" {
    var ctx_data = try runtime.ContextData.init(testing.allocator, .{
        .realm_info = runtime.RealmInfo.forDedicatedWorker(),
    });
    defer ctx_data.deinit();

    // Worker should pass for window_and_worker exposure
    try validateExposure(&ctx_data, .window_and_worker);
    try validateExposure(&ctx_data, .worker);
    try validateExposure(&ctx_data, .all);
}

test "validateExposure - service worker passes" {
    var ctx_data = try runtime.ContextData.init(testing.allocator, .{
        .realm_info = runtime.RealmInfo.forServiceWorker(),
    });
    defer ctx_data.deinit();

    // ServiceWorker is a Worker, should pass
    try validateExposure(&ctx_data, .window_and_worker);
    try validateExposure(&ctx_data, .worker);
}

test "validateExposure - worklet fails" {
    var ctx_data = try runtime.ContextData.init(testing.allocator, .{
        .realm_info = runtime.RealmInfo.forWorklet(),
    });
    defer ctx_data.deinit();

    // Worklet should fail for window_and_worker exposure
    try testing.expectError(
        ExposureError.NotExposedInContext,
        validateExposure(&ctx_data, .window_and_worker),
