    try testing.expectError(
        ExposureError.NotExposedInContext,
        validateExposure(&ctx_data, .worker),
    );
}

test "isTestUtilsExposed - convenience function" {
    var window_ctx = try runtime.ContextData.init(testing.allocator, .{
        .realm_info = runtime.RealmInfo.forWindow(),
