    defer worker_ctx.deinit();

    var worklet_ctx = try runtime.ContextData.init(testing.allocator, .{
        .realm_info = runtime.RealmInfo.forWorklet(),
    });
    defer worklet_ctx.deinit();

    try testing.expect(isTestUtilsExposed(&window_ctx));
    try testing.expect(isTestUtilsExposed(&worker_ctx));
    try testing.expect(!isTestUtilsExposed(&worklet_ctx));
}
