pub fn benchmarkMemoryOverhead(allocator: std.mem.Allocator) !void {
    const baseline_mem = getMemoryUsage();

    var cache = WrapperCache.init(allocator, context);
    defer cache.deinit();

    // Add 1000 entries
    for (0..1000) |i| {
        const inst = createTestInstance(allocator);
