### Global State Management
```zig
//! Libcurl Network Backend - WHATWG Fetch Implementation
//!
//! Production network backend using statically-compiled libcurl.
//! Implements NetworkBackend interface for HTTP/HTTPS requests.
//!
//! Spec: https://fetch.spec.whatwg.org/#http-network-fetch

const std = @import("std");
const Allocator = std.mem.Allocator;
const backend = @import("backend.zig");
const NetworkBackend = backend.NetworkBackend;
const NetworkRequest = backend.NetworkRequest;
const NetworkResponse = backend.NetworkResponse;
const NetworkError = backend.NetworkError;
const HttpVersion = backend.HttpVersion;
const ConnectionTimingInfo = backend.ConnectionTimingInfo;
const curl = @import("curl_ffi.zig");
const curl_error = @import("curl_error.zig");

/// Global initialization state
var global_init_count: usize = 0;
var global_init_mutex: std.Thread.Mutex = .{};

/// Initialize libcurl globally (reference counted, thread-safe)
pub fn globalInit() !void {
    global_init_mutex.lock();
    defer global_init_mutex.unlock();

    if (global_init_count == 0) {
        const result = curl.curl_global_init(curl.CURL_GLOBAL_DEFAULT);
        if (result != curl.CURLE_OK) {
            return error.CurlGlobalInitFailed;
        }
    }
    global_init_count += 1;
}

/// Decrement global init reference count
pub fn globalCleanup() void {
    global_init_mutex.lock();
    defer global_init_mutex.unlock();

    if (global_init_count > 0) {
        global_init_count -= 1;
        if (global_init_count == 0) {
            curl.curl_global_cleanup();
        }
    }
}
```

### LibcurlBackend Structure
```zig
/// LibcurlBackend provides HTTP/HTTPS networking using libcurl.
///
/// Features:
/// - HTTP/1.0, HTTP/1.1, HTTP/2 support
/// - TLS with mbedTLS (certificate validation)
/// - Proxy support with authentication
/// - Connection and request timeouts
/// - Response body and header streaming
/// - Timing information for Resource Timing API
/// - Abort support via callback
pub const LibcurlBackend = struct {
    allocator: Allocator,
    handle: *curl.CURL,

    /// Abort flag - set to true to cancel in-progress request
    aborted: std.atomic.Value(bool),

    /// Response data accumulated during transfer
    response_headers: std.ArrayList(backend.NetworkResponse.Header),
    response_body: std.ArrayList(u8),

    /// Header list for request (must outlive curl_easy_perform)
    request_header_list: ?*curl.curl_slist,

    const Self = @This();

    /// Initialize a new libcurl backend.
    ///
    /// Calls curl_global_init if this is the first backend instance.
    /// Each backend instance gets its own easy handle.
    pub fn init(allocator: Allocator) !*Self {
        try globalInit();
        errdefer globalCleanup();

        const handle = curl.curl_easy_init() orelse {
            return error.CurlHandleInitFailed;
        };
        errdefer curl.curl_easy_cleanup(handle);

        const self = try allocator.create(Self);
        self.* = .{
            .allocator = allocator,
            .handle = handle,
            .aborted = std.atomic.Value(bool).init(false),
            .response_headers = std.ArrayList(backend.NetworkResponse.Header).init(allocator),
            .response_body = std.ArrayList(u8).init(allocator),
            .request_header_list = null,
        };

        return self;
    }

    /// Clean up libcurl backend.
    pub fn deinit(self: *Self) void {
        // Free header list if allocated
        if (self.request_header_list) |list| {
            curl.curl_slist_free_all(list);
        }

        // Free response data
        for (self.response_headers.items) |header| {
            self.allocator.free(header.name);
            self.allocator.free(header.value);
        }
        self.response_headers.deinit();
        self.response_body.deinit();

        // Cleanup curl handle
        curl.curl_easy_cleanup(self.handle);

        // Decrement global init count
        globalCleanup();

        self.allocator.destroy(self);
    }

    /// Get as NetworkBackend interface.
    pub fn asBackend(self: *Self) NetworkBackend {
        return .{
            .ptr = self,
            .vtable = &vtable,
        };
    }
