```zig
fn addCookiesToRequest(
    request: *InternalRequest,
    cookie_store: *CookieStore,
) !void {
    if (request.credentials_mode == .omit) {
        return; // Don't send cookies
    }

    // Get URL components
    const url = try parseUrl(request.currentUrl());

    // Get matching cookies
    const cookies = try cookie_store.getCookiesForRequest(
        url.host,
        url.path,
        url.scheme == "https",
        determineSameSiteStatus(request),
        .normal,
    );

    if (cookies.len > 0) {
        const cookie_header = try buildCookieHeader(cookies);
        try request.header_list.append("Cookie", cookie_header);
    }
}

fn extractCookiesFromResponse(
    response: *InternalResponse,
    request: *InternalRequest,
    cookie_store: *CookieStore,
) !void {
    if (request.credentials_mode == .omit) {
        return; // Don't store cookies
    }

    const url = try parseUrl(request.currentUrl());

    // Get all Set-Cookie headers
    const set_cookies = try response.header_list.getSetCookie(allocator);
    defer allocator.free(set_cookies);

    for (set_cookies) |set_cookie| {
        try cookie_store.setCookie(
            set_cookie,
            url.host,
            url.path,
            url.scheme == "https",
        );
    }
}
