pub const LibcurlBackend = struct {
    // Option: Use connection pool
    use_pool: bool,
    pool: ?*ConnectionPool,

    pub fn init(allocator: Allocator, options: InitOptions) !*Self {
        // ...
        if (options.use_connection_pool) {
            self.pool = try getGlobalPool(allocator);
        }
    }

    pub fn send(...) !NetworkResponse {
        if (self.pool) |pool| {
            return try self.sendWithPool(pool, request);
        } else {
            return try self.sendDirect(request);
        }
    }
