## delete() Method

```zig
/// Delete a cookie from the cookie store
///
/// Per CookieStore API spec:
/// - Sets the cookie with an expiry in the past
/// - Must match domain and path to delete correct cookie
///
/// @param options: Cookie delete options
/// @param context_url: The URL of the context (for default domain)
pub fn delete(
    self: *CurlCookieManager,
    options: CookieDeleteOptions,
    context_url: ?[]const u8,
) !void {
    // Determine effective domain
    const effective_domain = options.domain orelse blk: {
        if (context_url) |url| {
            const parsed = try parseUrlForMatching(url);
            break :blk parsed.host;
        }
        break :blk "";
    };

    // Determine effective path
    const effective_path = options.path orelse "/";

    // Format deletion cookie (Netscape format with expiry=1)
    const delete_str = try formatDeleteCookie(
        self.allocator,
        options.name,
        effective_domain,
        effective_path,
    );
    defer self.allocator.free(delete_str);

    // Add null terminator
    const delete_cstr = try self.allocator.dupeZ(u8, delete_str);
    defer self.allocator.free(delete_cstr);

    // Delete via libcurl
    self.mutex.lock();
    defer self.mutex.unlock();

    const result = curl.curl_easy_setopt(
        self.cookie_handle,
        curl.CURLOPT_COOKIELIST,
        delete_cstr.ptr,
    );

    if (result != curl.CURLE_OK) {
        return error.DeleteCookieFailed;
    }
}

/// Convenience method: delete cookie by name only
pub fn deleteByName(
    self: *CurlCookieManager,
    name: []const u8,
    context_url: ?[]const u8,
) !void {
    return self.delete(.{ .name = name }, context_url);
}

/// Delete all cookies matching a predicate
pub fn deleteMatching(
    self: *CurlCookieManager,
    predicate: *const fn (Cookie) bool,
) !usize {
    self.mutex.lock();
    defer self.mutex.unlock();

    // Get all cookies first
    var cookie_list: ?*curl.curl_slist = null;
    const result = curl.curl_easy_getinfo(
        self.cookie_handle,
        curl.CURLINFO_COOKIELIST,
        &cookie_list,
    );

    if (result != curl.CURLE_OK) {
        return error.GetInfoFailed;
    }
    defer curl.curl_slist_free_all(cookie_list);

    // Collect cookies to delete
    var to_delete = std.ArrayList(Cookie).init(self.allocator);
    defer {
        for (to_delete.items) |*cookie| {
            cookie.deinit();
        }
        to_delete.deinit();
    }

    var iter = curl.slistIterator(cookie_list);
    while (iter.next()) |cookie_str| {
        const cookie = try parseNetscapeCookie(self.allocator, std.mem.span(cookie_str));

        if (predicate(cookie)) {
            try to_delete.append(cookie);
        } else {
            cookie.deinit();
        }
    }

    // Delete each matching cookie (release lock temporarily to call delete)
    // Note: We already hold the lock, so we use internal delete logic
    for (to_delete.items) |cookie| {
        const delete_str = try formatDeleteCookie(
            self.allocator,
            cookie.name,
            cookie.domain,
            cookie.path,
        );
        defer self.allocator.free(delete_str);

        const delete_cstr = try self.allocator.dupeZ(u8, delete_str);
        defer self.allocator.free(delete_cstr);

        _ = curl.curl_easy_setopt(
            self.cookie_handle,
            curl.CURLOPT_COOKIELIST,
            delete_cstr.ptr,
        );
    }

    return to_delete.items.len;
}

/// Delete all cookies for a specific domain
pub fn deleteForDomain(self: *CurlCookieManager, domain: []const u8) !usize {
    return self.deleteMatching(struct {
        fn predicate(cookie: Cookie) bool {
            return domainMatches(cookie.domain, domain);
        }
    }.predicate);
}
```

