Implement the CSP directives specific to Trusted Types enforcement.

## Spec Reference
- Trusted Types spec § 4 (CSP Integration)
- trusted-types directive: TT spec § 4.3.1
- require-trusted-types-for directive: TT spec § 4.3.2

## Directives

### trusted-types directive

Controls which Trusted Type policy names can be created.

```
trusted-types <policy-name-list>
trusted-types <policy-name-list> 'allow-duplicates'
trusted-types 'none'
```

Examples:
- `trusted-types foo bar` - Allow policies named 'foo' and 'bar'
- `trusted-types *` - Allow any policy name (wildcard)
- `trusted-types 'none'` - No policies allowed
- `trusted-types foo 'allow-duplicates'` - Allow 'foo', allow duplicate names

### require-trusted-types-for directive

Enables enforcement for sink groups.

```
require-trusted-types-for 'script'
```

Currently only 'script' is defined (for DOM XSS sinks).

## File: src/csp/directives/trusted_types.zig

```zig
const std = @import("std");
const types = @import("../types.zig");

/// Trusted Types directive value keywords
pub const TT_KEYWORD_NONE = "'none'";
pub const TT_KEYWORD_ALLOW_DUPLICATES = "'allow-duplicates'";
pub const TT_WILDCARD = "*";

/// Check if a policy name is allowed by the trusted-types directive.
/// Spec: TT spec § 4.3.1
/// 
/// Algorithm (Should Trusted Type policy creation be blocked by CSP?):
/// 1. Let dominated be null
/// 2. For each policy in global's CSP list:
///    a. If policy disposition is not input disposition, continue
///    b. If policy does not contain 'trusted-types' directive, continue
///    c. Let dominated' be result of 'Does TT directive value allow name?'
///    d. If dominated' is false, set dominated to false
///    e. If dominated is null, set dominated to dominated'
/// 3. If dominated is false, return 'Blocked'
/// 4. Return 'Allowed'
pub fn shouldTrustedTypePolicyCreationBeBlocked(
    csp_list: *const types.CSPList,
    policy_name: []const u8,
    disposition: types.PolicyDisposition,
) enum { Allowed, Blocked } {
    var dominated: ?bool = null;

    for (csp_list.policies.items) |*policy| {
        if (policy.disposition != disposition) continue;

        const tt_directive = policy.getDirective("trusted-types") orelse continue;

        const allows = doesTrustedTypesDirectiveAllowName(
            &tt_directive.value,
            policy_name,
        );

        if (!allows) {
            dominated = false;
        } else if (dominated == null) {
            dominated = allows;
        }
    }

    if (dominated == false) {
        return .Blocked;
    }

    return .Allowed;
}

/// Check if a trusted-types directive value allows a policy name.
/// Spec: TT spec § 4.3.1.1
fn doesTrustedTypesDirectiveAllowName(
    source_list: *const types.SourceList,
    policy_name: []const u8,
) bool {
    // Empty directive value means nothing is allowed
    if (source_list.expressions.items.len == 0) {
        return false;
    }

    for (source_list.expressions.items) |expr| {
        // 'none' keyword - nothing allowed
        if (expr.type == .keyword_none) {
            return false;
        }

        // Wildcard (*) - everything allowed
        if (std.mem.eql(u8, expr.raw_value, TT_WILDCARD)) {
            return true;
        }

        // Skip 'allow-duplicates' keyword
        if (std.ascii.eqlIgnoreCase(expr.raw_value, TT_KEYWORD_ALLOW_DUPLICATES)) {
            continue;
        }

        // Check if policy name matches this expression
        if (std.mem.eql(u8, expr.raw_value, policy_name)) {
            return true;
        }
    }

    return false;
}

/// Check if duplicate policy names are allowed.
pub fn areDuplicatePolicyNamesAllowed(
    csp_list: *const types.CSPList,
) bool {
    for (csp_list.policies.items) |*policy| {
        const tt_directive = policy.getDirective("trusted-types") orelse continue;

        for (tt_directive.value.expressions.items) |expr| {
            if (std.ascii.eqlIgnoreCase(expr.raw_value, TT_KEYWORD_ALLOW_DUPLICATES)) {
                return true;
            }
        }
    }

    return false;
}
```

## File: src/csp/directives/require_trusted_types.zig

```zig
const std = @import("std");
const types = @import("../types.zig");

/// Sink groups that can be protected
pub const SINK_GROUP_SCRIPT = "'script'";

/// Check if a sink group requires Trusted Types.
/// Spec: TT spec § 4.3.3
///
/// Algorithm (Does sink type require trusted types?):
/// 1. For each policy in global's CSP list:
///    a. Let directive be result of getting 'require-trusted-types-for'
///    b. If directive is null, continue
///    c. If directive value does not contain sink group, continue
///    d. If policy disposition is 'enforce', return true
///    e. If includeReportOnly, return true
/// 2. Return false
pub fn doesSinkTypeRequireTrustedTypes(
    csp_list: *const types.CSPList,
    sink_group: []const u8,
    include_report_only: bool,
) bool {
    for (csp_list.policies.items) |*policy| {
        const directive = policy.getDirective("require-trusted-types-for") orelse continue;

        // Check if sink group is in directive value
        var contains_sink_group = false;
        for (directive.value.expressions.items) |expr| {
            if (std.ascii.eqlIgnoreCase(expr.raw_value, sink_group)) {
                contains_sink_group = true;
                break;
            }
        }

        if (!contains_sink_group) continue;

        if (policy.disposition == .enforce) {
            return true;
        }

        if (include_report_only) {
            return true;
        }
    }

    return false;
}

/// Check if enforcement is required for the 'script' sink group.
/// Convenience function for the most common case.
pub fn isScriptSinkEnforcementRequired(
    csp_list: *const types.CSPList,
) bool {
    return doesSinkTypeRequireTrustedTypes(csp_list, SINK_GROUP_SCRIPT, false);
}

/// Check if any Trusted Types enforcement is active (including report-only).
pub fn isTrustedTypesEnforcementActive(
    csp_list: *const types.CSPList,
) bool {
    return doesSinkTypeRequireTrustedTypes(csp_list, SINK_GROUP_SCRIPT, true);
}
```

