pub fn createPolicy(
    self: *TrustedTypePolicyFactory,
    policy_name: []const u8,
    options: TrustedTypePolicyOptions,
    global: *GlobalObject,
) !*TrustedTypePolicy {
    // Check CSP allows this policy name
    if (global.csp_list) |csp_list| {
        if (shouldTrustedTypePolicyCreationBeBlocked(csp_list, policy_name, .enforce) == .Blocked) {
            // Create and report violation
            return error.TypeError;
        }

        // Check for report-only violations
        if (shouldTrustedTypePolicyCreationBeBlocked(csp_list, policy_name, .report) == .Blocked) {
            // Report violation but don't block
        }

        // Check duplicate policy names
        if (!areDuplicatePolicyNamesAllowed(csp_list)) {
            if (self.created_policy_names.contains(policy_name)) {
                return error.TypeError;
            }
        }
    }

