### Task 1: send() Algorithm Structure

**File:** `src/xhr/algorithms/send.zig`

```zig
//! XMLHttpRequest send() Algorithm
//!
//! WHATWG XHR Spec: https://xhr.spec.whatwg.org/#the-send()-method
//!
//! The send() method initiates the request. It has two paths:
//! - Asynchronous: Returns immediately, fires events as response arrives
//! - Synchronous: Blocks until response complete (implemented in Week 5)

const std = @import("std");
const Allocator = std.mem.Allocator;
const XMLHttpRequest = @import("../../webidl/interfaces/XMLHttpRequest.zig").XMLHttpRequest;
const Fetch = @import("../../fetch/root.zig");
const InternalRequest = @import("../../fetch/internal/request.zig").InternalRequest;
const InternalResponse = @import("../../fetch/internal/response.zig").InternalResponse;
const Body = @import("../../fetch/internal/body.zig").Body;
const HeaderList = @import("../../fetch/internal/headers.zig").HeaderList;

/// Send request
///
/// Spec: https://xhr.spec.whatwg.org/#the-send()-method
pub fn send(
    xhr: *XMLHttpRequest,
    body: ?Body,
) !void {
    // Step 1: Validate state
    if (xhr.state.ready_state != .OPENED) {
        return error.InvalidStateError;
    }

    // Step 2: Check send flag
    if (xhr.state.send_flag) {
        return error.InvalidStateError;
    }

    // Step 3-7: Extract body (if provided)
    const extracted_body = if (body) |b|
        try extractBody(xhr.allocator, b)
    else
        null;

    // Step 8: Create Fetch request
    const req = try createFetchRequest(
        xhr.allocator,
        xhr.state.request_method.?,
        xhr.state.request_url.?,
        xhr.state.request_headers,
        extracted_body,
        xhr.state.with_credentials,
        xhr.state.timeout,
    );

    // Step 9: Detect upload listeners
    xhr.state.upload_listener_flag = hasUploadListeners(xhr.upload);

    // Step 10: Set upload complete flag
    if (extracted_body == null or extracted_body.?.length == 0) {
        xhr.state.upload_complete_flag = true;
    }

    // Step 11: Choose async or sync path
    if (!xhr.state.synchronous_flag) {
        // Async path (this week)
        try sendAsync(xhr, req);
    } else {
        // Sync path (Week 5)
        try sendSync(xhr, req);
    }
}

/// Extract body from input
///
/// Spec: https://fetch.spec.whatwg.org/#concept-bodyinit-extract
fn extractBody(allocator: Allocator, body: Body) !?Body {
    // This delegates to Fetch's body extraction
    return try Body.extract(allocator, body);
}

/// Create Fetch internal request
fn createFetchRequest(
    allocator: Allocator,
    method: []const u8,
    url: *URL,
    headers: HeaderList,
    body: ?Body,
    with_credentials: bool,
    timeout: u64,
) !*InternalRequest {
    const req = try InternalRequest.init(allocator);

    // Set request properties
    req.method = try allocator.dupe(u8, method);
    req.url = url;
    req.headers = try headers.clone(allocator);
    req.body = body;

    // XHR always uses CORS mode
    req.mode = .cors;

    // Credentials based on withCredentials
    req.credentials = if (with_credentials) .include else .same_origin;

    // Timeout
    if (timeout > 0) {
        req.timeout = timeout;
    }

    return req;
}

/// Check if upload has event listeners
fn hasUploadListeners(upload: *XMLHttpRequestUpload) bool {
    // Check if any event listeners are registered on upload object
    return upload.hasEventListeners();
}
