### Task 2: Async send() Implementation

**Continuation of `src/xhr/algorithms/send.zig`:**

```zig
/// Send request asynchronously
///
/// Spec step 11: Async path
fn sendAsync(xhr: *XMLHttpRequest, req: *InternalRequest) !void {
    // Set send flag
    xhr.state.send_flag = true;

    // Fire loadstart on upload if listeners
    if (xhr.state.upload_listener_flag) {
        try fireProgressEvent(xhr.upload, "loadstart", 0, null);
    }

    // Fire loadstart on xhr
    try fireProgressEvent(xhr, "loadstart", 0, null);

    // Create callback context
    const context = try xhr.allocator.create(AsyncContext);
    context.* = .{
        .xhr = xhr,
        .allocator = xhr.allocator,
    };

    // Start fetch with process callbacks
    xhr.state.fetch_controller = try Fetch.fetch(
        req,
        .{
            .processRequestBodyChunk = processRequestBodyChunkCallback,
            .processRequestEndOfBody = processRequestEndOfBodyCallback,
            .processResponse = processResponseCallback,
            .processResponseBodyChunk = processResponseBodyChunkCallback,
            .processResponseEndOfBody = processResponseEndOfBodyCallback,
        },
        context,
    );
}

const AsyncContext = struct {
    xhr: *XMLHttpRequest,
    allocator: Allocator,
};

/// Callback: Process request body chunk (upload progress)
fn processRequestBodyChunkCallback(
    chunk: []const u8,
    user_data: ?*anyopaque,
) void {
    const context: *AsyncContext = @ptrCast(@alignCast(user_data.?));
    processRequestBodyChunk(context.xhr, chunk) catch |err| {
        std.log.err("Failed to process request body chunk: {}", .{err});
    };
}

/// Callback: Process request end of body (upload complete)
fn processRequestEndOfBodyCallback(user_data: ?*anyopaque) void {
    const context: *AsyncContext = @ptrCast(@alignCast(user_data.?));
    processRequestEndOfBody(context.xhr) catch |err| {
        std.log.err("Failed to process request end of body: {}", .{err});
    };
}

/// Callback: Process response (headers received)
fn processResponseCallback(
    response: *InternalResponse,
    user_data: ?*anyopaque,
) void {
    const context: *AsyncContext = @ptrCast(@alignCast(user_data.?));
    processResponse(context.xhr, response) catch |err| {
        std.log.err("Failed to process response: {}", .{err});
    };
}

/// Callback: Process response body chunk
fn processResponseBodyChunkCallback(
    chunk: []const u8,
    user_data: ?*anyopaque,
) void {
    const context: *AsyncContext = @ptrCast(@alignCast(user_data.?));
    processResponseBodyChunk(context.xhr, chunk) catch |err| {
        std.log.err("Failed to process response body chunk: {}", .{err});
    };
}

/// Callback: Process response end of body
fn processResponseEndOfBodyCallback(user_data: ?*anyopaque) void {
    const context: *AsyncContext = @ptrCast(@alignCast(user_data.?));
    processResponseEndOfBody(context.xhr) catch |err| {
        std.log.err("Failed to process response end of body: {}", .{err});
    };

    // Cleanup context
    context.allocator.destroy(context);
}
