//! Upload Progress Tracking
//!
//! Spec: https://xhr.spec.whatwg.org/#upload-progress-events

const std = @import("std");
const XMLHttpRequest = @import("../../webidl/interfaces/XMLHttpRequest.zig").XMLHttpRequest;
const XMLHttpRequestUpload = @import("../../webidl/interfaces/XMLHttpRequestUpload.zig").XMLHttpRequestUpload;

/// Process request body chunk (upload progress)
pub fn processRequestBodyChunk(
    xhr: *XMLHttpRequest,
    chunk: []const u8,
) !void {
    if (xhr.state.upload_listener_flag and !xhr.state.upload_complete_flag) {
        // Track upload progress
        xhr.upload_tracker.onChunk(chunk.len);
    }
}

/// Process request end of body (upload complete)
pub fn processRequestEndOfBody(xhr: *XMLHttpRequest) !void {
    xhr.state.upload_complete_flag = true;

    if (xhr.state.upload_listener_flag) {
        // Fire final upload events
        const total = xhr.upload_tracker.total_bytes;
        try fireProgressEvent(xhr.upload, "progress", total, total);
        try fireProgressEvent(xhr.upload, "load", total, total);
        try fireProgressEvent(xhr.upload, "loadend", total, total);
    }
}
