```zig
const std = @import("std");
const XMLHttpRequest = @import("../../src/xhr/root.zig").XMLHttpRequest;
const MockFetch = @import("../mocks/fetch.zig").MockFetch;

test "send() - GET request succeeds" {
    const allocator = std.testing.allocator;

    var xhr = try XMLHttpRequest.init(allocator);
    defer xhr.deinit();

    try xhr.open("GET", "http://example.com/data", true, null, null);

    // Track events
    var events = std.ArrayList([]const u8).init(allocator);
    defer events.deinit();

    xhr.onloadstart = captureEvent(&events, "loadstart");
    xhr.onprogress = captureEvent(&events, "progress");
    xhr.onload = captureEvent(&events, "load");
    xhr.onloadend = captureEvent(&events, "loadend");
    xhr.onreadystatechange = captureEvent(&events, "readystatechange");

    // Mock successful response
    MockFetch.setResponse("test response data");

    try xhr.send(null);

    // Run event loop until complete
    try xhr.waitForCompletion();

    // Verify events fired in order
    try std.testing.expectEqualStrings("loadstart", events.items[0]);
    try std.testing.expectEqualStrings("readystatechange", events.items[1]); // HEADERS_RECEIVED
    try std.testing.expectEqualStrings("readystatechange", events.items[2]); // LOADING
    // progress events...
    try std.testing.expectEqualStrings("load", events.items[events.items.len - 2]);
    try std.testing.expectEqualStrings("loadend", events.items[events.items.len - 1]);

    // Verify state
    try std.testing.expectEqual(ReadyState.DONE, xhr.readyState);
    try std.testing.expectEqualStrings("test response data", xhr.responseText);
}

test "send() - POST with body" {
    const allocator = std.testing.allocator;

    var xhr = try XMLHttpRequest.init(allocator);
    defer xhr.deinit();

    try xhr.open("POST", "http://example.com/api", true, null, null);
    try xhr.setRequestHeader("Content-Type", "application/json");

    const body = "{\"hello\":\"world\"}";

    try xhr.send(body);
    try xhr.waitForCompletion();

    try std.testing.expectEqual(ReadyState.DONE, xhr.readyState);
}

test "send() - network error fires error event" {
    const allocator = std.testing.allocator;

    var xhr = try XMLHttpRequest.init(allocator);
    defer xhr.deinit();

    try xhr.open("GET", "http://example.com/fail", true, null, null);

    var error_fired = false;
    xhr.onerror = setFlag(&error_fired);

    MockFetch.setNetworkError();

    try xhr.send(null);
    try xhr.waitForCompletion();

    try std.testing.expect(error_fired);
    try std.testing.expectEqual(ReadyState.DONE, xhr.readyState);
}

test "send() - progress events are throttled" {
    const allocator = std.testing.allocator;

    var xhr = try XMLHttpRequest.init(allocator);
    defer xhr.deinit();

    try xhr.open("GET", "http://example.com/large", true, null, null);

    var progress_count: usize = 0;
    xhr.onprogress = countEvents(&progress_count);

    // Mock large response with many chunks
    MockFetch.setChunkedResponse(1024 * 100, 1024); // 100 chunks of 1KB

    try xhr.send(null);
    try xhr.waitForCompletion();

    // Progress events should be throttled (not 100 events)
    // 100KB / 50ms ~= 2000 events per second max
    // For 100 chunks, expect << 100 events
    try std.testing.expect(progress_count < 50);
}

test "send() - state transitions" {
    const allocator = std.testing.allocator;

    var xhr = try XMLHttpRequest.init(allocator);
    defer xhr.deinit();

    try xhr.open("GET", "http://example.com/data", true, null, null);

    var states = std.ArrayList(u16).init(allocator);
    defer states.deinit();

    xhr.onreadystatechange = captureState(&states, xhr);

    try xhr.send(null);
    try xhr.waitForCompletion();

    // Verify state progression
    try std.testing.expectEqual(@as(u16, 2), states.items[0]); // HEADERS_RECEIVED
    try std.testing.expectEqual(@as(u16, 3), states.items[1]); // LOADING
    try std.testing.expectEqual(@as(u16, 4), states.items[2]); // DONE
}

// Helper functions
fn captureEvent(events: *std.ArrayList([]const u8), name: []const u8) EventHandler {
    return struct {
        fn handler(event: *Event) void {
            events.append(name) catch {};
        }
    }.handler;
}

fn setFlag(flag: *bool) EventHandler {
    return struct {
        fn handler(event: *Event) void {
            flag.* = true;
        }
    }.handler;
}

fn countEvents(counter: *usize) EventHandler {
    return struct {
        fn handler(event: *Event) void {
            counter.* += 1;
        }
    }.handler;
}

fn captureState(states: *std.ArrayList(u16), xhr: *XMLHttpRequest) EventHandler {
    return struct {
        fn handler(event: *Event) void {
            states.append(xhr.readyState) catch {};
        }
    }.handler;
}
