```zig
const std = @import("std");
const Transport = @import("network/transport.zig").Transport;
const StateMachine = @import("connection/state_machine.zig").ConnectionStateMachine;
const SendBuffer = @import("connection/buffer.zig").SendBuffer;
const frame = @import("protocol/frame.zig");
const masking = @import("protocol/masking.zig");
const handshake_client = @import("handshake_client.zig");
const CloseCode = @import("protocol/close_codes.zig").CloseCode;
const Opcode = @import("protocol/opcodes.zig").Opcode;

/// WebSocket connection event callback
pub const EventCallback = *const fn (event: Event, user_data: ?*anyopaque) void;

/// Events emitted by WebSocket connection
pub const Event = union(enum) {
    /// Connection established
    open: OpenEvent,
    /// Message received
    message: MessageEvent,
    /// Error occurred
    @"error": ErrorEvent,
    /// Connection closed
    close: CloseEvent,
};

pub const OpenEvent = struct {
    /// Negotiated extensions
    extensions: ?[]const u8,
    /// Negotiated subprotocol
    protocol: ?[]const u8,
};

pub const MessageEvent = struct {
    /// Message data
    data: []const u8,
    /// True if text, false if binary
    is_text: bool,
};

pub const ErrorEvent = struct {
    // Per spec, we don't expose error details to script
};

pub const CloseEvent = struct {
    /// Close code
    code: u16,
    /// Close reason
    reason: []const u8,
    /// Whether close was clean
    was_clean: bool,
};

/// WebSocket connection
pub const WebSocketConnection = struct {
    /// Memory allocator
    allocator: std.mem.Allocator,

    /// Network transport (TCP or TLS)
    transport: ?Transport,

    /// Connection state machine
    state_machine: StateMachine,

    /// Send buffer
    send_buffer: SendBuffer,

    /// Receive buffer for partial frames
    recv_buffer: std.ArrayList(u8),

    /// Event callback
    on_event: ?EventCallback,
    on_event_user_data: ?*anyopaque,

    /// Connection URL
    url: []const u8,

    /// Negotiated protocol
    protocol: ?[]const u8,

    /// Negotiated extensions
    extensions: ?[]const u8,

    const Self = @This();

    /// Create a new WebSocket connection (starts in CONNECTING state)
    pub fn init(
        allocator: std.mem.Allocator,
        url: []const u8,
        options: ConnectOptions,
    ) !*Self {
        const self = try allocator.create(Self);
        errdefer allocator.destroy(self);

        self.* = .{
            .allocator = allocator,
            .transport = null,
            .state_machine = StateMachine.init(allocator),
            .send_buffer = SendBuffer.init(allocator, 0),
            .recv_buffer = std.ArrayList(u8).init(allocator),
            .on_event = null,
            .on_event_user_data = null,
            .url = try allocator.dupe(u8, url),
            .protocol = null,
            .extensions = null,
        };

        return self;
    }

    pub fn deinit(self: *Self) void {
        if (self.transport) |t| {
            t.close();
        }
        self.state_machine.deinit();
        self.send_buffer.deinit();
        self.recv_buffer.deinit();
        if (self.protocol) |p| self.allocator.free(p);
        if (self.extensions) |e| self.allocator.free(e);
        self.allocator.free(self.url);
        self.allocator.destroy(self);
    }

    /// Set event callback
    pub fn setEventCallback(
        self: *Self,
        callback: EventCallback,
        user_data: ?*anyopaque,
    ) void {
        self.on_event = callback;
        self.on_event_user_data = user_data;
    }

    /// Connect and perform handshake
    pub fn connect(self: *Self, options: ConnectOptions) !void {
        // Parse URL
        const parsed_url = try parseWebSocketUrl(self.url);

        // Establish transport
        self.transport = try Transport.connect(self.allocator, .{
            .host = parsed_url.host,
            .port = parsed_url.port orelse if (parsed_url.is_secure) 443 else 80,
            .use_tls = parsed_url.is_secure,
        });
        errdefer {
            self.transport.?.close();
            self.transport = null;
        }

        // Perform handshake
        const result = try handshake_client.performHandshake(
            self.allocator,
            self.transport.?,
            .{
                .url = parsed_url,
                .protocols = options.protocols,
            },
        );

        self.protocol = result.protocol;
        self.extensions = result.extensions;

        // Transition to OPEN
        _ = try self.state_machine.connectionEstablished();

        // Emit open event
        self.emitEvent(.{ .open = .{
            .extensions = self.extensions,
            .protocol = self.protocol,
        }});
    }

    /// Send a text message
    pub fn sendText(self: *Self, text: []const u8) !void {
        if (self.state_machine.state != .open) {
            return error.InvalidState;
        }

        try self.send_buffer.queueMessage(.text, text);
        try self.flushSendBuffer();
    }

    /// Send a binary message
    pub fn sendBinary(self: *Self, data: []const u8) !void {
        if (self.state_machine.state != .open) {
            return error.InvalidState;
        }

        try self.send_buffer.queueMessage(.binary, data);
        try self.flushSendBuffer();
    }

    /// Initiate close handshake
    pub fn close(self: *Self, code: ?u16, reason: ?[]const u8) !void {
        const close_code: CloseCode = if (code) |c| @enumFromInt(c) else .normal_closure;
        const close_reason = reason orelse "";

        try self.state_machine.initiateClose(close_code, close_reason);
        try self.sendCloseFrame(close_code, close_reason);
    }

    /// Process incoming data
    pub fn processIncoming(self: *Self) !void {
        const transport = self.transport orelse return;

        // Read available data
        var read_buffer: [4096]u8 = undefined;
        const n = transport.read(&read_buffer) catch |err| {
            if (err == error.ConnectionClosed) {
                self.handleAbnormalClose();
            }
            return err;
        };

        if (n == 0) {
            self.handleAbnormalClose();
            return;
        }

        try self.recv_buffer.appendSlice(read_buffer[0..n]);
        try self.processRecvBuffer();
    }

    fn processRecvBuffer(self: *Self) !void {
        while (true) {
            // Try to parse a frame
            const parse_result = frame.parseFrameHeader(self.recv_buffer.items, true) catch |err| {
                if (err == error.Incomplete) break;
                return err;
            };

            const header = parse_result.header;
            const header_size = parse_result.bytes_consumed;
            const total_frame_size = header_size + header.payload_length;

            // Do we have the full frame?
            if (self.recv_buffer.items.len < total_frame_size) break;

            // Extract payload
            const payload = self.recv_buffer.items[header_size..total_frame_size];

            // Unmask if needed (server should not mask, but be defensive)
            var payload_copy: []u8 = undefined;
            if (header.masked) {
                payload_copy = try self.allocator.dupe(u8, payload);
                masking.applyMask(payload_copy, header.masking_key);
            } else {
                payload_copy = try self.allocator.dupe(u8, payload);
            }
            defer self.allocator.free(payload_copy);

            // Process through state machine
            if (try self.state_machine.handleFrame(header, payload_copy)) |event| {
                self.handleStateEvent(event);
            }

            // Remove processed data
            const remaining = self.recv_buffer.items[total_frame_size..];
            @memcpy(self.recv_buffer.items[0..remaining.len], remaining);
            self.recv_buffer.shrinkRetainingCapacity(remaining.len);
        }
    }

    fn handleStateEvent(self: *Self, event: StateMachine.StateEvent) void {
        switch (event) {
            .message => |msg| {
                self.emitEvent(.{ .message = .{
                    .data = msg.data,
                    .is_text = msg.is_text,
                }});
            },
            .closed => |info| {
                self.emitEvent(.{ .close = .{
                    .code = @intFromEnum(info.code),
                    .reason = info.reason,
                    .was_clean = info.was_clean,
                }});
                self.cleanup();
            },
            .ping_received => |data| {
                self.sendPongFrame(data) catch {};
            },
            .pong_received => {},
            .opened => {}, // Already handled
            .@"error" => {
                self.emitEvent(.{ .@"error" = .{} });
            },
        }
    }

    fn flushSendBuffer(self: *Self) !void {
        const transport = self.transport orelse return;

        while (self.send_buffer.peekNext()) |msg| {
            // Build frame
            const masked = true; // Client must mask
            const key = masking.generateMaskingKey();
            const header_size = frame.headerSizeForPayload(msg.data.len, masked);

            var frame_buffer = try self.allocator.alloc(u8, header_size + msg.data.len);
            defer self.allocator.free(frame_buffer);

            _ = try frame.serializeFrameHeader(frame_buffer, .{
                .opcode = msg.opcode,
                .payload_length = msg.data.len,
                .mask = true,
            }, key);

            // Copy and mask payload
            @memcpy(frame_buffer[header_size..], msg.data);
            masking.applyMask(frame_buffer[header_size..], key);

            // Send
            try transport.writeAll(frame_buffer);

            self.send_buffer.markSent(msg.data.len);
        }
    }

    fn sendCloseFrame(self: *Self, code: CloseCode, reason: []const u8) !void {
        // Build close payload: 2-byte code + reason
        var payload: [125]u8 = undefined;
        std.mem.writeInt(u16, payload[0..2], @intFromEnum(code), .big);
        const reason_len = @min(reason.len, 123);
        @memcpy(payload[2..][0..reason_len], reason[0..reason_len]);

        try self.sendControlFrame(.close, payload[0 .. 2 + reason_len]);
        self.state_machine.closeFrameSent();
    }

    fn sendPongFrame(self: *Self, data: []const u8) !void {
        try self.sendControlFrame(.pong, data);
    }

    fn sendControlFrame(self: *Self, opcode: Opcode, payload: []const u8) !void {
        const transport = self.transport orelse return;
        const key = masking.generateMaskingKey();
        const header_size = frame.headerSizeForPayload(payload.len, true);

        var buffer: [131]u8 = undefined; // max control frame: 2 + 4 + 125
        _ = try frame.serializeFrameHeader(&buffer, .{
            .opcode = opcode,
            .payload_length = payload.len,
            .mask = true,
        }, key);

        @memcpy(buffer[header_size..][0..payload.len], payload);
        masking.applyMask(buffer[header_size..][0..payload.len], key);

        try transport.writeAll(buffer[0 .. header_size + payload.len]);
    }

    fn handleAbnormalClose(self: *Self) void {
        const event = self.state_machine.abnormalClose();
        self.handleStateEvent(event);
    }

    fn cleanup(self: *Self) void {
        if (self.transport) |t| {
            t.close();
            self.transport = null;
        }
    }

    fn emitEvent(self: *Self, event: Event) void {
        if (self.on_event) |callback| {
            callback(event, self.on_event_user_data);
        }
    }

    /// Get current ready state
    pub fn getReadyState(self: *Self) u2 {
        return @intFromEnum(self.state_machine.state);
    }

    /// Get buffered amount
    pub fn getBufferedAmount(self: *Self) u64 {
        return self.send_buffer.getBufferedAmount();
    }
};

pub const ConnectOptions = struct {
    /// Requested subprotocols
    protocols: []const []const u8 = &.{},
    /// Connection timeout in milliseconds
    timeout_ms: u32 = 30000,
};

fn parseWebSocketUrl(url: []const u8) !ParsedUrl {
