```zig
//! WebSocket Echo Client Example
//!
//! Demonstrates basic WebSocket usage:
//! - Connecting to a server
//! - Sending and receiving messages
//! - Handling events
//! - Clean shutdown

const std = @import("std");
const websocket = @import("websocket");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    std.debug.print("Connecting to WebSocket server...\n", .{});

    var ws = try websocket.WebSocketConnection.init(
        allocator,
        "wss://echo.websocket.org",
        .{},
    );
    defer ws.deinit();

    // Track connection state
    var connected = false;
    var message_count: usize = 0;

    ws.setEventCallback(struct {
        fn callback(event: websocket.Event, ctx: ?*anyopaque) void {
            const state = @ptrCast(*struct { connected: *bool, count: *usize }, ctx);

            switch (event) {
                .open => {
                    std.debug.print("✓ Connected!\n", .{});
                    state.connected.* = true;
                },
                .message => |msg| {
                    state.count.* += 1;
                    if (msg.is_text) {
                        std.debug.print("← Received [{d}]: {s}\n", .{state.count.*, msg.data});
                    } else {
                        std.debug.print("← Received [{d}]: {d} bytes binary\n", .{state.count.*, msg.data.len});
                    }
                },
                .close => |c| {
                    std.debug.print("Connection closed: {d} ({s})\n", .{c.code, c.reason});
                    state.connected.* = false;
                },
                .@"error" => {
                    std.debug.print("Error occurred\n", .{});
                    state.connected.* = false;
                },
            }
        }
    }.callback, &.{ .connected = &connected, .count = &message_count });

    // Connect
    try ws.connect(.{});

    // Wait for connection
    while (!connected) {
        try ws.processIncoming();
    }

    // Send messages
    const messages = [_][]const u8{
        "Hello, WebSocket!",
        "Testing 1, 2, 3...",
        "Goodbye!",
    };

    for (messages) |msg| {
        std.debug.print("→ Sending: {s}\n", .{msg});
        try ws.sendText(msg);

        // Wait for echo
        try ws.processIncoming();
    }

    // Clean close
    std.debug.print("Closing connection...\n", .{});
    try ws.close(1000, "Example complete");

    // Wait for close confirmation
    while (connected) {
        try ws.processIncoming();
    }

    std.debug.print("Done! Received {d} messages.\n", .{message_count});
}
```

