// TestUtils.gc() End-to-End JavaScript Tests
//
// These tests verify TestUtils.gc() behavior from JavaScript's perspective,
// simulating how web-platform-tests would use the API.
//
// Run with: zig build run-js-tests -Denable-test-utils=true

'use strict';

// Test utilities
const assert = (condition, message) => {
    if (!condition) {
        throw new Error(message || 'Assertion failed');
    }
};

const assertEqual = (actual, expected, message) => {
    if (actual !== expected) {
        throw new Error(message || `Expected ${expected}, got ${actual}`);
    }
};

const assertInstanceOf = (obj, type, message) => {
    if (!(obj instanceof type)) {
        throw new Error(message || `Expected instance of ${type.name}`);
    }
};

// ============================================================================
// Test: TestUtils namespace exists
// ============================================================================
async function testNamespaceExists() {
    assert(typeof TestUtils !== 'undefined', 'TestUtils should be defined');
    assert(typeof TestUtils === 'object', 'TestUtils should be an object');
    console.log('✓ TestUtils namespace exists');
}

// ============================================================================
// Test: gc() method exists
// ============================================================================
async function testGcMethodExists() {
    assert(typeof TestUtils.gc === 'function', 'TestUtils.gc should be a function');
    console.log('✓ TestUtils.gc method exists');
}

// ============================================================================
// Test: gc() returns a Promise
// ============================================================================
async function testGcReturnsPromise() {
    const result = TestUtils.gc();

    assertInstanceOf(result, Promise, 'gc() should return a Promise');
    console.log('✓ TestUtils.gc() returns a Promise');

    // Clean up - wait for promise to settle
    await result;
}

// ============================================================================
// Test: gc() Promise resolves to undefined
// ============================================================================
async function testGcResolvesToUndefined() {
    const result = await TestUtils.gc();

    assertEqual(result, undefined, 'gc() should resolve to undefined');
    console.log('✓ TestUtils.gc() resolves to undefined');
}

// ============================================================================
// Test: gc() can be called multiple times
// ============================================================================
async function testMultipleGcCalls() {
    const promise1 = TestUtils.gc();
    const promise2 = TestUtils.gc();
    const promise3 = TestUtils.gc();

    // All should be Promises
    assertInstanceOf(promise1, Promise);
    assertInstanceOf(promise2, Promise);
    assertInstanceOf(promise3, Promise);

    // All should resolve
    const results = await Promise.all([promise1, promise2, promise3]);

    // All should resolve to undefined
    results.forEach((result, i) => {
        assertEqual(result, undefined, `gc() call ${i+1} should resolve to undefined`);
    });

    console.log('✓ Multiple TestUtils.gc() calls work correctly');
}

// ============================================================================
// Test: gc() can be awaited sequentially
// ============================================================================
async function testSequentialGcCalls() {
    const result1 = await TestUtils.gc();
    const result2 = await TestUtils.gc();
    const result3 = await TestUtils.gc();

    assertEqual(result1, undefined);
    assertEqual(result2, undefined);
    assertEqual(result3, undefined);

    console.log('✓ Sequential TestUtils.gc() calls work correctly');
}

// ============================================================================
// Test: gc() with Promise.race
// ============================================================================
async function testGcWithPromiseRace() {
    // Create a gc() promise and a timer promise
    const gcPromise = TestUtils.gc();
    const timerPromise = new Promise(resolve => setTimeout(() => resolve('timeout'), 5000));

    // gc() should resolve before the 5 second timeout
    const result = await Promise.race([gcPromise, timerPromise]);

    // If gc() resolved first, result is undefined
    // If timer resolved first, something is wrong
    assertEqual(result, undefined, 'gc() should resolve before 5 second timeout');

    console.log('✓ TestUtils.gc() resolves in reasonable time');
}

// ============================================================================
// Test: gc() in async function works correctly
// ============================================================================
async function testGcInAsyncFunction() {
    async function triggerGc() {
        await TestUtils.gc();
        return 'gc completed';
    }

    const result = await triggerGc();
    assertEqual(result, 'gc completed');

    console.log('✓ TestUtils.gc() works in async functions');
}

// ============================================================================
// Test: gc() with .then() chaining
// ============================================================================
async function testGcWithThenChaining() {
    let chainCalled = false;

    await TestUtils.gc()
        .then(result => {
            chainCalled = true;
            assertEqual(result, undefined, '.then() receives undefined');
            return 'chained';
        })
        .then(result => {
            assertEqual(result, 'chained', 'Chaining works');
        });

    assert(chainCalled, '.then() handler should be called');

    console.log('✓ TestUtils.gc() works with .then() chaining');
}

// ============================================================================
// Test: gc() actually collects garbage (best-effort)
// ============================================================================
async function testGcActuallyCollects() {
    // This is a best-effort test - GC behavior is not strictly guaranteed
    // We create objects and WeakRefs, trigger GC, and check if refs were cleared

    let weakRef;

    // Create object in a block scope so it becomes unreachable
    {
        const largeObject = {
            data: new Array(10000).fill(Math.random())
        };
        weakRef = new WeakRef(largeObject);
    }

    // Trigger GC
    await TestUtils.gc();

    // The weak ref might still hold the object (GC is not guaranteed)
    // This is more of a smoke test to ensure gc() doesn't break anything
    // In practice, after a full GC, the weak ref should be cleared

    // We don't strictly assert here since GC timing is implementation-defined
    const derefResult = weakRef.deref();
    if (derefResult === undefined) {
        console.log('✓ TestUtils.gc() appears to have collected garbage');
    } else {
        console.log('✓ TestUtils.gc() completed (GC timing is implementation-defined)');
    }
}

// ============================================================================
// Test: gc() error handling (Promise rejection handling)
// ============================================================================
async function testGcErrorHandling() {
    // gc() should not reject under normal circumstances
    // This test verifies we can handle rejections if they occur

    let caughtError = null;

    try {
        await TestUtils.gc();
    } catch (error) {
        caughtError = error;
    }

    // Should not have caught any error
    assertEqual(caughtError, null, 'gc() should not reject');

    console.log('✓ TestUtils.gc() does not reject');
}

// ============================================================================
// Test: gc() with finally clause
// ============================================================================
async function testGcWithFinally() {
    let finallyCalled = false;

    try {
        await TestUtils.gc();
    } finally {
        finallyCalled = true;
    }

    assert(finallyCalled, 'finally should be called');

    console.log('✓ TestUtils.gc() works with try/finally');
}

// ============================================================================
// Run all tests
// ============================================================================
async function runAllTests() {
    console.log('\n=== TestUtils.gc() E2E Tests ===\n');

    const tests = [
        testNamespaceExists,
        testGcMethodExists,
        testGcReturnsPromise,
        testGcResolvesToUndefined,
        testMultipleGcCalls,
        testSequentialGcCalls,
        testGcWithPromiseRace,
        testGcInAsyncFunction,
        testGcWithThenChaining,
        testGcActuallyCollects,
        testGcErrorHandling,
        testGcWithFinally,
    ];

    let passed = 0;
    let failed = 0;

    for (const test of tests) {
        try {
            await test();
            passed++;
        } catch (error) {
            console.error(`✗ ${test.name}: ${error.message}`);
            failed++;
        }
    }

    console.log(`\n=== Results: ${passed} passed, ${failed} failed ===\n`);

    if (failed > 0) {
        throw new Error(`${failed} tests failed`);
    }

    console.log('All TestUtils.gc() E2E tests passed!');
}

// Execute tests
runAllTests().catch(error => {
    console.error('Test suite failed:', error);
    process.exit(1);
});
