### get()
```zig
/// Get a single cookie by name, optionally filtered by URL
/// Returns the first matching cookie or null if not found
///
/// @param name: Cookie name to find (null = any name, return first)
/// @param url: Optional URL to filter by domain/path matching
/// @return: Cookie if found, null otherwise
pub fn get(
    self: *CurlCookieManager,
    name: ?[]const u8,
    url: ?[]const u8,
) !?Cookie {
    self.mutex.lock();
    defer self.mutex.unlock();

    // Get cookie list from libcurl
    var cookie_list: ?*curl.curl_slist = null;
    const result = curl.curl_easy_getinfo(
        self.cookie_handle,
        curl.CURLINFO_COOKIELIST,
        &cookie_list,
    );

    if (result != curl.CURLE_OK) {
        return error.GetInfoFailed;
    }

    defer curl.curl_slist_free_all(cookie_list);

    // Parse URL for domain/path matching
    const parsed_url = if (url) |u| try parseUrlForMatching(u) else null;

    // Iterate and find matching cookie
    var iter = curl.slistIterator(cookie_list);
    while (iter.next()) |cookie_str| {
        const cookie = try parseNetscapeCookie(self.allocator, std.mem.span(cookie_str));
        errdefer cookie.deinit();

        // Check name match
        if (name) |n| {
            if (!std.mem.eql(u8, cookie.name, n)) {
                cookie.deinit();
                continue;
            }
        }

        // Check URL match (domain and path)
        if (parsed_url) |pu| {
            if (!cookieMatchesUrl(cookie, pu)) {
                cookie.deinit();
                continue;
            }
        }

        // Found matching cookie
        return cookie;
    }

    return null;
}
```

### getAll()
```zig
/// Get all cookies, optionally filtered by name and/or URL
///
/// @param name: Cookie name to filter (null = all names)
/// @param url: Optional URL to filter by domain/path matching
/// @return: ArrayList of matching cookies (caller owns memory)
pub fn getAll(
    self: *CurlCookieManager,
    name: ?[]const u8,
    url: ?[]const u8,
) !std.ArrayList(Cookie) {
    self.mutex.lock();
    defer self.mutex.unlock();

    var cookies = std.ArrayList(Cookie).init(self.allocator);
    errdefer {
        for (cookies.items) |*cookie| {
            cookie.deinit();
        }
        cookies.deinit();
    }

    // Get cookie list from libcurl
    var cookie_list: ?*curl.curl_slist = null;
    const result = curl.curl_easy_getinfo(
        self.cookie_handle,
        curl.CURLINFO_COOKIELIST,
        &cookie_list,
    );

    if (result != curl.CURLE_OK) {
        return error.GetInfoFailed;
    }

    defer curl.curl_slist_free_all(cookie_list);

    // Parse URL for domain/path matching
    const parsed_url = if (url) |u| try parseUrlForMatching(u) else null;

    // Iterate and collect matching cookies
    var iter = curl.slistIterator(cookie_list);
    while (iter.next()) |cookie_str| {
        const cookie = try parseNetscapeCookie(self.allocator, std.mem.span(cookie_str));
        errdefer cookie.deinit();

        // Check name match
        if (name) |n| {
            if (!std.mem.eql(u8, cookie.name, n)) {
                cookie.deinit();
                continue;
            }
        }

        // Check URL match
        if (parsed_url) |pu| {
            if (!cookieMatchesUrl(cookie, pu)) {
                cookie.deinit();
                continue;
            }
        }

        try cookies.append(cookie);
    }

    return cookies;
}
