## Core Struct

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const curl = @import("curl_ffi.zig");

/// Thread-safe cookie manager using libcurl's shared cookie engine.
/// Provides unified cookie storage for Fetch API, WebSocket, and CookieStore API.
pub const CurlCookieManager = struct {
    /// Shared handle for cookie storage across multiple CURL handles
    share_handle: *curl.CURLSH,

    /// Dedicated CURL handle for cookie manipulation (get/set/delete)
    /// This handle is never used for actual HTTP requests
    cookie_handle: *curl.CURL,

    /// Allocator for internal allocations
    allocator: Allocator,

    /// Mutex for thread-safe cookie operations
    mutex: std.Thread.Mutex,

    /// Whether to persist cookies to disk
    persist_path: ?[]const u8,

    /// Initialize a new CurlCookieManager
    /// @param allocator: Allocator for internal use
    /// @param persist_path: Optional file path to persist cookies (null = memory only)
    pub fn init(allocator: Allocator, persist_path: ?[]const u8) !*CurlCookieManager {
        const self = try allocator.create(CurlCookieManager);
        errdefer allocator.destroy(self);

        // Initialize share handle
        const share = curl.curl_share_init() orelse return error.ShareInitFailed;
        errdefer _ = curl.curl_share_cleanup(share);

        // Enable cookie sharing
        var result = curl.curl_share_setopt(share, curl.CURLSHOPT_SHARE, curl.CURL_LOCK_DATA_COOKIE);
        if (result != curl.CURLSHE_OK) return error.ShareSetoptFailed;

        // Set lock functions for thread safety
        result = curl.curl_share_setopt(share, curl.CURLSHOPT_LOCKFUNC, lockCallback);
        if (result != curl.CURLSHE_OK) return error.ShareSetoptFailed;
        result = curl.curl_share_setopt(share, curl.CURLSHOPT_UNLOCKFUNC, unlockCallback);
        if (result != curl.CURLSHE_OK) return error.ShareSetoptFailed;
        result = curl.curl_share_setopt(share, curl.CURLSHOPT_USERDATA, self);
        if (result != curl.CURLSHE_OK) return error.ShareSetoptFailed;

        // Initialize dedicated cookie handle
        const cookie_handle = curl.curl_easy_init() orelse return error.EasyInitFailed;
        errdefer curl.curl_easy_cleanup(cookie_handle);

        // Attach share handle
        _ = curl.curl_easy_setopt(cookie_handle, curl.CURLOPT_SHARE, share);

        // Enable cookie engine
        if (persist_path) |path| {
            // Read from file on init, write on cleanup
            _ = curl.curl_easy_setopt(cookie_handle, curl.CURLOPT_COOKIEFILE, path.ptr);
            _ = curl.curl_easy_setopt(cookie_handle, curl.CURLOPT_COOKIEJAR, path.ptr);
        } else {
            // Memory-only mode (empty string enables engine)
            _ = curl.curl_easy_setopt(cookie_handle, curl.CURLOPT_COOKIEFILE, "");
        }

        self.* = .{
            .share_handle = share,
            .cookie_handle = cookie_handle,
            .allocator = allocator,
            .mutex = .{},
            .persist_path = if (persist_path) |p| try allocator.dupe(u8, p) else null,
        };

        return self;
    }

    /// Clean up all resources
    pub fn deinit(self: *CurlCookieManager) void {
        // Flush cookies to file if persisting
        if (self.persist_path != null) {
            _ = curl.curl_easy_setopt(self.cookie_handle, curl.CURLOPT_COOKIELIST, "FLUSH");
        }

        curl.curl_easy_cleanup(self.cookie_handle);
        _ = curl.curl_share_cleanup(self.share_handle);

        if (self.persist_path) |path| {
            self.allocator.free(path);
        }

        self.allocator.destroy(self);
    }

    /// Attach this cookie manager to a CURL easy handle
    /// Call this before performing HTTP requests to share cookies
    pub fn attachToHandle(self: *CurlCookieManager, handle: *curl.CURL) void {
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_SHARE, self.share_handle);
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_COOKIEFILE, "");
    }

    /// Flush cookies to disk (if persistence enabled)
    pub fn flush(self: *CurlCookieManager) void {
        if (self.persist_path != null) {
            self.mutex.lock();
            defer self.mutex.unlock();
            _ = curl.curl_easy_setopt(self.cookie_handle, curl.CURLOPT_COOKIELIST, "FLUSH");
        }
    }

    /// Clear all session cookies (cookies without expiry)
    pub fn clearSessionCookies(self: *CurlCookieManager) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        _ = curl.curl_easy_setopt(self.cookie_handle, curl.CURLOPT_COOKIELIST, "SESS");
    }

    /// Clear all cookies
    pub fn clearAll(self: *CurlCookieManager) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        _ = curl.curl_easy_setopt(self.cookie_handle, curl.CURLOPT_COOKIELIST, "ALL");
    }

    // Lock callback for CURLSH thread safety
    fn lockCallback(
        handle: *curl.CURL,
        data: c_int,
        access: c_int,
        userptr: ?*anyopaque,
    ) callconv(.C) void {
        _ = handle;
        _ = data;
        _ = access;
        if (userptr) |ptr| {
            const self: *CurlCookieManager = @ptrCast(@alignCast(ptr));
            self.mutex.lock();
        }
    }

    // Unlock callback for CURLSH thread safety
    fn unlockCallback(
        handle: *curl.CURL,
        data: c_int,
        userptr: ?*anyopaque,
    ) callconv(.C) void {
        _ = handle;
        _ = data;
        if (userptr) |ptr| {
            const self: *CurlCookieManager = @ptrCast(@alignCast(ptr));
            self.mutex.unlock();
        }
    }
};
