const std = @import("std");

/// Namespace constants
pub const HTML_NAMESPACE = "http://www.w3.org/1999/xhtml";
pub const SVG_NAMESPACE = "http://www.w3.org/2000/svg";
pub const XLINK_NAMESPACE = "http://www.w3.org/1999/xlink";

/// Trusted Type names as returned by getPropertyType/getAttributeType
pub const TRUSTED_HTML = "TrustedHTML";
pub const TRUSTED_SCRIPT = "TrustedScript";
pub const TRUSTED_SCRIPT_URL = "TrustedScriptURL";

/// Get the required Trusted Type for an element's IDL attribute (property).
/// 
/// Algorithm:
/// 1. Set localName to tagName in ASCII lowercase
/// 2. If elementNs is null or empty, set to HTML namespace
/// 3. Let interface be the element interface for localName and elementNs
/// 4. Find matching row in property table
/// 5. Return the TrustedType name or null
pub fn getPropertyType(
    tag_name: []const u8,
    property: []const u8,
    element_ns: ?[]const u8,
) ?[]const u8 {
    // Normalize tag name to lowercase
    var lower_tag: [64]u8 = undefined;
    const tag_lower = std.ascii.lowerString(lower_tag[0..@min(tag_name.len, 64)], tag_name);

    // Default to HTML namespace
    const ns = element_ns orelse HTML_NAMESPACE;
    const is_html = std.mem.eql(u8, ns, HTML_NAMESPACE) or ns.len == 0;
    const is_svg = std.mem.eql(u8, ns, SVG_NAMESPACE);

    // Check property-specific requirements

    // innerHTML and outerHTML apply to any element
    if (std.mem.eql(u8, property, "innerHTML") or 
        std.mem.eql(u8, property, "outerHTML")) {
        return TRUSTED_HTML;
    }

    // HTMLIFrameElement.srcdoc
    if (is_html and std.mem.eql(u8, tag_lower, "iframe") and
        std.mem.eql(u8, property, "srcdoc")) {
        return TRUSTED_HTML;
    }

    // HTMLScriptElement properties
    if (is_html and std.mem.eql(u8, tag_lower, "script")) {
        if (std.mem.eql(u8, property, "src")) {
            return TRUSTED_SCRIPT_URL;
        }
        if (std.mem.eql(u8, property, "innerText") or
            std.mem.eql(u8, property, "text") or
            std.mem.eql(u8, property, "textContent")) {
            return TRUSTED_SCRIPT;
        }
    }

    // SVGScriptElement properties
    if (is_svg and std.mem.eql(u8, tag_lower, "script")) {
        if (std.mem.eql(u8, property, "href")) {
            return TRUSTED_SCRIPT_URL;
        }
        if (std.mem.eql(u8, property, "innerText") or
            std.mem.eql(u8, property, "text") or
            std.mem.eql(u8, property, "textContent")) {
            return TRUSTED_SCRIPT;
        }
    }

    return null;
}

/// Get the required Trusted Type for an element's content attribute.
///
/// Algorithm:
/// 1. Set localName to tagName in ASCII lowercase
/// 2. If elementNs is null or empty, set to HTML namespace  
/// 3. Let interface be the element interface for localName and elementNs
/// 4. Find matching row in attribute table (considering attrNs)
/// 5. Return the TrustedType name or null
pub fn getAttributeType(
    tag_name: []const u8,
    attribute: []const u8,
    element_ns: ?[]const u8,
    attr_ns: ?[]const u8,
) ?[]const u8 {
    // Normalize tag name to lowercase
    var lower_tag: [64]u8 = undefined;
    const tag_lower = std.ascii.lowerString(lower_tag[0..@min(tag_name.len, 64)], tag_name);

    // Normalize attribute name to lowercase
    var lower_attr: [64]u8 = undefined;
    const attr_lower = std.ascii.lowerString(lower_attr[0..@min(attribute.len, 64)], attribute);

    // Default to HTML namespace
    const ns = element_ns orelse HTML_NAMESPACE;
    const is_html = std.mem.eql(u8, ns, HTML_NAMESPACE) or ns.len == 0;
    const is_svg = std.mem.eql(u8, ns, SVG_NAMESPACE);

    // HTMLIFrameElement srcdoc attribute
    if (is_html and std.mem.eql(u8, tag_lower, "iframe") and
        std.mem.eql(u8, attr_lower, "srcdoc")) {
        return TRUSTED_HTML;
    }

    // HTMLScriptElement src attribute
    if (is_html and std.mem.eql(u8, tag_lower, "script") and
        std.mem.eql(u8, attr_lower, "src")) {
        return TRUSTED_SCRIPT_URL;
    }

    // SVGScriptElement href attribute
    if (is_svg and std.mem.eql(u8, tag_lower, "script") and
        std.mem.eql(u8, attr_lower, "href")) {
        // Check for xlink namespace variant
        if (attr_ns) |ans| {
            if (std.mem.eql(u8, ans, XLINK_NAMESPACE)) {
                return TRUSTED_SCRIPT_URL;
            }
        }
        // No namespace or HTML namespace
        return TRUSTED_SCRIPT_URL;
    }

    // Event handler attributes (on*)
    if (attr_lower.len > 2 and std.mem.startsWith(u8, attr_lower, "on")) {
        // Check if it's a known event handler
        if (isEventHandlerAttribute(attr_lower)) {
            return TRUSTED_SCRIPT;
        }
    }

    return null;
}

/// Check if an attribute name is an event handler (onclick, onload, etc.)
fn isEventHandlerAttribute(attr: []const u8) bool {
    const event_handlers = [_][]const u8{
        "onabort", "onauxclick", "onbeforeinput", "onbeforematch", 
        "onbeforetoggle", "onblur", "oncancel", "oncanplay",
        "oncanplaythrough", "onchange", "onclick", "onclose",
        "oncontextlost", "oncontextmenu", "oncontextrestored",
        "oncopy", "oncuechange", "oncut", "ondblclick", "ondrag",
        "ondragend", "ondragenter", "ondragleave", "ondragover",
        "ondragstart", "ondrop", "ondurationchange", "onemptied",
        "onended", "onerror", "onfocus", "onformdata", "oninput",
        "oninvalid", "onkeydown", "onkeypress", "onkeyup", "onload",
        "onloadeddata", "onloadedmetadata", "onloadstart", "onmousedown",
        "onmouseenter", "onmouseleave", "onmousemove", "onmouseout",
        "onmouseover", "onmouseup", "onpaste", "onpause", "onplay",
        "onplaying", "onprogress", "onratechange", "onreset", "onresize",
        "onscroll", "onscrollend", "onsecuritypolicyviolation", "onseeked",
        "onseeking", "onselect", "onslotchange", "onstalled", "onsubmit",
        "onsuspend", "ontimeupdate", "ontoggle", "onvolumechange", "onwaiting",
        "onwheel",
    };

    for (event_handlers) |handler| {
        if (std.mem.eql(u8, attr, handler)) {
            return true;
        }
    }
    return false;
}

