### CORS Preflight Fetch
```zig
/// Perform CORS-preflight fetch.
///
/// Algorithm:
/// 1. Let preflight be new request with:
///    - method = OPTIONS
///    - URL = request's current URL
///    - initiator = "" 
///    - destination = ""
///    - mode = "cors"
///    - credentials mode = "same-origin" (omit for preflight)
///    - response tainting = "cors"
///    - referrer = "no-referrer"
/// 2. Append Access-Control-Request-Method with request's method
/// 3. Let headers be CORS-unsafe request-header names for request
/// 4. If headers is not empty, append Access-Control-Request-Headers
/// 5. Let response be result of HTTP-network-or-cache fetch with preflight
/// 6. If CORS check fails, return network error
/// 7. If response status is not ok status, return network error
/// 8. Parse Access-Control-Allow-Methods, Access-Control-Allow-Headers
/// 9. If method not in allowed methods (considering *), return network error
/// 10. If headers not all in allowed headers (considering *), return network error
/// 11. If credentials and wildcard used, return network error
/// 12. Parse Access-Control-Max-Age, create cache entry
/// 13. Return response
pub fn corsPreflightFetch(
    allocator: std.mem.Allocator,
    request: *InternalRequest,
    network_backend: *NetworkBackend,
) !*InternalResponse
```

### Create Preflight Request
```zig
/// Create the OPTIONS preflight request.
fn createPreflightRequest(
    allocator: std.mem.Allocator,
    request: *InternalRequest,
) !*InternalRequest {
    var preflight = try allocator.create(InternalRequest);
    preflight.* = .{
        .allocator = allocator,
        .method = "OPTIONS",
        .url = request.currentUrl().*,
        .header_list = try HeaderList.init(allocator),
        .initiator = .empty,
        .destination = .empty,
        .mode = .cors,
        .credentials_mode = .same_origin,
        .response_tainting = .cors,
        .referrer = .no_referrer,
        .client = request.client,
    };

    // Add Access-Control-Request-Method
    try preflight.header_list.append(
        "Access-Control-Request-Method",
        request.method,
    );

    // Add Access-Control-Request-Headers if needed
    const unsafe_headers = try getCORSUnsafeRequestHeaderNames(
        allocator, 
        request.header_list
    );
    if (unsafe_headers.len > 0) {
        const headers_value = try std.mem.join(allocator, ", ", unsafe_headers);
        try preflight.header_list.append(
            "Access-Control-Request-Headers",
            headers_value,
        );
    }

    return preflight;
}
```

### Validate Preflight Response
```zig
/// Validate preflight response against request.
fn validatePreflightResponse(
    request: *InternalRequest,
    response: *InternalResponse,
) !void {
    // Check CORS
    if (!corsCheck(request, response)) {
        return error.CorsError;
    }

    // Check status
    if (!isOkStatus(response.status)) {
        return error.PreflightFailed;
    }

    // Parse allowed methods
    const methods = try parseAllowedMethods(response.header_list);
    if (!isMethodAllowed(request.method, methods, request.credentials_mode)) {
        return error.MethodNotAllowed;
    }

    // Parse allowed headers  
    const headers = try parseAllowedHeaders(response.header_list);
    const unsafe = try getCORSUnsafeRequestHeaderNames(request.header_list);
    if (!areHeadersAllowed(unsafe, headers, request.credentials_mode)) {
        return error.HeaderNotAllowed;
    }
}
```

