## File: src/csp/matching.zig

### Main Matching Algorithm

```zig
const std = @import("std");
const types = @import("types.zig");

/// Check if a URL matches a source list.
/// Spec: CSP Level 3 § 6.7.2.1
pub fn doesUrlMatchSourceList(
    url: anytype,
    source_list: *const types.SourceList,
    self_origin: ?anytype,
    redirect_count: u32,
) bool {
    // If source list is empty, nothing matches
    if (source_list.expressions.items.len == 0) {
        return false;
    }

    // Check for 'none' - nothing matches 'none'
    if (source_list.isNone()) {
        return false;
    }

    // Check each expression
    for (source_list.expressions.items) |expr| {
        if (doesUrlMatchExpression(url, &expr, self_origin, redirect_count)) {
            return true;
        }
    }

    return false;
}

/// Check if a URL matches a single source expression.
/// Spec: CSP Level 3 § 6.7.2.8
pub fn doesUrlMatchExpression(
    url: anytype,
    expr: *const types.SourceExpression,
    self_origin: ?anytype,
    redirect_count: u32,
) bool {
    switch (expr.type) {
        .keyword_none => return false,

        .keyword_self => {
            if (self_origin) |origin| {
                return doesUrlMatchOrigin(url, origin);
            }
            return false;
        },

        .scheme => {
            return doesUrlMatchScheme(url, expr.scheme_part.?);
        },

        .host => {
            return doesUrlMatchHost(url, expr, self_origin, redirect_count);
        },

        // Keywords like 'unsafe-inline', 'unsafe-eval' don't match URLs
        // They're checked separately for inline/eval contexts
        .keyword_unsafe_inline,
        .keyword_unsafe_eval,
        .keyword_unsafe_hashes,
        .keyword_strict_dynamic,
        .keyword_wasm_unsafe_eval,
        .keyword_report_sample,
        .keyword_trusted_types_eval => return false,

        // Nonce and hash are checked separately
        .nonce, .hash => return false,
    }
}

/// Check if URL's scheme matches scheme source.
/// Spec: CSP Level 3 § 6.7.2.3
fn doesUrlMatchScheme(url: anytype, scheme_expr: []const u8) bool {
    const url_scheme = url.scheme;

    // Remove trailing : from scheme expression if present
    const expr_scheme = if (scheme_expr.len > 0 and scheme_expr[scheme_expr.len - 1] == ':')
        scheme_expr[0..scheme_expr.len - 1]
    else
        scheme_expr;

    // Case-insensitive comparison
    if (std.ascii.eqlIgnoreCase(url_scheme, expr_scheme)) {
        return true;
    }

    // http: also matches https:
    if (std.ascii.eqlIgnoreCase(expr_scheme, "http") and
        std.ascii.eqlIgnoreCase(url_scheme, "https")) {
        return true;
    }

    // ws: also matches wss:
    if (std.ascii.eqlIgnoreCase(expr_scheme, "ws") and
        std.ascii.eqlIgnoreCase(url_scheme, "wss")) {
        return true;
    }

    return false;
}

/// Check if URL matches 'self' (same origin).
fn doesUrlMatchOrigin(url: anytype, origin: anytype) bool {
    const url_origin = url.origin();

    // Compare scheme, host, port
    if (!std.ascii.eqlIgnoreCase(url_origin.scheme, origin.scheme)) {
        return false;
    }

    if (!std.ascii.eqlIgnoreCase(url_origin.host, origin.host)) {
        return false;
    }

    // Port comparison (consider default ports)
    const url_port = url_origin.port orelse getDefaultPort(url_origin.scheme);
    const origin_port = origin.port orelse getDefaultPort(origin.scheme);

    return url_port == origin_port;
}

/// Check if URL matches a host source expression.
/// Spec: CSP Level 3 § 6.7.2.5-6.7.2.8
fn doesUrlMatchHost(
    url: anytype,
    expr: *const types.SourceExpression,
    self_origin: ?anytype,
    redirect_count: u32,
) bool {
    _ = redirect_count; // Used for path matching relaxation

    // If expression has scheme, it must match
    if (expr.scheme_part) |scheme| {
        if (!doesUrlMatchScheme(url, scheme)) {
            return false;
        }
    } else {
        // No scheme in expression - use self-origin's scheme or default rules
        // http: and https: are acceptable, ws: and wss: are acceptable
        const url_scheme = url.scheme;
        if (!std.ascii.eqlIgnoreCase(url_scheme, "http") and
            !std.ascii.eqlIgnoreCase(url_scheme, "https") and
            !std.ascii.eqlIgnoreCase(url_scheme, "ws") and
            !std.ascii.eqlIgnoreCase(url_scheme, "wss")) {
            // For other schemes, must match self-origin scheme
            if (self_origin) |origin| {
                if (!std.ascii.eqlIgnoreCase(url_scheme, origin.scheme)) {
                    return false;
                }
            } else {
                return false;
            }
        }
    }

    // Host matching
    if (expr.host_part) |host_expr| {
        const url_host = url.host;

        // Wildcard host (*.example.com)
        if (host_expr.len > 2 and host_expr[0] == '*' and host_expr[1] == '.') {
            const suffix = host_expr[1..]; // .example.com
            if (!std.mem.endsWith(u8, url_host, suffix)) {
                return false;
            }
            // Ensure it's a subdomain, not just suffix match
            if (url_host.len == suffix.len - 1) {
                return false; // Can't match just "example.com"
            }
        } else {
            // Exact host match (case-insensitive)
            if (!std.ascii.eqlIgnoreCase(url_host, host_expr)) {
                return false;
            }
        }
    }

    // Port matching
    if (expr.port_part) |expr_port| {
        const url_port = url.port orelse getDefaultPort(url.scheme);
        if (url_port != expr_port) {
            return false;
        }
    }

    // Path matching (simplified - full implementation is complex)
    if (expr.path_part) |path_expr| {
        const url_path = url.path;
        if (!std.mem.startsWith(u8, url_path, path_expr)) {
            return false;
        }
    }

    return true;
}

/// Check if nonce matches.
pub fn doesNonceMatch(
    nonce: []const u8,
    source_list: *const types.SourceList,
) bool {
    for (source_list.expressions.items) |expr| {
        if (expr.type == .nonce) {
            if (expr.nonce_value) |expr_nonce| {
                if (std.mem.eql(u8, nonce, expr_nonce)) {
                    return true;
                }
            }
        }
    }
    return false;
}

/// Check if hash matches.
pub fn doesHashMatch(
    hash_algorithm: []const u8,
    hash_value: []const u8,
    source_list: *const types.SourceList,
) bool {
    for (source_list.expressions.items) |expr| {
        if (expr.type == .hash) {
            if (expr.hash_algorithm) |algo| {
                if (expr.hash_value) |value| {
                    if (std.ascii.eqlIgnoreCase(algo, hash_algorithm) and
                        std.mem.eql(u8, value, hash_value)) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}

/// Get default port for scheme.
fn getDefaultPort(scheme: []const u8) ?u16 {
    if (std.ascii.eqlIgnoreCase(scheme, "http") or
        std.ascii.eqlIgnoreCase(scheme, "ws")) {
        return 80;
    }
    if (std.ascii.eqlIgnoreCase(scheme, "https") or
        std.ascii.eqlIgnoreCase(scheme, "wss")) {
        return 443;
    }
    if (std.ascii.eqlIgnoreCase(scheme, "ftp")) {
        return 21;
    }
    return null;
}
```

## Key Matching Rules

1. **'none'** - Nothing matches
2. **'self'** - Same origin as document
3. **Scheme upgrade** - http: matches https:, ws: matches wss:
4. **Wildcard hosts** - *.example.com matches subdomains
5. **Port defaulting** - Use default port if not specified
6. **Path matching** - Path prefix matching (with complexity for redirects)

