/// Header guard controls what operations are allowed on a Headers object.
/// 
/// - immutable: No modifications allowed (used for Response headers in certain contexts)
/// - request: Forbids forbidden request-headers
/// - request-no-cors: Only allows no-CORS-safelisted request-headers
/// - response: Forbids forbidden response-headers
/// - none: No restrictions (default)
pub const HeaderGuard = enum {
    immutable,
    request,
    request_no_cors,
    response,
    none,
};
```

### Validation Functions
```zig
/// Check if appending (name, value) is allowed under guard.
/// 
/// Algorithm (append):
/// 1. If guard is immutable, return false
/// 2. If guard is request and (name, value) is forbidden request-header, return false
/// 3. If guard is request-no-cors:
///    a. Let temporaryValue = get(name) from headers
///    b. If temporaryValue is null, set to value
///    c. Else set to temporaryValue + ", " + value
///    d. If (name, temporaryValue) is NOT no-CORS-safelisted, return false
/// 4. If guard is response and name is forbidden response-header, return false
/// 5. Return true
pub fn canAppend(
    guard: HeaderGuard, 
    headers: *HeaderList,
    name: []const u8, 
    value: []const u8
) bool

/// Check if setting (name, value) is allowed under guard.
/// Similar to canAppend but doesn't consider existing values.
pub fn canSet(guard: HeaderGuard, name: []const u8, value: []const u8) bool

/// Check if deleting name is allowed under guard.
///
/// Algorithm:
/// 1. If guard is immutable, return false
/// 2. If guard is request and name is forbidden request-header name, return false
/// 3. If guard is request-no-cors:
///    a. If name is not no-CORS-safelisted request-header name, return true (allow delete)
///    b. If name is no-CORS-safelisted, check if removing it would leave headers valid
/// 4. If guard is response and name is forbidden response-header, return false
/// 5. Return true
pub fn canDelete(
    guard: HeaderGuard,
    headers: *HeaderList, 
    name: []const u8
) bool
```

### Integration with Headers Interface
The guard mode is stored in the Headers object's internal state and checked before each mutation operation.

```zig
// Example usage in Headers impl:
pub fn append(self: *Headers, name: []const u8, value: []const u8) !void {
    // Validate name and value format first
    if (!validation.isValidHeaderName(name)) return error.TypeError;
    if (!validation.isValidHeaderValue(value)) return error.TypeError;

    // Normalize value
    const normalized = parsing.trimHttpWhitespace(value);

    // Check guard
    if (!guards.canAppend(self.guard, &self.list, name, normalized)) {
        return error.TypeError;
    }

    // Perform append
    try self.list.append(name, normalized);
}
```

### Guard Assignment Rules
- Headers created via constructor: guard = "none"
- Headers from Request constructor: guard = "request"
- Headers from Request constructor with mode="no-cors": guard = "request-no-cors"
- Headers from Response constructor: guard = "response"
- Headers from Response.error()/redirect()/json(): guard = "immutable"

