## Summary

Implement the send buffer and message queuing system for WebSocket. This tracks bufferedAmount and handles the case when data cannot be sent immediately.

## Specification Reference

### WHATWG WebSockets - bufferedAmount

> The bufferedAmount getter steps are to return the number of bytes of 
> application data that have been queued using send() but that... had not 
> yet been transmitted to the network.

The spec also says:
> If the data cannot be sent, e.g. because it would need to be buffered 
> but the buffer is full, the user agent must flag the WebSocket as full 
> and then close the WebSocket connection.

## Implementation Details

### File: src/websocket/connection/buffer.zig

```zig
const std = @import("std");
const Opcode = @import("../protocol/opcodes.zig").Opcode;

/// Maximum buffer size before we "flag as full" and close
pub const MAX_BUFFER_SIZE: usize = 16 * 1024 * 1024; // 16 MB

/// A queued message waiting to be sent
pub const QueuedMessage = struct {
    /// Frame opcode (text or binary)
    opcode: Opcode,
    /// Message data (owned by the queue)
    data: []u8,
    /// Offset into data for partial sends
    sent_offset: usize = 0,

    pub fn remainingBytes(self: QueuedMessage) usize {
        return self.data.len - self.sent_offset;
    }
};

/// Send buffer for managing outgoing WebSocket messages
pub const SendBuffer = struct {
    /// Queued messages
    queue: std.DoublyLinkedList(QueuedMessage),

    /// Pool for queue nodes
    node_pool: std.heap.MemoryPool(std.DoublyLinkedList(QueuedMessage).Node),

    /// Total bytes currently queued (the bufferedAmount)
    buffered_amount: u64,

    /// Allocator for message data
    allocator: std.mem.Allocator,

    /// Maximum buffer size (0 = unlimited)
    max_size: usize,

    /// Flag indicating buffer is full
    is_full: bool,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, max_size: usize) Self {
        return .{
            .queue = .{},
            .node_pool = std.heap.MemoryPool(std.DoublyLinkedList(QueuedMessage).Node).init(allocator),
            .buffered_amount = 0,
            .allocator = allocator,
            .max_size = if (max_size == 0) MAX_BUFFER_SIZE else max_size,
            .is_full = false,
        };
    }

    pub fn deinit(self: *Self) void {
        // Free all queued message data
        while (self.queue.popFirst()) |node| {
            self.allocator.free(node.data.data);
            self.node_pool.destroy(node);
        }
        self.node_pool.deinit();
    }

    /// Queue a message for sending
    /// Returns error.BufferFull if buffer would exceed max size
    pub fn queueMessage(self: *Self, opcode: Opcode, data: []const u8) !void {
        // Check if adding this would exceed max
        if (self.buffered_amount + data.len > self.max_size) {
            self.is_full = true;
            return error.BufferFull;
        }

        // Copy data (we own it until sent)
        const owned_data = try self.allocator.dupe(u8, data);
        errdefer self.allocator.free(owned_data);

        // Create node
        const node = try self.node_pool.create();
        node.data = .{
            .opcode = opcode,
            .data = owned_data,
        };

        // Add to queue
        self.queue.append(node);
        self.buffered_amount += data.len;
    }

    /// Get the next message to send (or null if empty)
    pub fn peekNext(self: *Self) ?*QueuedMessage {
        if (self.queue.first) |node| {
            return &node.data;
        }
        return null;
    }

    /// Mark bytes as sent, potentially removing completed message
    pub fn markSent(self: *Self, bytes: usize) void {
        var remaining = bytes;

        while (remaining > 0) {
            const node = self.queue.first orelse break;
            const msg = &node.data;

            const can_mark = @min(remaining, msg.remainingBytes());
            msg.sent_offset += can_mark;
            self.buffered_amount -= can_mark;
            remaining -= can_mark;

            // If message fully sent, remove it
            if (msg.sent_offset >= msg.data.len) {
                self.allocator.free(msg.data);
                self.queue.remove(node);
                self.node_pool.destroy(node);
            }
        }
    }

    /// Check if there are messages waiting to be sent
    pub fn hasPending(self: *Self) bool {
        return self.queue.first != null;
    }

    /// Get current buffered amount
    pub fn getBufferedAmount(self: *Self) u64 {
        return self.buffered_amount;
    }

    /// Check if buffer is flagged as full
    pub fn isFull(self: *Self) bool {
        return self.is_full;
    }

    /// Clear the full flag (after recovery or close)
    pub fn clearFullFlag(self: *Self) void {
        self.is_full = false;
    }
};

/// Queue a text message (validates UTF-8)
pub fn queueTextMessage(buffer: *SendBuffer, text: []const u8) !void {
    // Per spec, text must be valid UTF-8
    if (!std.unicode.utf8ValidateSlice(text)) {
        return error.InvalidUtf8;
    }
    try buffer.queueMessage(.text, text);
}

/// Queue a binary message
pub fn queueBinaryMessage(buffer: *SendBuffer, data: []const u8) !void {
    try buffer.queueMessage(.binary, data);
}

/// Calculate UTF-8 byte length for bufferedAmount tracking
/// Per WHATWG spec: "increase the bufferedAmount by the number of bytes 
/// needed to express the argument as UTF-8"
pub fn utf8ByteLength(text: []const u8) usize {
    // Input is already UTF-8 encoded
    return text.len;
}
