const std = @import("std");

/// Validate that a byte slice is valid UTF-8
/// Per RFC 6455 Section 8.1
pub fn isValidUtf8(data: []const u8) bool {
    return std.unicode.utf8ValidateSlice(data);
}

/// Validate UTF-8 with partial sequence detection
/// For streaming validation where the final bytes might be incomplete
pub const Utf8Validator = struct {
    /// Bytes of incomplete sequence from previous chunk
    pending: [4]u8 = undefined,
    pending_len: u3 = 0,
    /// Whether validation has failed
    failed: bool = false,

    const Self = @This();

    /// Validate a chunk of data
    /// Returns true if valid so far, false if invalid
    pub fn validate(self: *Self, data: []const u8) bool {
        if (self.failed) return false;

        var i: usize = 0;

        // First, try to complete any pending sequence
        if (self.pending_len > 0) {
            const needed = utf8SequenceLength(self.pending[0]) - self.pending_len;
            if (data.len < needed) {
                // Still not enough bytes
                @memcpy(self.pending[self.pending_len..][0..data.len], data);
                self.pending_len += @truncate(data.len);
                return true;
            }

            // Complete the sequence
            @memcpy(self.pending[self.pending_len..][0..needed], data[0..needed]);

            // Validate completed sequence
            if (!isValidUtf8Sequence(self.pending[0 .. self.pending_len + needed])) {
                self.failed = true;
                return false;
            }

            self.pending_len = 0;
            i = needed;
        }

        // Validate complete sequences in the chunk
        while (i < data.len) {
            const seq_len = utf8SequenceLength(data[i]);

            if (i + seq_len > data.len) {
                // Incomplete sequence at end - save for next chunk
                const remaining = data.len - i;
                @memcpy(self.pending[0..remaining], data[i..]);
                self.pending_len = @truncate(remaining);
                return true;
            }

            // Validate the sequence
            if (!isValidUtf8Sequence(data[i..][0..seq_len])) {
                self.failed = true;
                return false;
            }

            i += seq_len;
        }

        return true;
    }

    /// Finalize validation - checks for incomplete sequences
    pub fn finalize(self: *Self) bool {
        if (self.failed) return false;
        if (self.pending_len > 0) {
            // Incomplete sequence at end of stream
            self.failed = true;
            return false;
        }
        return true;
    }

    /// Reset the validator for reuse
    pub fn reset(self: *Self) void {
        self.pending_len = 0;
        self.failed = false;
    }
};

/// Get the expected length of a UTF-8 sequence from its first byte
fn utf8SequenceLength(first_byte: u8) u3 {
    if (first_byte < 0x80) return 1;
    if (first_byte < 0xC0) return 1; // Invalid, but return 1 to advance
    if (first_byte < 0xE0) return 2;
    if (first_byte < 0xF0) return 3;
    if (first_byte < 0xF8) return 4;
    return 1; // Invalid
}

/// Validate a complete UTF-8 sequence
fn isValidUtf8Sequence(seq: []const u8) bool {
    var it = std.unicode.Utf8Iterator{ .bytes = seq, .i = 0 };
    _ = it.nextCodepoint() orelse return false;
    return it.i == seq.len;
}

/// Validate and get the UTF-8 byte length for bufferedAmount
/// Per WHATWG spec: "increase bufferedAmount by the number of bytes 
/// needed to express the argument as UTF-8"
pub fn utf8ByteLength(text: []const u8) usize {
    // Input is already UTF-8, so length is just the byte length
    return text.len;
}
