### Integration with Frame Processing

```zig
// In state_machine.zig

fn handleDataFrame(self: *Self, frame: FrameHeader, payload: []const u8) !StateEvent {
    if (frame.opcode == .text) {
        // Validate UTF-8 for text frames
        if (!utf8.isValidUtf8(payload)) {
            // Fail with code 1007
            self.close_code = .invalid_payload_data;
            return error.InvalidUtf8;
        }
    }

    if (frame.fin) {
        return .{ .message = .{
            .data = payload,
            .is_text = frame.opcode == .text,
        }};
    } else {
        // Start fragmented message with validator
        self.fragment_opcode = frame.opcode;
        if (frame.opcode == .text) {
            self.utf8_validator = Utf8Validator{};
            if (!self.utf8_validator.validate(payload)) {
                self.close_code = .invalid_payload_data;
                return error.InvalidUtf8;
            }
        }
        try self.fragment_buffer.appendSlice(payload);
        return null;
    }
}

fn handleContinuation(self: *Self, frame: FrameHeader, payload: []const u8) !StateEvent {
    // Validate UTF-8 incrementally for text messages
    if (self.fragment_opcode == .text) {
        if (!self.utf8_validator.validate(payload)) {
            self.close_code = .invalid_payload_data;
            return error.InvalidUtf8;
        }
    }

    try self.fragment_buffer.appendSlice(payload);

    if (frame.fin) {
        // Finalize UTF-8 validation
        if (self.fragment_opcode == .text) {
            if (!self.utf8_validator.finalize()) {
                self.close_code = .invalid_payload_data;
                return error.InvalidUtf8;
            }
        }

        const data = try self.fragment_buffer.toOwnedSlice();
        const is_text = self.fragment_opcode == .text;
        self.fragment_opcode = null;

        return .{ .message = .{
            .data = data,
            .is_text = is_text,
        }};
    }

    return null;
}
