```zig
const std = @import("std");
const Transport = @import("network/transport.zig").Transport;
const handshake = @import("protocol/handshake.zig");

/// Handshake result on success
pub const HandshakeResult = struct {
    /// Negotiated subprotocol (or null if none)
    protocol: ?[]const u8,
    /// Negotiated extensions (or null if none)
    extensions: ?[]const u8,
    /// The underlying transport (now upgraded)
    transport: Transport,
};

pub const HandshakeError = error{
    /// HTTP status was not 101 Switching Protocols
    NotSwitchingProtocols,
    /// Missing required response header
    MissingHeader,
    /// Sec-WebSocket-Accept validation failed
    InvalidAccept,
    /// Server selected protocol we didn't request
    InvalidProtocol,
    /// Server sent malformed response
    MalformedResponse,
    /// Connection failed
    ConnectionFailed,
    /// Response too large
    ResponseTooLarge,
};

/// Configuration for WebSocket handshake
pub const HandshakeConfig = struct {
    /// Target URL (ws:// or wss://)
    url: Url,
    /// Requested subprotocols
    protocols: []const []const u8 = &.{},
    /// Additional headers to send
    extra_headers: []const Header = &.{},
    /// Origin header value
    origin: ?[]const u8 = null,
};

pub const Header = struct {
    name: []const u8,
    value: []const u8,
};

/// Perform WebSocket handshake over an established transport
pub fn performHandshake(
    allocator: std.mem.Allocator,
    transport: Transport,
    config: HandshakeConfig,
) !HandshakeResult {
    // Generate Sec-WebSocket-Key
    const key = handshake.generateSecWebSocketKey();

    // Build HTTP request
    var request = std.ArrayList(u8).init(allocator);
    defer request.deinit();

    try buildHandshakeRequest(&request, config, &key);

    // Send request
    try transport.writeAll(request.items);

    // Read response
    var response_buffer: [8192]u8 = undefined;
    const response_len = try readHttpResponse(transport, &response_buffer);
    const response = response_buffer[0..response_len];

    // Parse and validate response
    return try validateHandshakeResponse(allocator, response, &key, config.protocols);
}

fn buildHandshakeRequest(
    request: *std.ArrayList(u8),
    config: HandshakeConfig,
    key: *const [24]u8,
) !void {
    const writer = request.writer();

    // Request line
    try writer.print("GET {s} HTTP/1.1\r\n", .{config.url.path orelse "/"});

    // Required headers
    try writer.print("Host: {s}", .{config.url.host});
    if (config.url.port) |port| {
        try writer.print(":{d}", .{port});
    }
    try writer.writeAll("\r\n");

    try writer.writeAll("Upgrade: websocket\r\n");
    try writer.writeAll("Connection: Upgrade\r\n");
    try writer.print("Sec-WebSocket-Key: {s}\r\n", .{key});
    try writer.writeAll("Sec-WebSocket-Version: 13\r\n");

    // Subprotocols
    if (config.protocols.len > 0) {
        try writer.writeAll("Sec-WebSocket-Protocol: ");
        for (config.protocols, 0..) |proto, i| {
            if (i > 0) try writer.writeAll(", ");
            try writer.writeAll(proto);
        }
        try writer.writeAll("\r\n");
    }

    // Extensions (permessage-deflate)
    try writer.writeAll("Sec-WebSocket-Extensions: permessage-deflate; client_max_window_bits\r\n");

    // Origin
    if (config.origin) |origin| {
        try writer.print("Origin: {s}\r\n", .{origin});
    }

    // Extra headers
    for (config.extra_headers) |header| {
        try writer.print("{s}: {s}\r\n", .{ header.name, header.value });
    }

    // End of headers
    try writer.writeAll("\r\n");
}

fn readHttpResponse(transport: Transport, buffer: []u8) !usize {
    var total: usize = 0;

    while (total < buffer.len) {
        const n = try transport.read(buffer[total..]);
        if (n == 0) return error.ConnectionFailed;
        total += n;

        // Check for end of headers
        if (std.mem.indexOf(u8, buffer[0..total], "\r\n\r\n")) |_| {
            return total;
        }
    }

    return error.ResponseTooLarge;
}

fn validateHandshakeResponse(
    allocator: std.mem.Allocator,
    response: []const u8,
    client_key: *const [24]u8,
    requested_protocols: []const []const u8,
) !HandshakeResult {
    // Parse status line
    const status_end = std.mem.indexOf(u8, response, "\r\n") orelse 
        return error.MalformedResponse;
    const status_line = response[0..status_end];

    // Check for 101 Switching Protocols
    if (!std.mem.containsAtLeast(u8, status_line, 1, "101")) {
        return error.NotSwitchingProtocols;
    }

    // Parse headers
    const headers_start = status_end + 2;
    const headers_end = std.mem.indexOf(u8, response[headers_start..], "\r\n\r\n") orelse
        return error.MalformedResponse;

    var headers = HttpHeaderIterator.init(response[headers_start..][0..headers_end]);

    var accept: ?[]const u8 = null;
    var protocol: ?[]const u8 = null;
    var extensions: ?[]const u8 = null;
    var upgrade_seen = false;
    var connection_upgrade = false;

    while (headers.next()) |header| {
        if (std.ascii.eqlIgnoreCase(header.name, "Sec-WebSocket-Accept")) {
            accept = header.value;
        } else if (std.ascii.eqlIgnoreCase(header.name, "Sec-WebSocket-Protocol")) {
            protocol = header.value;
        } else if (std.ascii.eqlIgnoreCase(header.name, "Sec-WebSocket-Extensions")) {
            extensions = header.value;
        } else if (std.ascii.eqlIgnoreCase(header.name, "Upgrade")) {
            upgrade_seen = std.ascii.eqlIgnoreCase(header.value, "websocket");
        } else if (std.ascii.eqlIgnoreCase(header.name, "Connection")) {
            connection_upgrade = std.ascii.indexOfIgnoreCase(header.value, "upgrade") != null;
        }
    }

    // Validate required headers
    if (!upgrade_seen or !connection_upgrade) {
        return error.MissingHeader;
    }

    // Validate Sec-WebSocket-Accept
    if (accept == null) {
        return error.MissingHeader;
    }
    if (!handshake.validateSecWebSocketAccept(client_key, accept.?)) {
        return error.InvalidAccept;
    }

    // Validate protocol
    if (requested_protocols.len > 0 and protocol != null) {
        var valid = false;
        for (requested_protocols) |req| {
            if (std.mem.eql(u8, req, protocol.?)) {
                valid = true;
                break;
            }
        }
        if (!valid) return error.InvalidProtocol;
    }

    return .{
        .protocol = if (protocol) |p| try allocator.dupe(u8, p) else null,
        .extensions = if (extensions) |e| try allocator.dupe(u8, e) else null,
        .transport = transport,
    };
}

/// Simple HTTP header iterator
const HttpHeaderIterator = struct {
    data: []const u8,
    pos: usize = 0,

    pub fn init(data: []const u8) HttpHeaderIterator {
        return .{ .data = data };
    }

    pub fn next(self: *HttpHeaderIterator) ?Header {
        if (self.pos >= self.data.len) return null;

        const line_end = std.mem.indexOf(u8, self.data[self.pos..], "\r\n") orelse 
            self.data.len - self.pos;
        const line = self.data[self.pos..][0..line_end];
        self.pos += line_end + 2;

        const colon = std.mem.indexOf(u8, line, ":") orelse return self.next();

        return .{
            .name = std.mem.trim(u8, line[0..colon], " "),
            .value = std.mem.trim(u8, line[colon + 1..], " "),
        };
    }
};
