This is a large, complex algorithm. Key steps:

```zig
/// Main fetch algorithm.
///
/// This is the core orchestration algorithm that:
/// 1. Handles service worker interception
/// 2. Processes recursive flag for redirects
/// 3. Dispatches to scheme fetch
/// 4. Processes response (filtering, timing)
/// 5. Handles early hints (103)
/// 6. Queues response processing
pub fn mainFetch(
    allocator: std.mem.Allocator,
    fetch_params: *FetchParams,
    recursive: bool,
    network_backend: *NetworkBackend,
    cache_backend: *CacheBackend,
    sw_controller: *ServiceWorkerController,
) !*InternalResponse {
    // Step 1: Let request be fetchParams's request
    const request = fetch_params.request;

    // Step 2: Let response be null
    var response: ?*InternalResponse = null;

    // Step 3: If request's local-URLs-only flag is set and request's current URL is not local
    if (request.local_urls_only and !isLocalUrl(request.currentUrl())) {
        response = try InternalResponse.networkError(allocator);
    }

    // Step 4: Run report Content Security Policy violations (stub)
    // TODO(csp-spec): Implement CSP violation reporting

    // Step 5: Upgrade mixed content request
    // TODO(mixed-content-spec): Implement mixed content upgrading

    // Step 6: If should block due to bad port
    if (response == null and shouldBlockDueToBadPort(request)) {
        response = try InternalResponse.networkError(allocator);
    }

    // Step 7: If should block due to MIME type
    if (response == null and shouldBlockDueToMimeType(request)) {
        response = try InternalResponse.networkError(allocator);
    }

    // Step 8: If request's referrer policy is empty string
    if (request.referrer_policy == .empty) {
        request.referrer_policy = request.policy_container.referrer_policy;
    }

    // Step 9: If request's referrer is not "no-referrer"
    if (request.referrer != .no_referrer) {
        request.referrer = try determineRequestsReferrer(allocator, request);
    }

    // Step 10: Set request's current URL's scheme to https if upgrade
    // (handled in step 5)

    // Step 11: If recursive is false
    if (!recursive) {
        // Step 11.1: Run main fetch preparation (timing, preload, etc.)
        try mainFetchPreparation(fetch_params);
    }

    // Step 12: If response is null
    if (response == null) {
        // Step 12.1: If request's mode is "navigate" or "websocket"
        // (special handling for navigation/websocket - skip SW)

        // Step 12.2: Otherwise, if service-workers mode is "all"
        if (request.service_workers_mode == .all) {
            // Try service worker
            response = sw_controller.handleFetch(request);
        }
    }

    // Step 13: If response is null
    if (response == null) {
        // Step 13.1: Set response's request-includes-credentials
        // Step 13.2: Invoke scheme fetch
        response = try schemeFetch(allocator, fetch_params, network_backend, cache_backend);
    }

    // Step 14: If recursive is true, return response
    if (recursive) {
        return response.?;
    }

    // Step 15: If response is not network error
    if (!response.?.isNetworkError()) {
        // Step 15.1: If request's response tainting is "cors"
        if (request.response_tainting == .cors) {
            // Create CORS filtered response
            response = createCORSFilteredResponse(response.?);
        } else if (request.response_tainting == .basic) {
            response = createBasicFilteredResponse(response.?);
        } else if (request.response_tainting == .opaque) {
            response = createOpaqueFilteredResponse(response.?);
        }
    }

    // Step 16: Set timing info
    fetch_params.timing_info.end_time = getCurrentTime();

    // Step 17: Process response via callback
    if (fetch_params.process_response) |callback| {
        callback(response.?);
    }

    // Step 18: Process response end of body
    if (response.?.body) |body| {
        try body.fullyRead(allocator, processEndOfBody, processError, fetch_params.task_destination);
    }

    return response.?;
}
