/// Create a violation object for a blocked resource.
/// Spec: CSP Level 3 § 5.2.1
pub fn createViolation(
    allocator: std.mem.Allocator,
    global: anytype,
    policy: *const types.Policy,
    directive_name: []const u8,
    resource: types.ViolationResource,
) !types.Violation {
    return types.Violation{
        .document_uri = try getDocumentUri(allocator, global),
        .status_code = getStatusCode(global),
        .blocked_uri = resource,
        .referrer = try getReferrer(allocator, global),
        .violated_directive = try allocator.dupe(u8, directive_name),
        .effective_directive = try getEffectiveDirectiveName(allocator, policy, directive_name),
        .original_policy = try serializePolicy(allocator, policy),
        .disposition = policy.disposition,
        .source_file = null,
        .line_number = null,
        .column_number = null,
        .sample = null,
        .allocator = allocator,
    };
}

/// Create a violation for Trusted Types policy creation block.
pub fn createTrustedTypesPolicyViolation(
    allocator: std.mem.Allocator,
    global: anytype,
    policy: *const types.Policy,
    policy_name: []const u8,
) !types.Violation {
    var violation = try createViolation(
        allocator,
        global,
        policy,
        "trusted-types",
        .trusted_types_policy,
    );

    // Sample contains the policy name
    violation.sample = try allocator.dupe(u8, policy_name[0..@min(policy_name.len, 40)]);

    return violation;
}

/// Create a violation for Trusted Types sink mismatch.
pub fn createTrustedTypesSinkViolation(
    allocator: std.mem.Allocator,
    global: anytype,
    policy: *const types.Policy,
    sink: []const u8,
    value: []const u8,
) !types.Violation {
    var violation = try createViolation(
        allocator,
        global,
        policy,
        "require-trusted-types-for",
        .trusted_types_sink,
    );

    // Sample contains first 40 chars of the value
    violation.sample = try allocator.dupe(u8, value[0..@min(value.len, 40)]);

    return violation;
}

/// Report a violation.
/// Spec: CSP Level 3 § 5.3
pub fn reportViolation(
    violation: *const types.Violation,
    report_endpoints: anytype, // From report-to/report-uri directive
) !void {
    // TODO: Implement actual reporting
    // 1. Create violation report body
    // 2. Send to report endpoints
    // 3. Fire securitypolicyviolation event
    _ = violation;
    _ = report_endpoints;
}

/// Get serialized policy for violation report.
fn serializePolicy(
    allocator: std.mem.Allocator,
    policy: *const types.Policy,
) ![]const u8 {
    var result = std.ArrayList(u8).init(allocator);
    defer result.deinit();

    var first = true;
    var iter = policy.directive_set.items.iterator();
    while (iter.next()) |entry| {
        if (!first) {
            try result.appendSlice("; ");
        }
        first = false;

        try result.appendSlice(entry.key_ptr.*);

        for (entry.value_ptr.value.expressions.items) |expr| {
            try result.append(' ');
            try result.appendSlice(expr.raw_value);
        }
    }

    return try result.toOwnedSlice();
}

fn getDocumentUri(allocator: std.mem.Allocator, global: anytype) ![]const u8 {
    // Get document/worker URL
    _ = allocator;
    _ = global;
    return ""; // TODO: Implement
}

fn getStatusCode(global: anytype) u16 {
    _ = global;
    return 200; // TODO: Get actual status code
}

fn getReferrer(allocator: std.mem.Allocator, global: anytype) !?[]const u8 {
    _ = allocator;
    _ = global;
    return null; // TODO: Get referrer
}

fn getEffectiveDirectiveName(
    allocator: std.mem.Allocator,
    policy: *const types.Policy,
    directive_name: []const u8,
) ![]const u8 {
    const fallback = @import("fallback.zig");
    if (fallback.getEffectiveDirective(policy, directive_name)) |directive| {
        return try allocator.dupe(u8, directive.name);
    }
    return try allocator.dupe(u8, directive_name);
}
