Implement fixed-block slab allocator for stable I/O buffers (required by io_uring/IOCP).

**Objectives:**
- Fixed-size block allocation
- Lock-free free list
- Buffer stability guarantee
- Guard pages for debugging

**Files to Create:**
```
src/runtime/event_loop/mem/slab.zig
tests/event_loop/slab_test.zig
```

**Implementation:**

```zig
pub const SlabAllocator = struct {
    const BLOCK_SIZE = 8192; // 8KB blocks
    const BLOCKS_PER_SLAB = 256; // 256 blocks = 2MB slab

    slabs: std.ArrayList([]align(4096) u8), // Page-aligned slabs
    free_list: atomic.Value(?*Block), // Lock-free stack
    upstream_allocator: std.mem.Allocator,

    const Block = struct {
        next: ?*Block, // Intrusive link
        data: [BLOCK_SIZE]u8,
    };

    pub fn init(upstream_allocator: std.mem.Allocator) !SlabAllocator {
        var allocator = SlabAllocator{
            .slabs = std.ArrayList([]align(4096) u8).init(upstream_allocator),
            .free_list = atomic.Value(?*Block).init(null),
            .upstream_allocator = upstream_allocator,
        };

        // Allocate initial slab
        try allocator.allocateSlab();

        return allocator;
    }

    fn allocateSlab(self: *SlabAllocator) !void {
        const slab_size = BLOCKS_PER_SLAB * @sizeOf(Block);
        const slab = try self.upstream_allocator.alignedAlloc(u8, 4096, slab_size);

        // Initialize free list from this slab
        var blocks = @as([*]Block, @ptrCast(@alignCast(slab.ptr)))[0..BLOCKS_PER_SLAB];
        for (blocks) |*block| {
            self.freeBlock(block);
        }

        try self.slabs.append(slab);
    }

    pub fn acquire(self: *SlabAllocator) ![]u8 {
        // Lock-free pop from free list
        while (true) {
            const head = self.free_list.load(.Acquire) orelse {
                // Free list empty, allocate new slab
                try self.allocateSlab();
                continue;
            };

            if (self.free_list.cmpxchg(head, head.next, .Release, .Acquire)) |_| {
                // CAS failed, retry
                continue;
            }

            // Success, return block data
            return &head.data;
        }
    }

    pub fn release(self: *SlabAllocator, buffer: []u8) void {
        const block = @fieldParentPtr(Block, "data", buffer.ptr);
        self.freeBlock(block);
    }

    fn freeBlock(self: *SlabAllocator, block: *Block) void {
        // Lock-free push to free list
        while (true) {
            const head = self.free_list.load(.Acquire);
            block.next = head;

            if (self.free_list.cmpxchg(head, block, .Release, .Acquire) == null) {
                break; // Success
            }
        }
    }

    pub fn deinit(self: *SlabAllocator) void {
        for (self.slabs.items) |slab| {
            self.upstream_allocator.free(slab);
        }
        self.slabs.deinit();
    }
};
```

**Testing:**
1. Acquire/release buffers
2. Lock-free correctness (multiple threads)
3. Buffer stability (address doesn't change)
4. Slab growth
5. Performance: acquire < 100ns

