    pub fn init(allocator: Allocator, platform: *PlatformTimerBackend) TimerManager;
    pub fn deinit(self: *TimerManager) void;
};

pub const Timer = struct {
    id: u32,
    callback: TimerCallback,
    fire_time: i64,  // Absolute time in milliseconds
    interval: ?i64,  // null for setTimeout, value for setInterval
    nesting_level: u32,
    is_cancelled: bool,
