### Animation Frame Provider
```zig
pub const AnimationFrameProvider = struct {
    callbacks: ArrayList(FrameCallback),
    cancelled: AutoHashMap(u32, void),
    next_handle: u32,

    pub const FrameCallback = struct {
        handle: u32,
        callback: FrameRequestCallback,
    };

    pub fn requestAnimationFrame(
        self: *AnimationFrameProvider,
        callback: FrameRequestCallback,
    ) u32 {
        const handle = self.next_handle;
        self.next_handle += 1;
        self.callbacks.append(.{
            .handle = handle,
            .callback = callback,
        }) catch return 0;
        return handle;
    }

    pub fn cancelAnimationFrame(self: *AnimationFrameProvider, handle: u32) void {
        self.cancelled.put(handle, {}) catch {};
    }

    pub fn runCallbacks(self: *AnimationFrameProvider, timestamp: f64) void {
        // Snapshot callbacks (spec requirement)
        const to_run = self.callbacks.toOwnedSlice();
        defer self.callbacks.allocator.free(to_run);

        for (to_run) |cb| {
            if (!self.cancelled.contains(cb.handle)) {
                cb.callback(timestamp);
            }
        }

        self.cancelled.clearRetainingCapacity();
    }
};

pub const FrameRequestCallback = *const fn(f64) void;
```

### Frame Timing Backend
```zig
pub const FrameTimingBackend = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const VTable = struct {
        shouldRender: *const fn(*anyopaque) bool,
        getFrameTimestamp: *const fn(*anyopaque) f64,
        onFrameComplete: *const fn(*anyopaque) void,
    };
};

// Default: 60fps simulated
pub const SimulatedFrameTiming = struct {
    last_frame: i64,
    frame_interval: i64 = 16, // ~60fps

    fn shouldRender(ptr: *anyopaque) bool {
        const self = cast(ptr);
        const now = std.time.milliTimestamp();
        return now - self.last_frame >= self.frame_interval;
    }
};
