```zig
pub fn reportViolation(
    allocator: Allocator,
    violation: *const Violation,
    policy: *const Policy,
    global: *GlobalScope,
) !void {
    // 1. Create SecurityPolicyViolationEvent
    const event = try createSecurityPolicyViolationEvent(allocator, violation);
    defer event.deinit();

    // 2. Fire event on document/worker global
    _ = try global.dispatchEvent(event);

    // 3. If policy has report-uri, POST violation report
    if (policy.getDirective("report-uri")) |endpoints| {
        for (parseEndpoints(endpoints)) |endpoint| {
            try sendViolationReport(allocator, violation, endpoint);
        }
    }

    // 4. If policy has report-to, queue to Reporting API
    if (policy.getDirective("report-to")) |group| {
        try queueReportingAPIReport(allocator, violation, group);
    }
}
