pub fn sendViolationReport(
    allocator: Allocator,
    violation: *const Violation,
    endpoint: []const u8,
) !void {
    // 1. Serialize violation to JSON
    const json = try serializeViolationReport(allocator, violation);
    defer allocator.free(json);

    // 2. Create POST request
    var request = try fetch.Request.init(allocator, endpoint, .{
        .method = .POST,
        .headers = &.{
            .{ "Content-Type", "application/csp-report" },
        },
        .body = json,
    });
    defer request.deinit();

    // 3. Send (fire and forget, don't block)
    _ = fetch.fetch(allocator, request) catch {};
}
