pub fn enforceCSPOnDocumentLoad(
    document: *Document,
    csp_headers: []const HTTPHeader,
) !void {
    // 1. Parse CSP headers
    for (csp_headers) |header| {
        if (header.name.eql("Content-Security-Policy")) {
            const policy = try parsing.parseSerializedCSP(header.value);
            document.csp_list.append(policy);
        } else if (header.name.eql("Content-Security-Policy-Report-Only")) {
            var policy = try parsing.parseSerializedCSP(header.value);
            policy.disposition = .report;
            document.csp_list.append(policy);
        }
    }

    // 2. Check for upgrade-insecure-requests
    if (shouldUpgradeInsecureRequests(document.csp_list)) {
        document.upgrade_insecure_requests = true;
    }
}
```

