pub fn enforceCSPFromMeta(
    document: *Document,
    content: []const u8,
) !void {
    // <meta http-equiv="Content-Security-Policy" content="...">
    // Note: Some directives not allowed in meta (report-uri, frame-ancestors, sandbox)
    const policy = try parsing.parseSerializedCSP(content);

    // Validate allowed directives
    if (policy.hasDirective("report-uri") or 
        policy.hasDirective("frame-ancestors") or
