// SVG foreignObject, desc, title are HTML integration points
fn isHTMLIntegrationPoint(element: *Element) bool {
    if (element.namespace == .mathml) {
        if (mathml_text_integration_points.has(element.local_name)) {
            return true;
        }
        if (std.mem.eql(u8, element.local_name, "annotation-xml")) {
            // Check encoding attribute
            const encoding = element.getAttribute("encoding");
            if (encoding) |enc| {
                const lower = std.ascii.lowerString(enc);
                return std.mem.eql(u8, lower, "text/html") or
                       std.mem.eql(u8, lower, "application/xhtml+xml");
            }
        }
    }
    if (element.namespace == .svg) {
        return std.mem.eql(u8, element.local_name, "foreignObject") or
               std.mem.eql(u8, element.local_name, "desc") or
               std.mem.eql(u8, element.local_name, "title");
    }
    return false;
}
