## Requirements

### Fragment Parsing Algorithm
```zig
pub fn parseFragment(
    allocator: Allocator,
    context: *Element,
    html: []const u8,
    scripting_enabled: bool,
) !*DocumentFragment {
    // Per spec section 13.4

    // 1. Create a new Document node
    const document = try Document.createHTMLDocument(allocator, "");
    defer if (fragment_failed) document.deinit();

    // 2. If context is a template, set document type to "html"
    if (std.mem.eql(u8, context.local_name, "template")) {
        // Set content type
    }

    // 3. Create parser with document
    var parser = try HTMLParser.init(allocator, document);

    // 4. Set tokenizer state based on context element
    parser.tokenizer.setState(getInitialTokenizerState(context));

    // 5. Create root html element
    const root = try document.createElement("html");
    try document.appendChild(root);
    parser.open_elements.append(root);

    // 6. If context is template, push "in template" to template modes
    if (std.mem.eql(u8, context.local_name, "template")) {
        try parser.template_insertion_modes.append(.in_template);
    }

    // 7. Reset insertion mode appropriately
    parser.resetInsertionModeAppropriately(context);

    // 8. Set form element if context has form ancestor
    parser.form_element = findFormAncestor(context);

    // 9. Set scripting flag
    parser.scripting_flag = scripting_enabled;

    // 10. Parse the input
    try parser.run();

    // 11. Return the children as a DocumentFragment
    const fragment = try DocumentFragment.create(allocator, document);
    while (root.firstChild) |child| {
        try fragment.appendChild(try child.clone(true));
    }

    return fragment;
}
```

### Initial Tokenizer State Selection
```zig
fn getInitialTokenizerState(context: *Element) Tokenizer.State {
    const local_name = context.local_name;

    // Raw text elements
    if (std.mem.eql(u8, local_name, "title") or
        std.mem.eql(u8, local_name, "textarea")) {
        return .rcdata;
    }

    // RAWTEXT elements
    if (std.mem.eql(u8, local_name, "style") or
        std.mem.eql(u8, local_name, "xmp") or
        std.mem.eql(u8, local_name, "iframe") or
        std.mem.eql(u8, local_name, "noembed") or
        std.mem.eql(u8, local_name, "noframes")) {
        return .rawtext;
    }

    // Script data
    if (std.mem.eql(u8, local_name, "script")) {
        return .script_data;
    }

    // Noscript depends on scripting flag
    if (std.mem.eql(u8, local_name, "noscript")) {
        // If scripting is enabled, return rawtext
        return .rawtext; // Assuming scripting enabled by default
    }

    // Plaintext
    if (std.mem.eql(u8, local_name, "plaintext")) {
        return .plaintext;
    }

    // Default
    return .data;
}
```

### Integration with innerHTML/outerHTML
```zig
// Called by Element.set_innerHTML
pub fn parseInnerHTML(
    element: *Element,
    html: []const u8,
) !void {
    // 1. Parse as fragment
    const fragment = try parseFragment(
        element.allocator,
        element,
        html,
        element.ownerDocument.scripting_enabled,
    );
    defer fragment.deinit();

    // 2. Remove all children from element
    while (element.firstChild) |child| {
        element.removeChild(child);
    }

    // 3. Append fragment children
    try element.appendChild(fragment);
}

// Called by Element.set_outerHTML
pub fn parseOuterHTML(
    element: *Element,
    html: []const u8,
) !void {
    const parent = element.parentNode orelse return error.NoParent;

    // Use parent as context (with special handling)
    const context = if (parent.nodeType == .DOCUMENT_NODE) blk: {
        // Create a body element as context
        break :blk try element.ownerDocument.createElement("body");
    } else blk: {
        break :blk @ptrCast(*Element, parent);
    };

    const fragment = try parseFragment(
        element.allocator,
        context,
        html,
        element.ownerDocument.scripting_enabled,
    );

    // Replace element with fragment
    try parent.replaceChild(fragment, element);
}
