# Implement Pluggable Layout Backend

## Purpose
Provide abstract interface for layout engine, allowing embedders to plug in their renderer.

## Location
`src/platform/layout_backend.zig`

## Requirements

### Abstract Interface
```zig
pub const LayoutBackend = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const VTable = struct {
        // Computed styles
        getComputedStyle: *const fn(*anyopaque, element: *Element, pseudo: ?[]const u8) *CSSStyleDeclaration,

        // Box metrics
        getOffsetWidth: *const fn(*anyopaque, element: *Element) f64,
        getOffsetHeight: *const fn(*anyopaque, element: *Element) f64,
        getOffsetTop: *const fn(*anyopaque, element: *Element) f64,
        getOffsetLeft: *const fn(*anyopaque, element: *Element) f64,
        getOffsetParent: *const fn(*anyopaque, element: *Element) ?*Element,

        getClientWidth: *const fn(*anyopaque, element: *Element) f64,
        getClientHeight: *const fn(*anyopaque, element: *Element) f64,
        getClientTop: *const fn(*anyopaque, element: *Element) f64,
        getClientLeft: *const fn(*anyopaque, element: *Element) f64,

        getScrollWidth: *const fn(*anyopaque, element: *Element) f64,
        getScrollHeight: *const fn(*anyopaque, element: *Element) f64,
        getScrollTop: *const fn(*anyopaque, element: *Element) f64,
        setScrollTop: *const fn(*anyopaque, element: *Element, value: f64) void,
        getScrollLeft: *const fn(*anyopaque, element: *Element) f64,
        setScrollLeft: *const fn(*anyopaque, element: *Element, value: f64) void,

        getBoundingClientRect: *const fn(*anyopaque, element: *Element) DOMRect,
        getClientRects: *const fn(*anyopaque, element: *Element) DOMRectList,

        // Rendered text (for innerText)
        getRenderedText: *const fn(*anyopaque, element: *Element) []const u8,
        isElementRendered: *const fn(*anyopaque, element: *Element) bool,

        // Selection and caret
        getCaretRectAtPosition: *const fn(*anyopaque, node: *Node, offset: u32) ?DOMRect,

        // Dirty marking
        markDirty: *const fn(*anyopaque, element: *Element) void,

        // Force layout computation
        forceLayout: *const fn(*anyopaque) void,

        // Cleanup
        deinit: *const fn(*anyopaque, allocator: Allocator) void,
    };

    // Convenience methods
    pub fn getOffsetWidth(self: LayoutBackend, element: *Element) f64 {
        return self.vtable.getOffsetWidth(self.ptr, element);
    }
    // ... etc for all methods
};
```

### Stub Implementation (Returns Defaults)
```zig
pub const StubLayoutBackend = struct {
    allocator: Allocator,

    pub fn init(allocator: Allocator) *StubLayoutBackend {
        const self = allocator.create(StubLayoutBackend) catch unreachable;
        self.* = .{ .allocator = allocator };
        return self;
    }

    fn getOffsetWidth(_: *anyopaque, _: *Element) f64 {
        return 0;
    }

    fn getOffsetHeight(_: *anyopaque, _: *Element) f64 {
        return 0;
    }

    fn getBoundingClientRect(_: *anyopaque, _: *Element) DOMRect {
        return DOMRect.init(0, 0, 0, 0);
    }

    fn getRenderedText(_: *anyopaque, element: *Element) []const u8 {
        // Fallback: return textContent (not spec-compliant but usable)
        return element.textContent orelse "";
    }

    fn isElementRendered(_: *anyopaque, _: *Element) bool {
        return true; // Assume everything is rendered
    }

    fn getComputedStyle(_: *anyopaque, _: *Element, _: ?[]const u8) *CSSStyleDeclaration {
        // Return empty style declaration
        return &empty_style;
    }

    // ... implement all vtable functions with defaults

    pub const vtable = VTable{
        .getOffsetWidth = getOffsetWidth,
        .getOffsetHeight = getOffsetHeight,
        // ... all functions
    };

    pub fn backend(self: *StubLayoutBackend) LayoutBackend {
        return .{ .ptr = self, .vtable = &vtable };
    }
};
```

