### Frame Properties
```zig
pub fn get_frames(instance: *runtime.Instance) !typedefs.WindowProxy {
    return get_window(instance); // Same as window
}

pub fn get_length(instance: *runtime.Instance) !u32 {
    // Number of child browsing contexts
    return instance.internal.browsing_context.children.len;
}

pub fn get_top(instance: *runtime.Instance) !?typedefs.WindowProxy {
    // Top-level browsing context's WindowProxy
    var ctx = instance.internal.browsing_context;
    while (ctx.parent) |parent| {
        ctx = parent;
    }
    return ctx.window_proxy;
}

pub fn get_parent(instance: *runtime.Instance) !?typedefs.WindowProxy {
    if (instance.internal.browsing_context.parent) |parent| {
        return parent.window_proxy;
    }
    return get_window(instance); // Returns self if no parent
}

pub fn get_opener(instance: *runtime.Instance) !*const anyopaque {
    return instance.internal.opener;
}

pub fn get_frameElement(instance: *runtime.Instance) !?*runtime.Instance {
    // The iframe/frame element that contains this window
    return instance.internal.browsing_context.container_element;
}
