## Implementation

### Streaming Response Architecture
```
LibcurlBackend
    |
    v
WriteCallback (receives chunks)
    |
    v
StreamingResponseSource
    |
    v
ReadableStream (exposed to Fetch consumer)
```

### StreamingResponseSource
```zig
pub const StreamingResponseSource = struct {
    backend: *LibcurlBackend,
    buffer: std.ArrayList(u8),
    complete: bool,
    error_state: ?NetworkError,

    /// Pull callback for ReadableStream
    pub fn pull(self: *StreamingResponseSource, controller: *ReadableStreamController) !void {
        if (self.complete) {
            try controller.close();
            return;
        }

        if (self.error_state) |err| {
            try controller.error(err);
            return;
        }

        // Resume curl transfer if paused
        if (self.backend.paused) {
            _ = curl.curl_easy_pause(self.backend.handle, curl.CURLPAUSE_CONT);
            self.backend.paused = false;
        }

        // Enqueue buffered data
        if (self.buffer.items.len > 0) {
            const chunk = try self.buffer.toOwnedSlice();
            try controller.enqueue(chunk);
        }
    }

    /// Cancel callback
    pub fn cancel(self: *StreamingResponseSource) void {
        self.backend.aborted.store(true, .release);
    }
};
```

### Backpressure via curl_easy_pause
```zig
fn writeCallbackStreaming(
    data: [*]u8,
    size: usize,
    nmemb: usize,
    userdata: *anyopaque,
) callconv(.C) usize {
    const source: *StreamingResponseSource = @ptrCast(@alignCast(userdata));

    const total = size * nmemb;

    // Buffer the data
    source.buffer.appendSlice(data[0..total]) catch {
        return curl.CURL_WRITEFUNC_ERROR;
    };

    // If buffer exceeds high water mark, pause
    if (source.buffer.items.len > HIGH_WATER_MARK) {
        source.backend.paused = true;
        return curl.CURL_WRITEFUNC_PAUSE;
    }

    return total;
}
```

### Multi-threaded Transfer
For true streaming, curl_easy_perform blocks. Options:
1. Run curl in separate thread
2. Use curl_multi interface
3. Use async I/O

```zig
/// Start streaming transfer in background
pub fn startStreamingTransfer(
    backend: *LibcurlBackend,
    request: *const NetworkRequest,
) !*StreamingResponseSource {
    const source = try allocator.create(StreamingResponseSource);
    source.* = .{
        .backend = backend,
        .buffer = std.ArrayList(u8).init(allocator),
        .complete = false,
        .error_state = null,
    };

    // Configure curl for streaming
    try backend.configureRequest(request);
    _ = curl.curl_easy_setopt(backend.handle, curl.CURLOPT_WRITEDATA, source);

    // Start transfer thread
    source.transfer_thread = try std.Thread.spawn(.{}, transferThread, .{backend, source});

    return source;
}

fn transferThread(backend: *LibcurlBackend, source: *StreamingResponseSource) void {
    const result = curl.curl_easy_perform(backend.handle);

    if (result != curl.CURLE_OK) {
        source.error_state = curl_error.mapCurlError(result);
    }

    source.complete = true;
}
```

