### 4. Handle Cookies in WebSocket Constructor

Per the WebSocket spec, the constructor should:
1. Include cookies for the WebSocket URL's origin
2. Process Set-Cookie headers from the handshake response

```zig
/// WebSocket constructor implementation
/// https://websockets.spec.whatwg.org/#dom-websocket-websocket
pub fn connect(
    self: *WebSocketCurlBackend,
    url: []const u8,
    protocols: ?[]const []const u8,
) !*WebSocket {
    // Parse URL
    const parsed_url = try url_module.URL.parse(self.allocator, url);
    defer parsed_url.deinit();

    // Validate WebSocket URL
    if (!std.mem.eql(u8, parsed_url.scheme, "ws") and 
        !std.mem.eql(u8, parsed_url.scheme, "wss")) {
        return error.InvalidScheme;
    }

    // Create CURL handle for handshake
    const handle = curl.curl_easy_init() orelse return error.CurlInitFailed;
    errdefer curl.curl_easy_cleanup(handle);

    // Convert ws:// to http:// and wss:// to https:// for cookie matching
    const http_url = try self.convertToHttpUrl(url);
    defer self.allocator.free(http_url);

    // Attach cookies - use HTTP URL for proper domain matching
    if (self.cookie_manager) |manager| {
        manager.attachToHandle(handle);

        // Get cookies that would be sent
        // This is informational - libcurl will handle actual sending
        var cookies = try manager.getAll(null, http_url);
        defer {
            for (cookies.items) |*c| c.deinit();
            cookies.deinit();
        }

        if (cookies.items.len > 0) {
            // Log or track that cookies are being sent
            std.log.debug("WebSocket handshake sending {d} cookies", .{cookies.items.len});
        }
    }

    // Perform WebSocket handshake
    try self.performHandshake(handle, url, protocols);

    // Create WebSocket instance
    const ws = try self.allocator.create(WebSocket);
    ws.* = .{
        .handle = handle,
        .state = .connecting,
        // ...
    };

    return ws;
}

fn convertToHttpUrl(self: *WebSocketCurlBackend, ws_url: []const u8) ![]u8 {
    _ = self;
    // ws:// -> http://
    // wss:// -> https://
    if (std.mem.startsWith(u8, ws_url, "wss://")) {
        var result = try self.allocator.alloc(u8, ws_url.len);
        @memcpy(result[0..6], "https:");
        @memcpy(result[6..], ws_url[5..]);
        return result;
    } else if (std.mem.startsWith(u8, ws_url, "ws://")) {
        var result = try self.allocator.alloc(u8, ws_url.len + 1);
        @memcpy(result[0..5], "http:");
        @memcpy(result[5..], ws_url[4..]);
        return result;
    }
    return error.InvalidWebSocketUrl;
}
```

