//! Mock HTML Policy Container for Fetch
//!
//! TODO(html-spec): Replace this mock with real policy container implementation
//! when the HTML specification is implemented.
//! See: https://html.spec.whatwg.org/#policy-container
//!
//! A policy container contains policies that apply to a Document, WorkerGlobalScope,
//! or WorkletGlobalScope. For Fetch, we primarily need:
//! - Referrer policy (for Referer header)
//! - Embedder policy (for COEP/credentials checks)
//! - CSP list (for blocking checks - stubbed for now)

const std = @import("std");
const ReferrerPolicy = @import("referrer_policy").ReferrerPolicy;

/// Mock policy container.
pub const PolicyContainer = struct {
    allocator: std.mem.Allocator,

    /// Referrer policy for this container.
    /// Used to determine Referer header value.
    referrer_policy: ReferrerPolicy = .strict_origin_when_cross_origin,

    /// Embedder policy.
    embedder_policy: EmbedderPolicy = .{},

    /// CSP list (stubbed - just tracks if any CSP exists)
    /// TODO(csp-spec): Replace with real CSP list when CSP is implemented
