    pub fn init(allocator: std.mem.Allocator) PolicyContainer {
        return .{
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *PolicyContainer) void {
        _ = self;
        // Currently no allocations to free
    }

    /// Clone the policy container.
    pub fn clone(self: *PolicyContainer, allocator: std.mem.Allocator) !PolicyContainer {
        return .{
            .allocator = allocator,
            .referrer_policy = self.referrer_policy,
            .embedder_policy = self.embedder_policy,
            .csp_list = self.csp_list,
        };
    }
};
