### Policy Container Operations
```zig
/// Create a new policy container with default policies.
pub fn createDefault(allocator: std.mem.Allocator) PolicyContainer {
    return PolicyContainer.init(allocator);
}

/// Create a policy container from response headers.
/// Parses Referrer-Policy and Cross-Origin-Embedder-Policy headers.
pub fn createFromHeaders(
    allocator: std.mem.Allocator,
    headers: *HeaderList,
) PolicyContainer {
    var container = PolicyContainer.init(allocator);

    // Parse Referrer-Policy header
    if (headers.get("Referrer-Policy")) |value| {
        if (ReferrerPolicy.parse(value)) |policy| {
            container.referrer_policy = policy;
        }
    }

    // Parse Cross-Origin-Embedder-Policy header
    if (headers.get("Cross-Origin-Embedder-Policy")) |value| {
        container.embedder_policy = parseCoep(value);
    }

    return container;
}

fn parseCoep(value: []const u8) EmbedderPolicy {
    if (std.mem.eql(u8, value, "require-corp")) {
        return .{ .value = .require_corp };
    } else if (std.mem.eql(u8, value, "credentialless")) {
        return .{ .value = .credentialless };
    }
    return .{};
}
