/// Options for setting a cookie
/// Matches CookieInit dictionary from CookieStore API spec
pub const CookieInit = struct {
    /// Cookie name (required)
    name: []const u8,

    /// Cookie value (required)
    value: []const u8,

    /// Domain attribute (optional, defaults to current document's domain)
    domain: ?[]const u8 = null,

    /// Path attribute (optional, defaults to "/")
    path: ?[]const u8 = null,

    /// Expiry time as Unix timestamp (null = session cookie)
    expires: ?i64 = null,

    /// Secure attribute (optional, defaults based on context)
    secure: ?bool = null,

    /// SameSite attribute (optional, defaults to "lax")
    same_site: ?Cookie.SameSite = null,

    /// Partitioned attribute (optional, for CHIPS)
    partitioned: ?bool = null,
};
