## Summary
Implement the FileReaderSync interface for synchronous file reading in Worker contexts.

## Spec Reference
- W3C File API §6.5: Reading on Threads
- https://www.w3.org/TR/FileAPI/#FileReaderSync

## WebIDL Definition
```webidl
[Exposed=(DedicatedWorker,SharedWorker)]
interface FileReaderSync {
  constructor();

  ArrayBuffer readAsArrayBuffer(Blob blob);
  DOMString readAsBinaryString(Blob blob);
  DOMString readAsText(Blob blob, optional DOMString encoding);
  DOMString readAsDataURL(Blob blob);
};
```

## Implementation Notes
- Only exposed in Worker contexts (not Window)
- Synchronous - blocks until read complete
- Simpler than FileReader (no events, no state machine)
- Throws on error instead of using error attribute

## Implementation
```zig
pub fn call_constructor(allocator: std.mem.Allocator, ctx: runtime.Context) !*runtime.Instance {
    // Simple constructor - no internal state needed
    return FileReaderSync.init(allocator, FileReaderSync.State, &FileReaderSync.vtable, ctx);
}

pub fn call_readAsArrayBuffer(instance: *runtime.Instance, blob: *runtime.Instance) !*runtime.ArrayBuffer {
    const blob_internal = Blob.getInternal(blob) orelse return error.InvalidState;

    // Synchronously read all bytes
    const bytes = blob_internal.blob_data.bytes;

    // Package as ArrayBuffer
    return runtime.ArrayBuffer.create(instance.ctx, bytes);
}

pub fn call_readAsBinaryString(instance: *runtime.Instance, blob: *runtime.Instance) !runtime.DOMString {
    const blob_internal = Blob.getInternal(blob) orelse return error.InvalidState;
    const result = try file.algorithms.packageData(
        instance.allocator, blob_internal.blob_data.bytes,
        .BinaryString, blob_internal.blob_data.getType(), null
    );
    return runtime.DOMString.fromSlice(result.BinaryString);
}

pub fn call_readAsText(instance: *runtime.Instance, blob: *runtime.Instance, encoding: ?runtime.DOMString) !runtime.DOMString {
    const blob_internal = Blob.getInternal(blob) orelse return error.InvalidState;
    const enc = if (encoding) |e| e.asSlice() else null;
    const result = try file.algorithms.packageData(
        instance.allocator, blob_internal.blob_data.bytes,
        .Text, blob_internal.blob_data.getType(), enc
    );
    return runtime.DOMString.fromSlice(result.Text);
}

pub fn call_readAsDataURL(instance: *runtime.Instance, blob: *runtime.Instance) !runtime.DOMString {
    const blob_internal = Blob.getInternal(blob) orelse return error.InvalidState;
    const result = try file.algorithms.packageData(
        instance.allocator, blob_internal.blob_data.bytes,
        .DataURL, blob_internal.blob_data.getType(), null
    );
    return runtime.DOMString.fromSlice(result.DataURL);
}
```

